INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "引擎是一种将某种能量（如燃料、电力）转化为机械动力的装置，通常用于驱动车辆、机器或设备。", "primary_collocate": null, "pronunciation": "yǐn qíng", "ipa": "in˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "引擎的作用就是产生向前的推力，帮助飞机克服阻力。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这辆车的引擎声音很大。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机有四台引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机打开车盖，检查引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天车的引擎不容易发动。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "引擎坏了，船停在海上不动了。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车引擎需要用汽油才能工作。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台引擎很新，运转得很平稳。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修好了摩托车的引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭的引擎一启动，就冒出大火。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "引擎盖", "label": "复合"}], "register": "中性", "sense_fingerprint": "把能量变成动力的机械装置，如汽车、飞机的引擎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c08b601-4318-47af-9aac-f60ca0c0c5ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎是产生动力的装置，与“产生向前的推力”的作用相符。"}, {"text": "方向盘", "is_correct": false, "explanation": "语义：方向盘只用来控制车辆的方向，不产生推力，不能说它的作用是产生向前的推力。"}, {"text": "油箱", "is_correct": false, "explanation": "语义：油箱只用来储存燃料，本身不产生推力，句子所说的作用不符。"}, {"text": "座椅", "is_correct": false, "explanation": "搭配：“产生推力”的主语必须是动力装置，座椅没有这样的功能，不能与之搭配。"}], "explanations": {"引擎": "引擎是产生动力的装置，与“产生向前的推力”的作用相符。", "方向盘": "语义：方向盘只用来控制车辆的方向，不产生推力，不能说它的作用是产生向前的推力。", "油箱": "语义：油箱只用来储存燃料，本身不产生推力，句子所说的作用不符。", "座椅": "搭配：“产生推力”的主语必须是动力装置，座椅没有这样的功能，不能与之搭配。"}, "sentence_index": 0, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣的引擎很暖和。", "explanation": "这里不能用〈引擎〉。引擎是车辆、机器的动力装置，毛衣是衣物，没有引擎。"}, {"text": "这把雨伞的引擎很结实。", "explanation": "这里不能用〈引擎〉。雨伞没有动力装置，不能说它有引擎。"}, {"text": "这张桌子的引擎很结实。", "explanation": "这里不能用〈引擎〉。桌子没有动力装置，不能说它有引擎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎靠燃料工作，与句中的“汽油”和“工作”相符。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎不靠汽油工作，句中的燃料与它无关。"}, {"text": "车灯", "is_correct": false, "explanation": "语义：车灯多靠电力工作，不需要汽油，与句意不符。"}, {"text": "后视镜", "is_correct": false, "explanation": "搭配：后视镜不说“工作”，与“需要用汽油才能工作”不搭配。"}], "explanations": {"引擎": "引擎靠燃料工作，与句中的“汽油”和“工作”相符。", "轮胎": "语义：轮胎不靠汽油工作，句中的燃料与它无关。", "车灯": "语义：车灯多靠电力工作，不需要汽油，与句意不符。", "后视镜": "搭配：后视镜不说“工作”，与“需要用汽油才能工作”不搭配。"}, "sentence_index": 6, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把菜刀的引擎很锋利。", "explanation": "这里的〈引擎〉指汽车、飞机、船等的动力装置，菜刀是手工器具，没有这类部件，不能这样说。"}, {"text": "这本字典的引擎有五百多页。", "explanation": "这里的〈引擎〉指机械的动力装置，字典是书，没有这类部件，不能说它有几页。"}, {"text": "我的旧手机换了一台新引擎。", "explanation": "这里的〈引擎〉指车辆、飞机等的动力装置，手机没有这个部件，不能说给它换引擎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆引擎需要定期保养。", "corrected_sentence": "这台引擎需要定期保养。", "error_description": "量词错误：引擎的量词是“台”，“辆”用于车辆。正确说法是“这台引擎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把引擎修了好。", "corrected_sentence": "他终于把引擎修好了。", "error_description": "补语错误：结果补语“好”应紧跟动词，应说“修好”，不能说“修了好”。正确说法是“把引擎修好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3717dacd-16c2-4e77-ab18-05ee7a9d1d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "向前推动物体或事物前进的力量。", "primary_collocate": null, "pronunciation": "tuī lì", "ipa": "tʰu̯eɪ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "引擎的作用就是产生向前的推力，帮助飞机克服阻力。", "target_word": "推力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "推力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "如果推力不够，飞机就会变慢，甚至飞不动。", "target_word": "推力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "火箭需要很大的推力才能飞上天空。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台发动机的推力很大。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船的推力来自后面的螺旋桨。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发动机停了，飞机没有推力了。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在测试新火箭的推力。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，发动机的推力要特别大。", "target_word": "推力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "推力越大，火箭飞得越快。", "target_word": "推力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "股", "label": "量词"}, {"form": "反推力", "label": "复合"}], "register": "中性", "sense_fingerprint": "发动机等产生的向前推动物体前进的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确答案：推力（tuī lì），指推动物体前进的力。"}, {"text": "推理", "is_correct": false, "explanation": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。"}, {"text": "脱力", "is_correct": false, "explanation": "脱力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是失去力气。"}, {"text": "腿力", "is_correct": false, "explanation": "腿力（tuǐ lì）与推力的第一音节声调不同（第三声与第一声），意思是腿的力气。"}], "explanations": {"推力": "正确答案：推力（tuī lì），指推动物体前进的力。", "推理": "推理（tuī lǐ）与推力的第二音节声调不同（第三声与第四声），意思是根据已知推断结论。", "脱力": "脱力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是失去力气。", "腿力": "腿力（tuǐ lì）与推力的第一音节声调不同（第三声与第一声），意思是腿的力气。"}, "sentence_index": null, "correct_answer": "推力"}, "level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确：推力是引擎产生的向前推动飞机的力，与“产生向前的”相符。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力是阻碍前进的力，与“向前”的作用相反，且与后文“克服阻力”重复。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力是地球对物体的吸引力，方向向下，不能说“产生向前的重力”。"}, {"text": "体力", "is_correct": false, "explanation": "搭配：“体力”指人或动物的力气，不用来说引擎产生力。"}], "explanations": {"推力": "正确：推力是引擎产生的向前推动飞机的力，与“产生向前的”相符。", "阻力": "语义：阻力是阻碍前进的力，与“向前”的作用相反，且与后文“克服阻力”重复。", "重力": "语义：重力是地球对物体的吸引力，方向向下，不能说“产生向前的重力”。", "体力": "搭配：“体力”指人或动物的力气，不用来说引擎产生力。"}, "sentence_index": 0, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的推力很强，能解决很难的数学问题。", "explanation": "这里应该用〈能力〉。推力指推动物体前进的力，不能用来说人解决问题的本领。"}, {"text": "这根绳子的推力很大，能把车拉过来。", "explanation": "这里应该用〈拉力〉。推力指向前推动物体的力，把车拉过来用的是拉力，不能说推力。"}, {"text": "空气的推力很大，车跑不快。", "explanation": "这里应该用〈阻力〉。推力指推动物体前进的力，阻碍车前进的是阻力，不能说推力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确答案：推力（tuī lì），指推动物体前进的力。"}, {"text": "退离", "is_correct": false, "explanation": "退离（tuì lí）与推力（tuī lì）两个音节的声调都不同（第四声与第一声，第二声与第四声），意思是退出、离开。"}, {"text": "拖力", "is_correct": false, "explanation": "拖力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是拖拉时的拉力。"}, {"text": "体例", "is_correct": false, "explanation": "体例（tǐ lì）与推力（tuī lì）的第一音节不同（tǐ 与 tuī），第二音节相同，意思是著作的编写格式。"}], "explanations": {"推力": "正确答案：推力（tuī lì），指推动物体前进的力。", "退离": "退离（tuì lí）与推力（tuī lì）两个音节的声调都不同（第四声与第一声，第二声与第四声），意思是退出、离开。", "拖力": "拖力（tuō lì）与推力的韵母不同（uo 与 ui），第一音节声调相同，意思是拖拉时的拉力。", "体例": "体例（tǐ lì）与推力（tuī lì）的第一音节不同（tǐ 与 tuī），第二音节相同，意思是著作的编写格式。"}, "sentence_index": null, "correct_answer": "推力"}, "level_3": {"options": [{"text": "推力", "is_correct": true, "explanation": "正确：发动机停了，飞机就没有推动它前进的力，与句意相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：飞机的重量不会因发动机停了而消失，“没有重量了”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：物体都有温度，“没有温度了”说不通，与发动机的状态无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或动物的重量，不用来说飞机。"}], "explanations": {"推力": "正确：发动机停了，飞机就没有推动它前进的力，与句意相符。", "重量": "语义：飞机的重量不会因发动机停了而消失，“没有重量了”说不通。", "温度": "语义：物体都有温度，“没有温度了”说不通，与发动机的状态无关。", "体重": "搭配：“体重”指人或动物的重量，不用来说飞机。"}, "sentence_index": 6, "correct_answer": "推力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的推力越来越快，一分钟就跑了一公里。", "explanation": "这里应该用〈速度〉。“越来越快”说的是速度，推力只说大小，不能说快慢。"}, {"text": "月亮对海水有推力，所以海水会涨落。", "explanation": "这里应该用〈引力〉。推力指向前推动物体的力，月亮吸引海水使其涨落的是引力，不能说推力。"}, {"text": "老师对学生很有推力，大家都很喜欢他。", "explanation": "这里应该用〈耐心〉。推力指推动物体的力，不能用来形容人的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台发动机能产生一台很大的推力。", "corrected_sentence": "这台发动机能产生一股很大的推力。", "error_description": "量词错误：推力应用量词“股”，不能用“台”（“台”用于机器等）。正确说法是“一股很大的推力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新火箭的推力比旧的大的多。", "corrected_sentence": "新火箭的推力比旧的大得多。", "error_description": "补语标记错误：程度补语应用“得”连接，不能用“的”。正确说法是“比旧的大得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
