INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12107, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12107, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用意志和行动去战胜或解决困难、缺点等。", "primary_collocate": null, "pronunciation": "kè fú", "ipa": "kʰɤ˥˩ fu˧˥", "syllable_count": 2, "sentences": [{"text": "引擎的作用就是产生向前的推力，帮助飞机克服阻力。", "target_word": "克服", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他努力克服了学习上的困难。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想克服怕黑的缺点。", "target_word": "克服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她克服紧张，在大家面前唱了歌。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对失败，我们要想办法克服。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要克服懒惰，就得每天早起。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠自己克服了语言困难。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登山队克服了很多困难，终于到了山顶。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是怎么克服这个困难的？", "target_word": "克服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子一直想克服害羞的毛病。", "target_word": "克服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "克服了", "label": "体标"}, {"form": "克服过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用意志和行动战胜困难、缺点或阻碍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "正确：句子说引擎的推力帮助飞机战胜阻力，“克服阻力”与句意相符。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加阻力”会妨碍飞机前进，与“帮助飞机”的目的相反。"}, {"text": "产生", "is_correct": false, "explanation": "语义：“产生阻力”同样不能帮助飞机，与句中“帮助飞机”的意思矛盾。"}, {"text": "使用", "is_correct": false, "explanation": "搭配：“使用”后接工具、方法等，不能说“使用阻力”。"}], "explanations": {"克服": "正确：句子说引擎的推力帮助飞机战胜阻力，“克服阻力”与句意相符。", "增加": "语义：“增加阻力”会妨碍飞机前进，与“帮助飞机”的目的相反。", "产生": "语义：“产生阻力”同样不能帮助飞机，与句中“帮助飞机”的意思矛盾。", "使用": "搭配：“使用”后接工具、方法等，不能说“使用阻力”。"}, "sentence_index": 0, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于克服了对手，拿到了冠军。", "explanation": "这里应该用〈战胜〉。克服的对象是困难、缺点，不能用来说克服对手。"}, {"text": "他在比赛中克服了好成绩。", "explanation": "这里应该用〈取得〉。克服的对象是困难、缺点，不能用于成绩。"}, {"text": "他克服了老朋友，不再和他说话。", "explanation": "这里应该用〈疏远〉。克服的对象是事情、问题，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "克服", "is_correct": true, "explanation": "正确：句子说他凭自己的力量战胜了语言困难，“克服”与句意相符。"}, {"text": "依靠", "is_correct": false, "explanation": "语义：“依靠”与“靠自己”矛盾，句子强调凭自己的力量。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”后接快乐、生活等，不接“困难”。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”意味着不再努力，与“靠自己”的意思矛盾。"}], "explanations": {"克服": "正确：句子说他凭自己的力量战胜了语言困难，“克服”与句意相符。", "依靠": "语义：“依靠”与“靠自己”矛盾，句子强调凭自己的力量。", "享受": "搭配：“享受”后接快乐、生活等，不接“困难”。", "放弃": "语义：“放弃”意味着不再努力，与“靠自己”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "克服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都在克服这幅画的美，纷纷拍照留念。", "explanation": "这里应该用〈欣赏〉。克服针对困难或缺点，不能用于美。"}, {"text": "他正在克服游戏的快乐，玩得很开心。", "explanation": "这里应该用〈享受〉。克服的对象是困难或毛病，不能用于快乐。"}, {"text": "学校正在克服学生的兴趣。", "explanation": "这里应该用〈培养〉。克服针对困难、缺点，不能用于兴趣的培育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题他一直没克服了。", "corrected_sentence": "这个问题他一直没克服。", "error_description": "体标错误：“没”否定的动作后不能加“了”，应为“没克服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前克服了过这种困难。", "corrected_sentence": "他以前克服过这种困难。", "error_description": "体标错误：“了”与“过”不能同时用在同一动词后，应为“克服过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
