INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物体由于地球的吸引而受到的向下的力。", "primary_collocate": null, "pronunciation": "zhòng lì", "ipa": "ʈʂʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "重力", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "苹果落下来，是因为有重力。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在月球上，重力比地球上小。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太空里几乎没有重力，东西会飘起来。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重力把所有东西都往下拉。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跳起来以后，重力会让人回到地面。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水往低处流，是重力的作用。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宇航员在空间站里感觉不到重力。", "target_word": "重力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重力让雨水落到地上。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球的重力比月球的大得多。", "target_word": "重力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "重力场", "label": "复合"}, {"form": "重力加速度", "label": "复合"}], "register": "中性", "sense_fingerprint": "地球吸引物体而产生的向下的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：指地球对物体的吸引力。"}, {"text": "中立", "is_correct": false, "explanation": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中立，不偏向任何一方。"}, {"text": "正例", "is_correct": false, "explanation": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正面的例子。"}, {"text": "壮丽", "is_correct": false, "explanation": "zhuàng 与 zhòng 韵母不同（uang 与 ong），声调相同，意思是雄伟美丽。"}], "explanations": {"重力": "正确：指地球对物体的吸引力。", "中立": "zhōng（第一声）与 zhòng（第四声）声调不同，意思是中立，不偏向任何一方。", "正例": "zhèng 与 zhòng 韵母不同（eng 与 ong），意思是正面的例子。", "壮丽": "zhuàng 与 zhòng 韵母不同（uang 与 ong），声调相同，意思是雄伟美丽。"}, "sentence_index": null, "correct_answer": "重力"}, "level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：重力是地球吸引物体产生的向下的力，与升力、阻力、推力并列，符合“这四个力”。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是运动的快慢，不是力，不能和升力、阻力、推力并列为“这四个力”。"}, {"text": "能量", "is_correct": false, "explanation": "语义：能量不是力，不能算作“这四个力”之一。"}, {"text": "质量", "is_correct": false, "explanation": "语义：质量是物体所含物质的多少，不是力，不能算作“这四个力”之一。"}], "explanations": {"重力": "正确：重力是地球吸引物体产生的向下的力，与升力、阻力、推力并列，符合“这四个力”。", "速度": "语义：速度是运动的快慢，不是力，不能和升力、阻力、推力并列为“这四个力”。", "能量": "语义：能量不是力，不能算作“这四个力”之一。", "质量": "语义：质量是物体所含物质的多少，不是力，不能算作“这四个力”之一。"}, "sentence_index": 0, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱子的重力有二十公斤。", "explanation": "这里应该用〈重量〉。重力是地球吸引物体的力，单位是牛顿；说东西有几公斤重，要用重量。"}, {"text": "这块磁铁的重力很强，能吸住铁钉。", "explanation": "这里应该用〈磁力〉。重力只指地球对物体的吸引，磁铁吸住铁钉要用磁力。"}, {"text": "逆风飞行时，风对飞机的重力很大，飞机很难前进。", "explanation": "这里应该用〈阻力〉。阻力是阻碍物体运动的力，风阻碍飞机前进要说阻力；重力只指地球对物体的吸引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重力", "is_correct": true, "explanation": "正确：水往低处流是地球吸引的结果，即重力的作用。"}, {"text": "磁力", "is_correct": false, "explanation": "语义：磁力只吸引铁等磁性物质，不能让水往低处流。"}, {"text": "方法", "is_correct": false, "explanation": "搭配：“……的作用”前面要是能产生效果的力或因素，“方法”不能这样用来解释水流。"}, {"text": "浮力", "is_correct": false, "explanation": "语义：浮力是向上的力，不能用来解释水往低处流。"}], "explanations": {"重力": "正确：水往低处流是地球吸引的结果，即重力的作用。", "磁力": "语义：磁力只吸引铁等磁性物质，不能让水往低处流。", "方法": "搭配：“……的作用”前面要是能产生效果的力或因素，“方法”不能这样用来解释水流。", "浮力": "语义：浮力是向上的力，不能用来解释水往低处流。"}, "sentence_index": 6, "correct_answer": "重力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的重力在肚子附近，所以他很难站稳。", "explanation": "这里应该用〈重心〉。重心是物体重量集中的位置，重力是一种力，不能说它在哪个部位。"}, {"text": "气球里的重力很大，把它撑破了。", "explanation": "这里应该用〈压力〉。气球内部的气体挤压气球壁，是压力，不是重力。"}, {"text": "鞋底的重力很大，所以不容易滑倒。", "explanation": "这里应该用〈摩擦力〉。鞋底防滑靠的是与地面之间的摩擦力，重力不是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石头松手以后，会因为一只重力落下来。", "corrected_sentence": "石头松手以后，会因为重力落下来。", "error_description": "量词错误：“重力”是抽象的力，不能用量词“只”（“只”多用于动物、手等）。应去掉“一只”，直接说“因为重力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月球的重力比地球的小的多。", "corrected_sentence": "月球的重力比地球的小得多。", "error_description": "补语标记错误：程度补语应用“得”连接，不能用“的”。正确说法是“比地球的小得多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "维持稳定，不倾斜或不失去控制。", "primary_collocate": null, "pronunciation": "bǎo chí píng héng", "ipa": "pɑʊ̯˨˩ ʈʂʰɻ̩˧˥ pʰiŋ˧˥ xɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "飞行时，工程师要让升力、阻力、推力和重力这四个力保持平衡。", "target_word": "保持平衡", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "工作和生活要保持平衡，身体才会好。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态系统里，动物和植物要保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每月的收入和花费总是保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天平两边一样重，所以能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭要荤素搭配，让营养保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要让经济和环境保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习和休息保持平衡，成绩才会提高。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的货放得不均匀，船不能保持平衡。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要让收入和支出保持平衡，不能总是亏钱。", "target_word": "保持平衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保持着平衡", "label": "体标"}], "register": "中性", "sense_fingerprint": "让事物或力量维持稳定、不倾斜、不失控", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保持平衡", "is_correct": true, "explanation": "正确：要让这四个力稳定、不失衡，应说“保持平衡”。"}, {"text": "分开", "is_correct": false, "explanation": "语义：力分开了就不能保持平衡，与句子的意思相反。"}, {"text": "消失", "is_correct": false, "explanation": "语义：力消失了就谈不上保持平衡，与“让……保持”不符。"}, {"text": "断开", "is_correct": false, "explanation": "搭配：“断开”多用于线、连接，不能用来说“让四个力断开”。"}], "explanations": {"保持平衡": "正确：要让这四个力稳定、不失衡，应说“保持平衡”。", "分开": "语义：力分开了就不能保持平衡，与句子的意思相反。", "消失": "语义：力消失了就谈不上保持平衡，与“让……保持”不符。", "断开": "搭配：“断开”多用于线、连接，不能用来说“让四个力断开”。"}, "sentence_index": 0, "correct_answer": "保持平衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开车时，他要和前车保持平衡，不能靠得太近。", "explanation": "这里应该用〈保持距离〉。保持平衡指维持稳定、不倾斜；与前车之间的间隔要说保持距离。"}, {"text": "毕业以后，我们要保持平衡，经常通信。", "explanation": "这里应该用〈保持联系〉。保持平衡指维持稳定、不倾斜；朋友之间的往来要说保持联系。"}, {"text": "图书馆里，大家要保持平衡，不要说话。", "explanation": "这里应该用〈保持安静〉。保持平衡指维持稳定、不倾斜；要求别人不出声要说保持安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持平衡", "is_correct": true, "explanation": "正确：国家要让经济和环境稳定、不失衡，应说“保持平衡”。"}, {"text": "失衡", "is_correct": false, "explanation": "语义：“失衡”与“保持平衡”意思相反，国家不会让经济和环境失衡。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：国家要让两者保持平衡，就不能去破坏它们，意思正好相反。"}, {"text": "污染", "is_correct": false, "explanation": "语义：国家要让环境保持平衡，不能让环境受到污染，这里意思不符。"}], "explanations": {"保持平衡": "正确：国家要让经济和环境稳定、不失衡，应说“保持平衡”。", "失衡": "语义：“失衡”与“保持平衡”意思相反，国家不会让经济和环境失衡。", "破坏": "语义：国家要让两者保持平衡，就不能去破坏它们，意思正好相反。", "污染": "语义：国家要让环境保持平衡，不能让环境受到污染，这里意思不符。"}, "sentence_index": 6, "correct_answer": "保持平衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批文物要保持平衡，不能随便修改。", "explanation": "这里应该用〈保持原样〉。保持平衡指维持稳定、不倾斜；文物维持原来的样子要说保持原样。"}, {"text": "这碗汤要保持平衡，才好喝。", "explanation": "这里应该用〈保持温热〉。保持平衡指维持稳定、不倾斜；汤的温度要说保持温热。"}, {"text": "老师一直保持平衡，耐心地讲解题目。", "explanation": "这里应该用〈保持耐心〉。保持平衡指维持稳定、不倾斜；待人的态度要说保持耐心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人在船上要保持平衡了，不要乱动。", "corrected_sentence": "这两个人在船上要保持平衡，不要乱动。", "error_description": "体标误用：“要保持平衡”表示应该做而还没做的事，后面不能加完成体“了”；应删去“了”，说“要保持平衡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司一直保持平衡着，所以没有亏钱。", "corrected_sentence": "公司一直保持平衡，所以没有亏钱。", "error_description": "“着”多加在了“平衡”后面：“着”应紧跟动词，“平衡”后面不能加“着”；这句应说“公司一直保持平衡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "太大", "is_correct": true, "explanation": "太大与太小意思相反，指超过所需，是反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮指外貌好看，与尺寸的大小没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴指心情愉快，与尺寸的大小无关。"}, {"text": "湿润", "is_correct": false, "explanation": "湿润指含有适度的水分，与尺寸的大小无关。"}], "correct_answer": "太大", "explanations": {"太大": "太大与太小意思相反，指超过所需，是反义关系。", "漂亮": "漂亮指外貌好看，与尺寸的大小没有反义关系。", "高兴": "高兴指心情愉快，与尺寸的大小无关。", "湿润": "湿润指含有适度的水分，与尺寸的大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过大", "is_correct": true, "explanation": "过大与太小意思相反，指超过需要，是反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净指没有污垢，与尺寸的大小无关。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖指温度适宜，与尺寸的大小无关。"}, {"text": "灿烂", "is_correct": false, "explanation": "灿烂指光彩耀眼，与尺寸的大小无关。"}], "correct_answer": "过大", "explanations": {"过大": "过大与太小意思相反，指超过需要，是反义关系。", "干净": "干净指没有污垢，与尺寸的大小无关。", "温暖": "温暖指温度适宜，与尺寸的大小无关。", "灿烂": "灿烂指光彩耀眼，与尺寸的大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示程度低于所需，指事物尺寸、数量、程度等达不到标准或预期。", "primary_collocate": null, "pronunciation": "tài xiǎo", "ipa": "tʰaɪ̯˥˩ ɕi̯ɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果升力太大，飞机会上升；如果升力太小，飞机会下降。", "target_word": "太小", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "微生物太小了，眼睛根本看不见，它们生活在土壤和水中。", "target_word": "太小", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这件衣服太小，我穿不下。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间太小，放不下三张床。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋太小了，孩子穿着脚疼。", "target_word": "太小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音太小，后面的人听不见。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子太小，装不下一升水。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年纪太小，还不能一个人坐车。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "字太小了，爷爷看不清。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子太小，坐不下八个人。", "target_word": "太小", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "太小了", "label": "带语气助词"}], "register": "中性", "sense_fingerprint": "尺寸、数量或程度小于需要，达不到要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc3be047-ee05-479c-9375-1de3fabbe191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太小", "is_correct": true, "explanation": "正确：升力不足时飞机才会下降，“太小”表示升力低于所需。"}, {"text": "太大", "is_correct": false, "explanation": "语义：前一分句已说升力太大，后一分句若也用“太大”，飞机会下降的结论与逻辑矛盾。"}, {"text": "太慢", "is_correct": false, "explanation": "搭配：“慢”说的是速度，不能用来形容升力。"}, {"text": "太甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容升力。"}], "explanations": {"太小": "正确：升力不足时飞机才会下降，“太小”表示升力低于所需。", "太大": "语义：前一分句已说升力太大，后一分句若也用“太大”，飞机会下降的结论与逻辑矛盾。", "太慢": "搭配：“慢”说的是速度，不能用来形容升力。", "太甜": "搭配：“甜”形容味道，不能用来形容升力。"}, "sentence_index": 0, "correct_answer": "太小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子太小，正好能放下三张床。", "explanation": "这里应该用〈够大〉。“太小”表示达不到需要，与“正好能放下”矛盾。"}, {"text": "这件衣服太小，正好合身。", "explanation": "这里应该用〈合身〉。“太小”表示尺寸达不到要求，与“正好合身”矛盾。"}, {"text": "声音太小，大家都听得清楚。", "explanation": "这里应该用〈够响〉。“太小”表示声音达不到需要，与“大家都听得清楚”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太小", "is_correct": true, "explanation": "正确：杯子的容量不够，所以装不下一升水。"}, {"text": "太轻", "is_correct": false, "explanation": "语义：杯子的轻重与能否装下一升水无关，这里不能用“太轻”。"}, {"text": "太热", "is_correct": false, "explanation": "搭配：“热”说的是温度，不能用来形容杯子的容量。"}, {"text": "太长", "is_correct": false, "explanation": "语义：“长”描述外形的长度，杯子长不长与能否装下一升水无关。"}], "explanations": {"太小": "正确：杯子的容量不够，所以装不下一升水。", "太轻": "语义：杯子的轻重与能否装下一升水无关，这里不能用“太轻”。", "太热": "搭配：“热”说的是温度，不能用来形容杯子的容量。", "太长": "语义：“长”描述外形的长度，杯子长不长与能否装下一升水无关。"}, "sentence_index": 6, "correct_answer": "太小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子太小，坐八个人正好。", "explanation": "这里应该用〈宽大〉。“太小”表示达不到需要，与“坐八个人正好”矛盾。"}, {"text": "这间教室太小，学生们坐得特别宽松。", "explanation": "这里应该用〈宽敞〉。“太小”与“坐得特别宽松”矛盾。"}, {"text": "这个包太小，正好装下一台笔记本电脑。", "explanation": "这里应该用〈够大〉。“太小”与“正好装下”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子太太小，装不下这些书。", "corrected_sentence": "这个箱子太小，装不下这些书。", "error_description": "错误形式是“太太小”，正确形式是“太小”。多写了一个“太”，“太”修饰形容词只能用一次，不能重叠。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器的零件很太小，装不进去。", "corrected_sentence": "这台机器的零件太小，装不进去。", "error_description": "错误形式是在“太小”前面加“很”，正确形式是“太小”。“太”和“很”都表示程度，不能叠用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '355d5238-897e-48a2-b845-5951b7e3cd05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "足够", "is_correct": true, "explanation": "反义词：“足够”与“不够”在数量是否达到要求上正好相反。"}, {"text": "挑选", "is_correct": false, "explanation": "与“不够”没有反义或近义关系，表示从多个中选出。"}, {"text": "停留", "is_correct": false, "explanation": "与“不够”没有语义关系，表示在某处不再前进。"}, {"text": "收藏", "is_correct": false, "explanation": "与“不够”没有语义关系，表示把东西保存起来。"}], "correct_answer": "足够", "explanations": {"足够": "反义词：“足够”与“不够”在数量是否达到要求上正好相反。", "挑选": "与“不够”没有反义或近义关系，表示从多个中选出。", "停留": "与“不够”没有语义关系，表示在某处不再前进。", "收藏": "与“不够”没有语义关系，表示把东西保存起来。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "足够", "is_correct": true, "explanation": "反义词：“足够”与“不够”在数量或程度是否达到要求上正好相反。"}, {"text": "讨论", "is_correct": false, "explanation": "与“不够”没有反义或近义关系，表示大家一起交换意见。"}, {"text": "摆放", "is_correct": false, "explanation": "与“不够”没有语义关系，表示把东西按一定位置放好。"}, {"text": "清洗", "is_correct": false, "explanation": "与“不够”没有语义关系，表示用水等去除污物。"}], "correct_answer": "足够", "explanations": {"足够": "反义词：“足够”与“不够”在数量或程度是否达到要求上正好相反。", "讨论": "与“不够”没有反义或近义关系，表示大家一起交换意见。", "摆放": "与“不够”没有语义关系，表示把东西按一定位置放好。", "清洗": "与“不够”没有语义关系，表示用水等去除污物。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示数量、程度、能力等方面未能达到应有的标准或期望。", "primary_collocate": null, "pronunciation": "bú gòu", "ipa": "pu˧˥ kou̯˥˩", "syllable_count": 2, "sentences": [{"text": "如果推力不够，飞机就会变慢，甚至飞不动。", "target_word": "不够", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个月的钱不够，我不能买新手机。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的椅子不够，有三个人没座位。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平不够，听不懂新闻。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不够，我们明天再做吧。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜不够吃，再点一个汤吧。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不够大，我穿着有点小。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的水不够热，我想再烧一下。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你睡得不够多，所以上课没精神。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得不够快，没有拿到第一名。", "target_word": "不够", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量、程度或能力没有达到应有的标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案，表示数量或程度没有达到应有的标准。"}, {"text": "步骤", "is_correct": false, "explanation": "声母不同：zhòu 与 gòu 的声母分别是 zh 和 g，意思是步骤。"}, {"text": "布告", "is_correct": false, "explanation": "韵母不同：gào 与 gòu 的韵母分别是 ao 和 ou，意思是布告。"}, {"text": "补购", "is_correct": false, "explanation": "声调不同：bǔ（第三声）与 bú（第二声）声调不同，意思是补充购买。"}], "explanations": {"不够": "正确答案，表示数量或程度没有达到应有的标准。", "步骤": "声母不同：zhòu 与 gòu 的声母分别是 zh 和 g，意思是步骤。", "布告": "韵母不同：gào 与 gòu 的韵母分别是 ao 和 ou，意思是布告。", "补购": "声调不同：bǔ（第三声）与 bú（第二声）声调不同，意思是补充购买。"}, "sentence_index": null, "correct_answer": "不够"}, "level_3": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案。推力达不到要求，所以飞机才会变慢、飞不动。"}, {"text": "够", "is_correct": false, "explanation": "语义：“够”表示推力足够，与后文“变慢、飞不动”的因果矛盾。"}, {"text": "增加", "is_correct": false, "explanation": "配价：“增加”一般要说明增加的对象，这里用“推力增加”无法表达推力不足。"}, {"text": "变大", "is_correct": false, "explanation": "语义：推力变大应使飞机更快，与“变慢”“飞不动”矛盾。"}], "explanations": {"不够": "正确答案。推力达不到要求，所以飞机才会变慢、飞不动。", "够": "语义：“够”表示推力足够，与后文“变慢、飞不动”的因果矛盾。", "增加": "配价：“增加”一般要说明增加的对象，这里用“推力增加”无法表达推力不足。", "变大": "语义：推力变大应使飞机更快，与“变慢”“飞不动”矛盾。"}, "sentence_index": 0, "correct_answer": "不够"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间不够暖和，我一进门就觉得热得受不了。", "explanation": "这里应该用〈过热〉。“不够”表示未达到需要的标准，这里说的是温度超过了需要，应该用“过热”。"}, {"text": "这碗汤不够咸，我喝了一口就皱起了眉头。", "explanation": "这里应该用〈过咸〉。“不够咸”表示咸味未达到需要，这里说的是太咸，应该用“过咸”。"}, {"text": "这盘饺子不够吃，我们每人都吃撑了。", "explanation": "这里应该用〈太多〉。“不够”表示数量没有达到需要，这里说的是数量超过了需要，应该用“太多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不够", "is_correct": true, "explanation": "正确答案。衣服的尺寸没有达到要求，所以我穿着有点小。"}, {"text": "够", "is_correct": false, "explanation": "语义：“够”表示衣服足够大，与后文“我穿着有点小”矛盾。"}, {"text": "合身", "is_correct": false, "explanation": "语义：“合身”表示大小正合适，与后文“有点小”矛盾。"}, {"text": "显得", "is_correct": false, "explanation": "语义：“衣服显得大”与后文“我穿着有点小”矛盾，且不能说明尺寸没达到要求。"}], "explanations": {"不够": "正确答案。衣服的尺寸没有达到要求，所以我穿着有点小。", "够": "语义：“够”表示衣服足够大，与后文“我穿着有点小”矛盾。", "合身": "语义：“合身”表示大小正合适，与后文“有点小”矛盾。", "显得": "语义：“衣服显得大”与后文“我穿着有点小”矛盾，且不能说明尺寸没达到要求。"}, "sentence_index": 6, "correct_answer": "不够"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子不够凉快，我们开了空调，还是冷得直打哆嗦。", "explanation": "这里应该用〈过冷〉。“不够凉快”表示温度未达到需要，这里说的是太冷，应该用“过冷”。"}, {"text": "这份工作的压力不够大，我每天加班到深夜，累得不行。", "explanation": "这里应该用〈过重〉。“不够大”表示未达到需要，这里说的是压力超过了需要，应该用“过重”。"}, {"text": "这杯茶不够浓，喝一口就觉得苦得发涩。", "explanation": "这里应该用〈过浓〉。“不够浓”表示浓度未达到需要，这里说的是太浓，应该用“过浓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些椅子不够得，我们再搬几把来吧。", "corrected_sentence": "这些椅子不够，我们再搬几把来吧。", "error_description": "多加了“得”：“不够”后不能直接接“得”，应删去“得”，即“这些椅子不够，我们再搬几把来吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件外套不够得长，穿起来不暖和。", "corrected_sentence": "这件外套不够长，穿起来不暖和。", "error_description": "多加了“得”：“不够”后面直接接形容词，说“不够长”，不能说“不够得长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
