INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指因为疲劳或能力不足而无法继续飞行。", "primary_collocate": null, "pronunciation": "fēi bu dòng", "ipa": "feɪ̯˥ pu toŋ˥˩", "syllable_count": 3, "sentences": [{"text": "如果推力不够，飞机就会变慢，甚至飞不动。", "target_word": "飞不动", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "小鸟太累了，飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只雏鸟刚学会飞，本领还不够，很快就飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，小鸟飞不动，只好回家。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟的翅膀受伤了，飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长途飞行以后，大雁累得飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机太重，发动机力量小，飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小蜜蜂带着很多花粉，飞不动了。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它吃得太多，胖得飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架旧无人机太重了，载上相机就飞不动。", "target_word": "飞不动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飞得动", "label": "肯定式"}], "register": "中性", "sense_fingerprint": "因疲劳或能力不足而不能继续飞行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb9f15f3-ccce-46a2-a36a-890065503d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞不动", "is_correct": true, "explanation": "正确答案。推力不够，飞机变慢后就会飞不动。"}, {"text": "飞得快", "is_correct": false, "explanation": "语义：推力不够时飞机变慢，“飞得快”与前半句的因果矛盾。"}, {"text": "飞得动", "is_correct": false, "explanation": "语义：“飞得动”表示有能力飞，与“推力不够”的前提矛盾。"}, {"text": "起飞", "is_correct": false, "explanation": "搭配：“起飞”指开始飞行，接在“变慢”之后，表达的递进关系不合。"}], "explanations": {"飞不动": "正确答案。推力不够，飞机变慢后就会飞不动。", "飞得快": "语义：推力不够时飞机变慢，“飞得快”与前半句的因果矛盾。", "飞得动": "语义：“飞得动”表示有能力飞，与“推力不够”的前提矛盾。", "起飞": "搭配：“起飞”指开始飞行，接在“变慢”之后，表达的递进关系不合。"}, "sentence_index": 0, "correct_answer": "飞不动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只小鸟精神饱满，一口气飞了三公里，一点也飞不动。", "explanation": "这里应该用〈飞得动〉。“飞不动”表示因疲劳或能力不足而无法继续飞行，这只小鸟精神饱满，应说“飞得动”。"}, {"text": "他跑了一天，累得飞不动了，只好躺在草地上。", "explanation": "这里应该用〈跑不动〉。人用脚奔跑，应说“跑不动”，“飞不动”只用于能飞的鸟或飞机。"}, {"text": "这辆卡车装满了货，已经飞不动了。", "explanation": "这里应该用〈开不动〉。卡车在路上行驶应说“开不动”，“飞不动”只用于能在空中飞的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞不动", "is_correct": true, "explanation": "正确答案。飞机太重，发动机力量小，所以飞不动。"}, {"text": "飞得高", "is_correct": false, "explanation": "语义：飞机太重、力量小，“飞得高”与前面的原因矛盾。"}, {"text": "飞得远", "is_correct": false, "explanation": "语义：力量小、飞机太重，“飞得远”与前面的原因矛盾。"}, {"text": "飞走", "is_correct": false, "explanation": "搭配：“飞走”表示飞离开，不能用来说明因重量而无法继续飞行的结果。"}], "explanations": {"飞不动": "正确答案。飞机太重，发动机力量小，所以飞不动。", "飞得高": "语义：飞机太重、力量小，“飞得高”与前面的原因矛盾。", "飞得远": "语义：力量小、飞机太重，“飞得远”与前面的原因矛盾。", "飞走": "搭配：“飞走”表示飞离开，不能用来说明因重量而无法继续飞行的结果。"}, "sentence_index": 6, "correct_answer": "飞不动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小鸟精力十足，一早起来就飞不动了。", "explanation": "这里应该用〈振翅高飞〉。“飞不动”表示因疲劳或能力不足而无法继续飞行，小鸟精力充沛，应说“振翅高飞”。"}, {"text": "这只猫爬了一会儿树，就飞不动了。", "explanation": "这里应该用〈爬不动〉。猫在树上攀爬应说“爬不动”，“飞不动”只用于能飞的东西。"}, {"text": "这架飞机刚加满油，发动机很好，所以飞不动了。", "explanation": "这里应该用〈飞得动〉。“飞不动”表示因能力不足而无法继续飞行，飞机油满、发动机好，正是能飞的原因，应说“飞得动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟累得飞不动过，只好落在树上。", "corrected_sentence": "小鸟累得飞不动了，只好落在树上。", "error_description": "错误形式：“飞不动过”。正确形式：“飞不动了”。“飞不动”描述小鸟当下无力飞行的状态，应用“了”表示状态出现的变化，不能用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个风筝太重，我们的力气小，能飞不动。", "corrected_sentence": "这个风筝太重，我们的力气小，飞不动。", "error_description": "错误形式：“能飞不动”。正确形式：“飞不动”。“飞不动”本身已表示无法飞行，前面不能再加“能”，二者语义冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b46aeab5-29c5-4b59-b392-eb370d2768e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
