INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12115, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "知道、明白、了解。", "primary_collocate": null, "pronunciation": "dǒng", "ipa": "tʊŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "所以飞行员和工程师都要懂这些物理原理，才能让飞机安全飞行。", "target_word": "懂", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "懂了这些规律，我们就能造出更好的飞机。", "target_word": "懂", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师讲得很清楚，我全都懂了。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个字是什么意思，你懂吗？", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说的是法语，我一句也不懂。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不懂电脑，所以常常问我。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太懂这道题，你能再讲一遍吗？", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子不懂大人的难处。", "target_word": "懂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很懂音乐，常常给我们推荐好歌。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书太难了，很多地方我都没懂。", "target_word": "懂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "懂了", "label": "体标"}, {"form": "懂得", "label": "复合"}, {"form": "懂事", "label": "复合"}], "register": "中性", "sense_fingerprint": "懂：知道、明白、了解某事或某个道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '772fca80-e265-4879-9a3c-3f993f58a8df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12115, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：懂（dǒng，第三声），意思是知道、明白。"}, {"text": "统", "is_correct": false, "explanation": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是统一、统计。"}, {"text": "动", "is_correct": false, "explanation": "dòng（第四声）与 dǒng（第三声）声调不同，意思是动作、动弹。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dǒng（第三声）声调不同，意思是东边。"}], "explanations": {"懂": "正确：懂（dǒng，第三声），意思是知道、明白。", "统": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是统一、统计。", "动": "dòng（第四声）与 dǒng（第三声）声调不同，意思是动作、动弹。", "东": "dōng（第一声）与 dǒng（第三声）声调不同，意思是东边。"}, "sentence_index": null, "correct_answer": "懂"}, "level_3": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：“懂”表示理解物理原理，与“才能让飞机安全飞行”的语境相符。"}, {"text": "造", "is_correct": false, "explanation": "搭配：“造”的对象是实物，不能说造原理。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理具体器物，不能说修原理。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“这些物理原理”做宾语。"}], "explanations": {"懂": "正确：“懂”表示理解物理原理，与“才能让飞机安全飞行”的语境相符。", "造": "搭配：“造”的对象是实物，不能说造原理。", "修": "搭配：“修”用于修理具体器物，不能说修原理。", "睡": "配价：“睡”是不及物动词，不能带“这些物理原理”做宾语。"}, "sentence_index": 0, "correct_answer": "懂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在楼下懂了敲门声。", "explanation": "这里应该用〈听见〉。懂指理解意思或道理，听到声音要用听见。"}, {"text": "我在窗边懂了那只鸟，颜色很漂亮。", "explanation": "这里应该用〈看见〉。懂指理解意思，看到景物要用看见。"}, {"text": "我在厨房懂了饭菜的香味，饿极了。", "explanation": "这里应该用〈闻到〉。懂指理解意思或道理，闻到气味要用闻到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12115, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：懂（dǒng，第三声），意思是知道、明白。"}, {"text": "桶", "is_correct": false, "explanation": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是水桶。"}, {"text": "洞", "is_correct": false, "explanation": "dòng（第四声）与 dǒng（第三声）声调不同，意思是洞穴、孔。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dǒng（第三声）声调不同，意思是冬天。"}], "explanations": {"懂": "正确：懂（dǒng，第三声），意思是知道、明白。", "桶": "声母不同：tǒng 的声母是 t，dǒng 的声母是 d，此处意思是水桶。", "洞": "dòng（第四声）与 dǒng（第三声）声调不同，意思是洞穴、孔。", "冬": "dōng（第一声）与 dǒng（第三声）声调不同，意思是冬天。"}, "sentence_index": null, "correct_answer": "懂"}, "level_3": {"options": [{"text": "懂", "is_correct": true, "explanation": "正确：“懂”表示没有理解题目，与“你能再讲一遍吗”相呼应。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”的对象是商品，不能说买题目。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃题目。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“这道题”做宾语。"}], "explanations": {"懂": "正确：“懂”表示没有理解题目，与“你能再讲一遍吗”相呼应。", "买": "搭配：“买”的对象是商品，不能说买题目。", "吃": "搭配：“吃”的对象是食物，不能说吃题目。", "游泳": "配价：“游泳”是不及物动词，不能带“这道题”做宾语。"}, "sentence_index": 6, "correct_answer": "懂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我懂这位新同学，我们昨天第一次见面。", "explanation": "这里应该用〈认识〉。懂指明白意思或道理，初次与人相识要用认识。"}, {"text": "这首老歌一响，我就懂起了小时候的事。", "explanation": "这里应该用〈想起〉。懂指理解意思，回忆过去的事要用想起。"}, {"text": "这个电话号码我懂了，就不用再记了。", "explanation": "这里应该用〈记住〉。懂指理解意思，记住号码、单词等要用记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师的话，我听了懂。", "corrected_sentence": "老师的话，我听懂了。", "error_description": "“听懂”是动补结构，“了”应放在补语“懂”之后，说“听懂了”，不能说“听了懂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我终于了懂这道数学题。", "corrected_sentence": "我终于懂了这道数学题。", "error_description": "“了”应放在动词“懂”之后表示完成，“了懂”的语序错误，应说“懂了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
