INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在受控环境中测试物体对气流反应的过程", "primary_collocate": null, "pronunciation": "shí yàn", "ipa": "ʂʐ̩˧˥ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "现代飞机设计要用到很多工程计算和风洞实验。", "target_word": "实验", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "工程师在风洞里做实验，测试飞机。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验测试汽车模型受风的影响。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验开始前，要先打开风洞的风扇。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在风洞里用小模型做了几次实验。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验证明，圆形的车头更不容易受风影响。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们第一次看到了风洞实验。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，模型飞机一直放在风洞里。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师根据实验的数据改了机翼。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验要控制风速，只能在风洞里做。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个实验", "label": "量词"}, {"form": "一项实验", "label": "量词"}, {"form": "一次实验", "label": "量词"}, {"form": "實驗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在风洞等受控环境中测试物体受气流影响的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a504ff71-c661-4a1d-b12d-34e4e5063915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12121, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "食盐", "is_correct": false, "explanation": "食盐（shí yán）与实验（shí yàn）只有第二音节声调不同，意思是食用的盐。"}, {"text": "实验", "is_correct": true, "explanation": "实验（shí yàn）指在受控环境中测试物体的过程，是正确答案。"}, {"text": "时延", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是信号传输的延迟。"}, {"text": "食言", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是不守诺言。"}], "explanations": {"食盐": "食盐（shí yán）与实验（shí yàn）只有第二音节声调不同，意思是食用的盐。", "实验": "实验（shí yàn）指在受控环境中测试物体的过程，是正确答案。", "时延": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是信号传输的延迟。", "食言": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是不守诺言。"}, "sentence_index": null, "correct_answer": "实验"}, "level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "实验：“风洞实验”指在风洞里测试模型的专业实验，与“风洞”搭配。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”指吃饭的地方，与飞机设计和工程计算无关。"}, {"text": "宴会", "is_correct": false, "explanation": "语义：“宴会”指聚餐活动，与工程测试的语境不符。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：“风洞”是测试设备，不能组成“风洞广告”。"}], "explanations": {"实验": "实验：“风洞实验”指在风洞里测试模型的专业实验，与“风洞”搭配。", "餐厅": "语义：“餐厅”指吃饭的地方，与飞机设计和工程计算无关。", "宴会": "语义：“宴会”指聚餐活动，与工程测试的语境不符。", "广告": "搭配：“风洞”是测试设备，不能组成“风洞广告”。"}, "sentence_index": 0, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师做了一只风洞实验。", "explanation": "这里应该用〈项〉。“只”用于动物，实验用“项”“个”“次”来计数。"}, {"text": "工程师每天都吃一个风洞实验当午饭。", "explanation": "这里不能用〈实验〉。“吃”的对象是食物，实验是研究活动，应说〈午饭〉。"}, {"text": "她唱了一个实验。", "explanation": "这里应该用〈歌〉。“唱”搭配歌曲，不能唱实验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "实验：“风洞实验”指在风洞里进行的测试活动，搭配正确。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是种花的地方，风洞不是花园，句意不通。"}, {"text": "书店", "is_correct": false, "explanation": "语义：“书店”是卖书的地方，与风洞无关。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“风洞”后不说“风洞演出”，“演出”是舞台活动。"}], "explanations": {"实验": "实验：“风洞实验”指在风洞里进行的测试活动，搭配正确。", "花园": "语义：“花园”是种花的地方，风洞不是花园，句意不通。", "书店": "语义：“书店”是卖书的地方，与风洞无关。", "演出": "搭配：“风洞”后不说“风洞演出”，“演出”是舞台活动。"}, "sentence_index": 6, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位实验一共做了三次，数据很完整。", "explanation": "这里应该用〈个〉。“位”用于人，实验用“个”“项”“次”来计数。"}, {"text": "这台实验要控制风速，只能在风洞里做。", "explanation": "这里应该用〈个〉。“台”用于机器，实验用“个”“项”“次”来计数。"}, {"text": "孩子们在风洞里喝实验。", "explanation": "这里不能用〈实验〉。“喝”的对象是饮品，实验不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只风洞实验为新款汽车提供了数据。", "corrected_sentence": "这项风洞实验为新款汽车提供了数据。", "error_description": "错误是量词用错。“实验”应用“项”，“只”多用于动物，不能修饰“实验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只风洞实验测试了新飞机的机翼。", "corrected_sentence": "这项风洞实验测试了新飞机的机翼。", "error_description": "错误是量词用错。“实验”应用“项”，“只”多用于动物，不能修饰“实验”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf5d48ef-4b40-4f5e-8fb2-d5452eeb113f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
