INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12122, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指风（风本身或风带来的气流）吹拂到人身上，也比喻让人感到凉爽或舒适。", "primary_collocate": null, "pronunciation": "chuī fēng", "ipa": "ʈʂʰweɪ˥ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "工程师让志愿者站在风洞里吹风，记录他们的感受。", "target_word": "吹风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，我们在河边吹风。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在窗边吹风，觉得很舒服。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车开得很快，我把头伸出窗外吹风。", "target_word": "吹风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太热了，到阳台吹风吧。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在山顶吹风，一点也不热。", "target_word": "吹风", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大热天，我们去海边吹风。", "target_word": "吹风", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子出了汗，别在风口吹风，会感冒。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她闭着眼睛，在树下吹风。", "target_word": "吹风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午没事，爷爷喜欢在院子里吹风。", "target_word": "吹风", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "吹吹风", "label": "重叠"}, {"form": "吹了风", "label": "体标"}, {"form": "吹着风", "label": "体标"}, {"form": "吹过风", "label": "体标"}, {"form": "吹風", "label": "繁体"}], "register": "口语", "sense_fingerprint": "吹风：让风吹在身上，感到凉爽舒适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '772fca80-e265-4879-9a3c-3f993f58a8df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吹风", "is_correct": true, "explanation": "吹风：让风吹在志愿者身上，符合风洞里测试人体感受的语境。"}, {"text": "避风", "is_correct": false, "explanation": "语义：“避风”指躲开风的吹拂，志愿者站在风洞里不能避风，句意矛盾。"}, {"text": "吹牛", "is_correct": false, "explanation": "语义：“吹牛”指夸口说大话，与风洞里记录感受的语境无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“洗澡”要在浴室或水中进行，不能在风洞里洗澡。"}], "explanations": {"吹风": "吹风：让风吹在志愿者身上，符合风洞里测试人体感受的语境。", "避风": "语义：“避风”指躲开风的吹拂，志愿者站在风洞里不能避风，句意矛盾。", "吹牛": "语义：“吹牛”指夸口说大话，与风洞里记录感受的语境无关。", "洗澡": "搭配：“洗澡”要在浴室或水中进行，不能在风洞里洗澡。"}, "sentence_index": 0, "correct_answer": "吹风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒风刺骨，我们躲在墙角吹风。", "explanation": "这里应该用〈避风〉。吹风是风吹在身上带来凉爽，躲在墙角避风时不能说吹风。"}, {"text": "他总爱在朋友面前吹风，说自己多厉害。", "explanation": "这里应该用〈吹牛〉。吹风指风吹在身上，夸大自己、说大话要用吹牛，吹风没有这个意思。"}, {"text": "周末我们去商场吹风。", "explanation": "这里应该用〈逛〉。吹风要有风吹在身上，商场里没有风，闲逛要说逛商场，不能说吹风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吹风", "is_correct": true, "explanation": "吹风：在海边让凉风吹在身上，符合大热天去海边的语境。"}, {"text": "取暖", "is_correct": false, "explanation": "语义：“取暖”是让身体变暖，与“大热天”的语境正好相反。"}, {"text": "驱寒", "is_correct": false, "explanation": "搭配：“驱寒”要驱赶的是寒气，大热天没有寒气可驱，二者不搭配。"}, {"text": "烤火", "is_correct": false, "explanation": "语义：“烤火”需要靠近火取暖，与大热天去海边的语境不符。"}], "explanations": {"吹风": "吹风：在海边让凉风吹在身上，符合大热天去海边的语境。", "取暖": "语义：“取暖”是让身体变暖，与“大热天”的语境正好相反。", "驱寒": "搭配：“驱寒”要驱赶的是寒气，大热天没有寒气可驱，二者不搭配。", "烤火": "语义：“烤火”需要靠近火取暖，与大热天去海边的语境不符。"}, "sentence_index": 6, "correct_answer": "吹风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "树下连一丝风都没有，大家都在那儿吹风。", "explanation": "这里应该用〈避暑〉。吹风需要风吹到身上，这里说连一丝风都没有；避暑指躲开暑热。"}, {"text": "冬天的夜里，我们围着火炉吹风。", "explanation": "这里应该用〈取暖〉。吹风是风吹在身上带来凉爽，与“围着火炉”的暖和语境矛盾。"}, {"text": "裁判一吹风，比赛就开始了。", "explanation": "这里应该用〈吹哨〉。吹风指风吹在身上，裁判用哨子发出开始的信号要说吹哨，吹风没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在阳台上吹着一会儿风，就回屋了。", "corrected_sentence": "他在阳台上吹了一会儿风，就回屋了。", "error_description": "体标错误：离合词「吹风」带时量补语「一会儿」表示已完成的一段时间，要用「了」，说「吹了一会儿风」，不能用「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在河边吹风吹，觉得很凉快。", "corrected_sentence": "他在河边吹吹风，觉得很凉快。", "error_description": "重叠形式错误：「吹风」重叠应为「吹吹风」，不能说「吹风吹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7feda931-af34-49a2-bf65-6382cdc6fdf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
