INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究飞行器设计、制造和运行的工程领域。", "primary_collocate": null, "pronunciation": "háng kōng gōng chéng", "ipa": "xɑŋ˧˥ kʰʊŋ˥˥ kʊŋ˥˥ ʈʂʰɤŋ˧˥", "syllable_count": 4, "sentences": [{"text": "在现代航空工程的精密体系中，飞行器的设计本质上是物理法则的艺术化应用，尤其是空气动力学原理在其中占据了核心地位。", "target_word": "航空工程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "由此观之，航空工程不仅是技术的集合体，更是人类对自然法则深刻理解的外化表现。", "target_word": "航空工程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我哥哥在大学学航空工程。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "航空工程研究飞机怎么设计和制造。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业于航空工程专业，现在设计飞机。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学航空工程的人要懂数学和物理。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所大学的航空工程很有名。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "航空工程的发展让人们飞得更远。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想读航空工程，将来造飞机。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "航空工程需要很多人一起合作。", "target_word": "航空工程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "研究飞行器设计、制造、运行的工程学科与领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空工程", "is_correct": true, "explanation": "航空工程：研究飞行器设计、制造的工程领域，与「飞行器的设计」「空气动力学」的语境相符。"}, {"text": "生物工程", "is_correct": false, "explanation": "语义：生物工程研究生命体系，与「飞行器的设计」和「空气动力学原理」不相符。"}, {"text": "园林工程", "is_correct": false, "explanation": "语义：园林工程处理景观营造，与「飞行器」「空气动力学」的语境无关。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：「精密体系」指复杂的工程或仪器系统，「烹饪」不能用作其定语。"}], "explanations": {"航空工程": "航空工程：研究飞行器设计、制造的工程领域，与「飞行器的设计」「空气动力学」的语境相符。", "生物工程": "语义：生物工程研究生命体系，与「飞行器的设计」和「空气动力学原理」不相符。", "园林工程": "语义：园林工程处理景观营造，与「飞行器」「空气动力学」的语境无关。", "烹饪": "搭配：「精密体系」指复杂的工程或仪器系统，「烹饪」不能用作其定语。"}, "sentence_index": 0, "correct_answer": "航空工程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在航空工程里等了两个小时的飞机。", "explanation": "这里应该用〈机场〉。机场是候机、登机的场所；航空工程是学科，不能作为等飞机的地点。"}, {"text": "航空工程每天安排大量航班。", "explanation": "这里应该用〈航空公司〉。航空公司负责运营航班；航空工程是学科和技术领域，不负责安排航班。"}, {"text": "他每天乘航空工程去上海出差。", "explanation": "这里应该用〈飞机〉。飞机是可以乘坐的交通工具；航空工程是学科，不能被乘坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空工程", "is_correct": true, "explanation": "航空工程：可以作为大学的专业或特色，与「这所大学的……很有名」相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是大学的专业或特色，不能说「很有名」。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：「很有名」不能修饰「温度」，温度不能作为大学的特色。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是致病微生物，与「大学的……很有名」的语境相矛盾。"}], "explanations": {"航空工程": "航空工程：可以作为大学的专业或特色，与「这所大学的……很有名」相符。", "天气": "语义：天气不是大学的专业或特色，不能说「很有名」。", "温度": "搭配：「很有名」不能修饰「温度」，温度不能作为大学的特色。", "病毒": "语义：病毒是致病微生物，与「大学的……很有名」的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "航空工程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在网上买了一张去北京的航空工程。", "explanation": "这里应该用〈机票〉。机票是乘飞机的凭证，可以用「张」来数、可以买；航空工程是学科，不能买。"}, {"text": "航空工程是人类飞行的工具。", "explanation": "这里应该用〈航空器〉。航空器指飞机、飞艇等实体；航空工程是学科和技术领域，不能作「工具」。"}, {"text": "航空工程要通过严格的体检。", "explanation": "这里应该用〈飞行员〉。飞行员是人，需要体检；航空工程是学科，不能接受体检。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "喜欢航空工程人要有耐心。", "corrected_sentence": "喜欢航空工程的人要有耐心。", "error_description": "「航空工程人」应为「航空工程的人」：定语「航空工程」修饰「人」时，中间要加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在航空工程很感兴趣。", "corrected_sentence": "他对航空工程很感兴趣。", "error_description": "「在航空工程」应为「对航空工程」：表示兴趣的对象要用介词「对」，说「对……感兴趣」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
