INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12129, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12129, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指能够在大气层内或大气层外空间飞行的各种机器或装置，例如飞机、火箭、卫星等。", "primary_collocate": null, "pronunciation": "fēi xíng qì", "ipa": "feɪ˥ ɕiŋ˧˥ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "在现代航空工程的精密体系中，飞行器的设计本质上是物理法则的艺术化应用，尤其是空气动力学原理在其中占据了核心地位。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这架飞行器可在空中连续飞行两个小时。", "target_word": "飞行器", "complexity_tier": "T3", "furigana": "zhè jià fēixíngqì kě zài kōngzhōng liánxù fēixíng liǎng gè xiǎoshí", "sentence_source": "generated"}, {"text": "工程师正在测试新设计的飞行器。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个飞行器的机翼很长，飞得很稳。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭和卫星都是飞行器。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行器离开地面后，速度越来越快。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家把飞行器送上了太空。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行器的燃料用完了，只能回到地面。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在操场上试飞小型飞行器，兴致很高。", "target_word": "飞行器", "complexity_tier": "T3", "furigana": "xuéshēngmen zài cāochǎng shàng shìfēi xiǎoxíng fēixíngqì, xìngzhì hěn gāo", "sentence_source": "generated"}, {"text": "这种飞行器不用人开，靠电脑控制。", "target_word": "飞行器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一架飞行器", "label": "量词"}, {"form": "无人飞行器", "label": "复合"}, {"form": "飛行器", "label": "繁体"}], "register": "书面", "sense_fingerprint": "能在大气层内外飞行的机器或装置，如飞机、火箭、卫星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa298e6-cfcf-449f-90b9-c2a575b9f960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞行器", "is_correct": true, "explanation": "正确。“飞行器”指能在大气层内外飞行的机器，与句中“航空工程”“设计”“空气动力学”的语境相符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物是供人食用的东西，与句中的航空工程和空气动力学原理毫不相关。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流用的符号系统，不是可以依据空气动力学原理设计的实体。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“设计”的对象应是人造物，不能说“天空的设计”。"}], "explanations": {"飞行器": "正确。“飞行器”指能在大气层内外飞行的机器，与句中“航空工程”“设计”“空气动力学”的语境相符。", "食物": "语义：食物是供人食用的东西，与句中的航空工程和空气动力学原理毫不相关。", "语言": "语义：语言是交流用的符号系统，不是可以依据空气动力学原理设计的实体。", "天空": "搭配：“设计”的对象应是人造物，不能说“天空的设计”。"}, "sentence_index": 0, "correct_answer": "飞行器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥的工作是飞行器。", "explanation": "这里应该用〈飞行员〉。“飞行器”指机器，不能用来指人的职业。"}, {"text": "我妈妈每天用飞行器做饭。", "explanation": "这里应该用〈锅〉。“飞行器”是能飞行的机器，不是做饭的厨具。"}, {"text": "飞机从飞行器起飞了。", "explanation": "这里应该用〈机场〉。飞行器是能飞的机器，不是飞机起飞的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "飞行器", "is_correct": true, "explanation": "正确。“送上太空”的对象是能飞行的机器，飞行器符合句意。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是大片地理实体，无法被“送上太空”。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市是人类聚居的地区，不是能被运送的物体。"}, {"text": "知识", "is_correct": false, "explanation": "搭配：“送上太空”一般指运送具体物体，“知识”不能这样被“送上”。"}], "explanations": {"飞行器": "正确。“送上太空”的对象是能飞行的机器，飞行器符合句意。", "海洋": "语义：海洋是大片地理实体，无法被“送上太空”。", "城市": "语义：城市是人类聚居的地区，不是能被运送的物体。", "知识": "搭配：“送上太空”一般指运送具体物体，“知识”不能这样被“送上”。"}, "sentence_index": 6, "correct_answer": "飞行器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都给飞行器喂食。", "explanation": "这里应该用〈小鸟〉。“喂食”的对象是有生命的动物，飞行器是机器，不需要也不能被喂食。"}, {"text": "他穿着飞行器出门了。", "explanation": "这里应该用〈鞋〉。“穿”用于衣物、鞋帽等，飞行器不能被穿。"}, {"text": "我每天早上都读飞行器。", "explanation": "这里应该用〈报纸〉。“读”的对象是文字材料，飞行器不能被阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师在车间里组装了一条飞行器。", "corrected_sentence": "工程师在车间里组装了一架飞行器。", "error_description": "量词错误：飞行器应使用量词「架」，不能用「条」。「条」多用于河、鱼、裤子等长条形事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把飞行器推出着库房。", "corrected_sentence": "他把飞行器推出了库房。", "error_description": "体标错误：“推出”表示动作已经完成，应用“了”，不能用“着”（“着”表示持续的状态）。应说“把飞行器推出了库房”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
