INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12131, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指通过艺术手法或审美加工，使事物具有艺术特性或形式美感。", "primary_collocate": null, "pronunciation": "yì shù huà", "ipa": "i˥˩ ʂu˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "在现代航空工程的精密体系中，飞行器的设计本质上是物理法则的艺术化应用，尤其是空气动力学原理在其中占据了核心地位。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这家店对咖啡的艺术化处理让人印象深刻。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活的艺术化让普通的日子变得有趣。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的艺术化表达很特别。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位摄影师把普通的街景艺术化了。", "target_word": "艺术化", "complexity_tier": "T3", "furigana": "zhè wèi shè yǐng shī bǎ pǔ tōng de jiē jǐng yì shù huà le", "sentence_source": "generated"}, {"text": "老师说，作文需要一点艺术化的语言。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师对房间的艺术化设计很满意。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市建筑的艺术化越来越明显。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对历史故事做了艺术化的处理。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度艺术化会让东西不实用。", "target_word": "艺术化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "艺术化处理", "label": "复合"}, {"form": "藝術化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用艺术手法或审美加工，使事物具有艺术特性和美感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa298e6-cfcf-449f-90b9-c2a575b9f960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宠物化", "is_correct": false, "explanation": "语义：「宠物化」指把事物当作宠物对待，与「物理法则」的科学语境毫不相关。"}, {"text": "艺术化", "is_correct": true, "explanation": "正确：「艺术化」修饰「应用」，指物理法则经艺术手法加工，句义通顺。"}, {"text": "神秘化", "is_correct": false, "explanation": "语义：「神秘化」指使事物显得神秘，与「精密体系」「空气动力学」的科学语境冲突。"}, {"text": "口语化", "is_correct": false, "explanation": "语域：「口语化」指语言通俗、适于口头表达，不能修饰「应用」，也与书面的科技语境不合。"}], "explanations": {"宠物化": "语义：「宠物化」指把事物当作宠物对待，与「物理法则」的科学语境毫不相关。", "艺术化": "正确：「艺术化」修饰「应用」，指物理法则经艺术手法加工，句义通顺。", "神秘化": "语义：「神秘化」指使事物显得神秘，与「精密体系」「空气动力学」的科学语境冲突。", "口语化": "语域：「口语化」指语言通俗、适于口头表达，不能修饰「应用」，也与书面的科技语境不合。"}, "sentence_index": 0, "correct_answer": "艺术化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇窗户太脏了，我花了一个小时把它艺术化了。", "explanation": "这里应该用〈擦洗〉。「艺术化」指通过艺术手法加工事物，使其具有艺术特性；擦洗脏窗户是清洁，不是艺术加工，应说「擦洗」。"}, {"text": "我们花了一周时间把水管艺术化了，现在终于不漏水了。", "explanation": "这里应该用〈修理〉。「艺术化」指通过艺术手法加工事物，使其具有艺术特性；修好漏水的水管是功能性修复，不说「艺术化」。"}, {"text": "这块旧木板经过艺术化，就能当门用了。", "explanation": "这里应该用〈加工〉。「艺术化」指使事物具有艺术特性，把木板改造成门要用「加工」，不说「艺术化」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方言化", "is_correct": false, "explanation": "语义：「方言化」指使事物带上地方方言的色彩，与「设计」的语境不合。"}, {"text": "粗糙化", "is_correct": false, "explanation": "语义：「粗糙化」指使东西变得不光滑，与设计师「很满意」的评价相冲突。"}, {"text": "艺术化", "is_correct": true, "explanation": "正确：「艺术化设计」指经过艺术手法加工的设计，与「很满意」的评价相符。"}, {"text": "石化", "is_correct": false, "explanation": "搭配：「石化」指变成石头或石油化工，不能修饰「房间的设计」。"}], "explanations": {"方言化": "语义：「方言化」指使事物带上地方方言的色彩，与「设计」的语境不合。", "粗糙化": "语义：「粗糙化」指使东西变得不光滑，与设计师「很满意」的评价相冲突。", "艺术化": "正确：「艺术化设计」指经过艺术手法加工的设计，与「很满意」的评价相符。", "石化": "搭配：「石化」指变成石头或石油化工，不能修饰「房间的设计」。"}, "sentence_index": 6, "correct_answer": "艺术化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人艺术化了堵塞的下水道。", "explanation": "这里应该用〈疏通〉。「艺术化」指用艺术手法加工事物，使其具有艺术特性；疏通堵塞的下水道是功能性处理，不说「艺术化」。"}, {"text": "这份计划需要艺术化，先把时间安排好。", "explanation": "这里应该用〈调整〉。「艺术化」偏重审美加工，计划的修改和时间安排应说「调整」。"}, {"text": "墙上的裂缝需要艺术化，防止继续开裂。", "explanation": "这里应该用〈修补〉。「艺术化」不表示修补或加固结构，处理裂缝应说「修补」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家餐厅对菜品做了艺术化地处理。", "corrected_sentence": "这家餐厅对菜品做了艺术化的处理。", "error_description": "助词错误：「艺术化」修饰名词「处理」，作定语，应该用「的」，不用「地」。「地」用在状语和动词之间。正确说法是「做了艺术化的处理」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把这些老房子艺术化。", "corrected_sentence": "他们把这些老房子艺术化了。", "error_description": "错误形式：「把这些老房子艺术化」后缺少「了」。正确形式：「把这些老房子艺术化了」。原因：「把」字句中动词后要带「了」或其他补充成分，句子才完整，只说「把……艺术化」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
