INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12133, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物理学的一个分支，研究物体运动状态变化与所受力的关系。", "primary_collocate": null, "pronunciation": "dòng lì xué", "ipa": "tʊŋ˥˩ li˥˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "研究人员用动力学方法分析了列车的运动。", "target_word": "动力学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "在工程课上，老师讲解了动力学的基本概念。", "target_word": "动力学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "学习动力学，需要先掌握牛顿运动定律。", "target_word": "动力学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "动力学的理论可以用来预测物体运动的变化。", "target_word": "动力学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "动力学和热力学是物理学中不同的分支。", "target_word": "动力学", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "动力学研究力和物体运动的关系。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学里选修了动力学这门课。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球为什么越滚越慢？动力学能回答这个问题。", "target_word": "动力学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动力学是物理学的一个分支。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师用动力学算出了车的加速度。", "target_word": "动力学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物理学分支：研究力与物体运动变化的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9032895-3c87-4536-a6ce-a44d1ddecd4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供儿童玩耍的物品，不能作分析的方法。"}, {"text": "大腕", "is_correct": false, "explanation": "语域：「大腕」是口语，指有名望的人，不能用在「方法」前。"}, {"text": "动力学", "is_correct": true, "explanation": "正确。「动力学方法」指用动力学理论分析问题，与句意相符。"}, {"text": "零食", "is_correct": false, "explanation": "语义：零食是食品，不能用来分析列车的运动。"}], "explanations": {"玩具": "语义：玩具是供儿童玩耍的物品，不能作分析的方法。", "大腕": "语域：「大腕」是口语，指有名望的人，不能用在「方法」前。", "动力学": "正确。「动力学方法」指用动力学理论分析问题，与句意相符。", "零食": "语义：零食是食品，不能用来分析列车的运动。"}, "sentence_index": 0, "correct_answer": "动力学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动力学只描述物体怎样运动，不考虑力。", "explanation": "这里应该用〈运动学〉。运动学只描述运动，不研究力；动力学研究力与运动的关系，与“不考虑力”相矛盾。"}, {"text": "这辆车的动力学很强。", "explanation": "这里应该用〈动力〉。“动力”指发动机输出的力量，“动力学”是学科名，不能用来形容车的动力。"}, {"text": "动力学研究能量与热的转化。", "explanation": "这里应该用〈热力学〉。热力学研究能量与热的转化，动力学研究力与运动的关系，不研究热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不能作大学课程的名称。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不能作大学课程的名称。"}, {"text": "动力学", "is_correct": true, "explanation": "正确：“动力学”是物理学的分支，可以作为大学课程的名称。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，不能作大学课程的名称。"}], "explanations": {"感冒": "语义：感冒是一种疾病，不能作大学课程的名称。", "鸡蛋": "语义：鸡蛋是食物，不能作大学课程的名称。", "动力学": "正确：“动力学”是物理学的分支，可以作为大学课程的名称。", "沙发": "语义：“沙发”是家具，不能作大学课程的名称。"}, "sentence_index": 6, "correct_answer": "动力学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "动力学研究静止的物体，不研究运动。", "explanation": "这里应该用〈静力学〉。静力学研究静止物体的受力，动力学研究运动的变化，与“不研究运动”相矛盾。"}, {"text": "动力学研究光的传播和反射。", "explanation": "这里应该用〈光学〉。光学研究光的传播与反射，动力学研究物体运动与力的关系。"}, {"text": "动力学研究生物的遗传规律。", "explanation": "这里应该用〈遗传学〉。遗传学研究生物的遗传规律，“动力学”研究物体运动与所受力的关系，不研究生物遗传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期选修了两只动力学课。", "corrected_sentence": "他这学期选修了两门动力学课。", "error_description": "量词错误：“动力学课”应搭配量词“门”，“只”用于动物等，应说“两门动力学课”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师已经讲了完动力学。", "corrected_sentence": "老师已经讲完了动力学。", "error_description": "补语位置错误：“讲完”是结果补语，“了”应放在“完”之后，说“讲完了动力学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
