INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12135, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12135, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大气层是包裹在地球或其他天体外部的一层气体混合物，对地球上的生命起到保护作用。", "primary_collocate": null, "pronunciation": "dà qì céng", "ipa": "ta˥˩ tɕʰi˥˩ tsʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "大气层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大气层保护着地球上的生命。", "target_word": "大气层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空船回到地球时要穿过大气层。", "target_word": "大气层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大气层里有很多空气。", "target_word": "大气层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "流星进入大气层就会燃烧。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球外面包着厚厚的大气层。", "target_word": "大气层", "complexity_tier": "T3", "furigana": "dà qì céng", "sentence_source": "generated"}, {"text": "大气层能挡住太阳的有害光线。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮没有像地球那样的大气层。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有大气层，地球上就没有生命。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机通常在大气层的下层飞行。", "target_word": "大气层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "包裹天体外部、保护生命的气体层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa298e6-cfcf-449f-90b9-c2a575b9f960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12135, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大气层", "is_correct": true, "explanation": "正确：飞机穿行的空间就是包围地球的大气层，句意通顺。"}, {"text": "客厅", "is_correct": false, "explanation": "语义：飞机不可能在客厅中穿行，与句子描写的高空飞行相矛盾。"}, {"text": "地下室", "is_correct": false, "explanation": "语义：地下室位于地下，飞机在其中穿行与高空飞行的语境不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“穿行”要求有可以通过的空间，玻璃是材料，不能作为飞机穿行的空间。"}], "explanations": {"大气层": "正确：飞机穿行的空间就是包围地球的大气层，句意通顺。", "客厅": "语义：飞机不可能在客厅中穿行，与句子描写的高空飞行相矛盾。", "地下室": "语义：地下室位于地下，飞机在其中穿行与高空飞行的语境不符。", "玻璃": "搭配：“穿行”要求有可以通过的空间，玻璃是材料，不能作为飞机穿行的空间。"}, "sentence_index": 0, "correct_answer": "大气层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在地球上空看到一座大气层。", "explanation": "这里应该用〈层〉。大气层是包围地球的一层气体，量词要用〈层〉；〈座〉多用于山、楼等大型建筑或山体，不能用来称量大气层。"}, {"text": "宇航员在大气层里漫步，四周是无边的太空。", "explanation": "这里不能用〈大气层〉指宇航员漫步的地方。大气层是包围地球的一层气体，宇航员漫步处在它之外的宇宙空间中，不能说在大气层里。"}, {"text": "这个房间里的大气层很干净。", "explanation": "这里应该用〈空气〉。大气层指包围地球的整层气体，不能用来指房间里的空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大气层", "is_correct": true, "explanation": "正确：大气层是能挡住有害光线的保护层，句意通顺。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文字作品，不能挡住太阳光线，与句子描述的物理作用不符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能挡住太阳的有害光线，句子说的是天体外围的防护层。"}, {"text": "喇叭", "is_correct": false, "explanation": "语义：喇叭是发声的器具，不能挡住太阳的光线，与句子描述的防护作用不符。"}], "explanations": {"大气层": "正确：大气层是能挡住有害光线的保护层，句意通顺。", "小说": "语义：小说是文字作品，不能挡住太阳光线，与句子描述的物理作用不符。", "饼干": "语义：饼干是食品，不能挡住太阳的有害光线，句子说的是天体外围的防护层。", "喇叭": "语义：喇叭是发声的器具，不能挡住太阳的光线，与句子描述的防护作用不符。"}, "sentence_index": 6, "correct_answer": "大气层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天都在呼吸干净的大气层。", "explanation": "这里应该用〈空气〉。大气层是包围地球的整层气体，不能说呼吸整层大气层；人呼吸的是其中的空气。"}, {"text": "工人正在大气层上铺一条新路。", "explanation": "这里应该用〈地面〉。铺路要在地面上进行，大气层是包围地球的气体层，不能被铺设。"}, {"text": "我们在大气层里养了一群鱼。", "explanation": "这里应该用〈池塘〉。鱼要生活在水中，大气层是包围地球的气体层，不能用来养鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球外面有一座厚厚的大气层。", "corrected_sentence": "地球外面有一层厚厚的大气层。", "error_description": "量词错误：大气层是一层气体，应用量词“层”，不能用“座”（座多用于山、楼等大型物体）。错误句中的“一座”应改为“一层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大气层有地球周围。", "corrected_sentence": "大气层在地球周围。", "error_description": "错误形式：「大气层有地球周围」。正确形式：「大气层在地球周围」。原因：「有」表示存在，其后接存在的事物，不能接地点；表示事物位于某处，应用介词「在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
