INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个地方或空间中间通过。", "primary_collocate": null, "pronunciation": "chuān xíng", "ipa": "tʂʰuan˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "穿行", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小船在窄窄的河道中穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车在山中穿行。", "target_word": "穿行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在人群中穿行，很快到了门口。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鱼在水草间穿行。", "target_word": "穿行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汽车在城市的小路上穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车的人在车流中穿行。", "target_word": "穿行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在云层中穿行。", "target_word": "穿行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的车在大雾中穿行了很久。", "target_word": "穿行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在花丛中穿行。", "target_word": "穿行", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿行了", "label": "体标"}, {"form": "穿行着", "label": "体标"}, {"form": "穿行过", "label": "体标"}], "register": "书面", "sense_fingerprint": "在某个空间或物体中间通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2aa298e6-cfcf-449f-90b9-c2a575b9f960') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿行", "is_correct": true, "explanation": "正确：飞机在大气层中移动着通过，与句意相符。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：飞机在大气层中是飞行而不是挖掘，“挖掘”要求挖开实物，与飞行情境不符。"}, {"text": "漫步", "is_correct": false, "explanation": "语义：“漫步”指人悠闲地行走，高速飞行的飞机不能漫步。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要水等可以游的液体作为环境，不能用于飞机在大气层中。"}], "explanations": {"穿行": "正确：飞机在大气层中移动着通过，与句意相符。", "挖掘": "语义：飞机在大气层中是飞行而不是挖掘，“挖掘”要求挖开实物，与飞行情境不符。", "漫步": "语义：“漫步”指人悠闲地行走，高速飞行的飞机不能漫步。", "游泳": "搭配：“游泳”需要水等可以游的液体作为环境，不能用于飞机在大气层中。"}, "sentence_index": 0, "correct_answer": "穿行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的讲话中穿行了许多笑话。", "explanation": "这里应该用〈穿插〉。穿插指夹杂在其中，穿行指人或物从中间通过，不能用来表示笑话夹杂在讲话里。"}, {"text": "这张桌子在人群中穿行，很快到了门口。", "explanation": "这里应该用〈搬〉。穿行的主语须能自己移动，桌子不能自行穿行，只能被人搬过去。"}, {"text": "他穿行在躺椅上，很快睡着了。", "explanation": "这里应该用〈坐〉。穿行指从中间通过，不能用来形容坐在躺椅上不动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿行", "is_correct": true, "explanation": "正确：骑车的人在车流中移动着通过，句意通顺。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：骑车的人在车流中处于行进状态，不能说在车流中睡觉，与句子情境矛盾。"}, {"text": "耕种", "is_correct": false, "explanation": "搭配：“耕种”需要土地作为对象，车流中不能耕种。"}, {"text": "冥想", "is_correct": false, "explanation": "语义：冥想是静坐思考，与骑车在车流中行进的情境矛盾。"}], "explanations": {"穿行": "正确：骑车的人在车流中移动着通过，句意通顺。", "睡觉": "语义：骑车的人在车流中处于行进状态，不能说在车流中睡觉，与句子情境矛盾。", "耕种": "搭配：“耕种”需要土地作为对象，车流中不能耕种。", "冥想": "语义：冥想是静坐思考，与骑车在车流中行进的情境矛盾。"}, "sentence_index": 6, "correct_answer": "穿行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子在花丛中穿行。", "explanation": "这里应该用〈搬〉。穿行的主语须能自己移动，椅子不能自行穿行。"}, {"text": "孩子们在花丛中穿行了一封信。", "explanation": "这里应该用〈写〉。穿行指从中间通过，不能用来表示写信。"}, {"text": "孩子们在花丛中穿行了一首歌。", "explanation": "这里应该用〈唱〉。穿行指从中间通过，不能用来表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他胡同里穿行，很快找到了那家店。", "corrected_sentence": "他在胡同里穿行，很快找到了那家店。", "error_description": "缺少介词“在”：处所“胡同里”作状语须由“在”引出，应说“在胡同里穿行”，不能省去“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在花丛中穿行的很快。", "corrected_sentence": "孩子们在花丛中穿行得很快。", "error_description": "补语误用：“穿行”后接程度补语“很快”，须用“得”引出，应说“穿行得很快”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef23cb6c-5aaf-4596-acdb-f4b90f406b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
