INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机翼是飞机两侧用来产生升力、保持飞行的部件。", "primary_collocate": null, "pronunciation": "jī yì", "ipa": "tɕi˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机在不同飞行阶段（如起飞、巡航、降落）所面临的气动挑战各异，要求机翼形态（如襟翼与缝翼的展开）能够动态适应。", "target_word": "机翼", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机的机翼能产生升力。", "target_word": "机翼", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机翼的形状影响飞机的升力。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在检查机翼上的零件。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这架飞机的机翼下方挂着两台发动机。", "target_word": "机翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员把襟翼放下，机翼的升力变大了。", "target_word": "机翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风洞实验测试了新型机翼的性能。", "target_word": "机翼", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对机翼", "label": "量词"}, {"form": "主机翼", "label": "复合"}], "register": "书面", "sense_fingerprint": "飞机两侧产生升力的部件，空气动力学语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。"}, {"text": "记忆", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是记住并能回想起的能力。"}, {"text": "机遇", "is_correct": false, "explanation": "第二个音节 yù 与 yì 的韵母不同（ü 对 i），意思是可以把握的好时机。"}, {"text": "机制", "is_correct": false, "explanation": "第二个音节 zhì 与 yì 的声母不同（zh 对零声母），意思是事物内部的运作方式。"}, {"text": "饥饿", "is_correct": false, "explanation": "第二个音节 è 与 yì 的韵母不同（e 对 i），意思是肚子空了、想吃东西的状态。"}, {"text": "奇异", "is_correct": false, "explanation": "第一个音节 qí 与 jī 声母不同（q 对 j），声调也不同（第二声对第一声），意思是奇特、与众不同。"}], "explanations": {"机翼": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。", "记忆": "jì（第四声）与 jī（第一声）声调不同，意思是记住并能回想起的能力。", "机遇": "第二个音节 yù 与 yì 的韵母不同（ü 对 i），意思是可以把握的好时机。", "机制": "第二个音节 zhì 与 yì 的声母不同（zh 对零声母），意思是事物内部的运作方式。", "饥饿": "第二个音节 è 与 yì 的韵母不同（e 对 i），意思是肚子空了、想吃东西的状态。", "奇异": "第一个音节 qí 与 jī 声母不同（q 对 j），声调也不同（第二声对第一声），意思是奇特、与众不同。"}, "sentence_index": null, "correct_answer": "机翼"}, "level_3": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确：机翼是飞机两侧产生升力的部件，与气流相互作用，决定飞行的可行性。"}, {"text": "车轮", "is_correct": false, "explanation": "语义：车轮属于陆上车辆，与在大气层中穿行的飞机无关。"}, {"text": "羽毛", "is_correct": false, "explanation": "语义：羽毛是鸟类的体表结构，飞机没有羽毛。"}, {"text": "齿轮", "is_correct": false, "explanation": "语义：齿轮是机械传动部件，不在大气中与气流作用，也不决定飞机能否飞行。"}], "explanations": {"机翼": "正确：机翼是飞机两侧产生升力的部件，与气流相互作用，决定飞行的可行性。", "车轮": "语义：车轮属于陆上车辆，与在大气层中穿行的飞机无关。", "羽毛": "语义：羽毛是鸟类的体表结构，飞机没有羽毛。", "齿轮": "语义：齿轮是机械传动部件，不在大气中与气流作用，也不决定飞机能否飞行。"}, "sentence_index": 0, "correct_answer": "机翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟张开机翼飞走了。", "explanation": "这里应该用〈翅膀〉。机翼专指飞机两侧的部件，鸟类的翅膀要说“翅膀”。"}, {"text": "这架直升机的机翼飞快地转动，带起一阵大风。", "explanation": "这里应该用〈旋翼〉。直升机的旋翼绕轴转动，机翼是固定在机身两侧的翼面，不会转动。"}, {"text": "工程师修好了一把机翼。", "explanation": "这里应该用〈个〉或〈对〉。“把”用于有柄的器具，机翼不用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。"}, {"text": "机器", "is_correct": false, "explanation": "第二个音节 qì 与 yì 的声母不同（q 对零声母），意思是利用能量做功的装置。"}, {"text": "积极", "is_correct": false, "explanation": "第二个音节 jí 与 yì 的声母和声调都不同，意思是主动、肯定的态度。"}, {"text": "极易", "is_correct": false, "explanation": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。"}, {"text": "技艺", "is_correct": false, "explanation": "第一个音节 jì（第四声）与 jī（第一声）声调不同，意思是技术和本领。"}], "explanations": {"机翼": "正确答案：机翼 jī yì，指飞机两侧产生升力的部件。", "机器": "第二个音节 qì 与 yì 的声母不同（q 对零声母），意思是利用能量做功的装置。", "积极": "第二个音节 jí 与 yì 的声母和声调都不同，意思是主动、肯定的态度。", "极易": "第一个音节 jí（第二声）与 jī（第一声）声调不同，意思是非常容易。", "技艺": "第一个音节 jì（第四声）与 jī（第一声）声调不同，意思是技术和本领。"}, "sentence_index": null, "correct_answer": "机翼"}, "level_3": {"options": [{"text": "机翼", "is_correct": true, "explanation": "正确：机翼是飞机上的部件，工程师检查的是机翼上的零件。"}, {"text": "树", "is_correct": false, "explanation": "语义：树上没有需要工程师检查的零件，句中指的是飞机部件。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币上不会有需要工程师检查的零件，与语境不合。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：“检查”可以用于病人（检查身体），但“病人上的零件”不成立，零件应指机器部件。"}], "explanations": {"机翼": "正确：机翼是飞机上的部件，工程师检查的是机翼上的零件。", "树": "语义：树上没有需要工程师检查的零件，句中指的是飞机部件。", "硬币": "语义：硬币上不会有需要工程师检查的零件，与语境不合。", "病人": "搭配：“检查”可以用于病人（检查身体），但“病人上的零件”不成立，零件应指机器部件。"}, "sentence_index": 6, "correct_answer": "机翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "风力发电机的机翼在风中慢慢转动。", "explanation": "这里应该用〈叶片〉。风力发电机的旋转部件叫叶片，机翼专指飞机的部件。"}, {"text": "无人机的机翼飞快地转动。", "explanation": "这里应该用〈螺旋桨〉。螺旋桨绕轴转动，机翼是固定在机身两侧的翼面，不会转动。"}, {"text": "工人把一扇机翼搬进了车间。", "explanation": "这里应该用〈个〉或〈对〉。“扇”用于门窗，机翼不能用“扇”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "检修人员在机场检查机翼了很久。", "corrected_sentence": "检修人员在机场检查机翼检查了很久。", "error_description": "语序错误：动词带宾语“机翼”又带时量补语“很久”时，须重复动词（检查机翼检查了很久），或把宾语提前（把机翼检查了很久），不能说“检查机翼了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师在车间里把机翼检查着一遍。", "corrected_sentence": "工程师在车间里把机翼检查了一遍。", "error_description": "体标错误：动量补语“一遍”前的动词应使用完成体“了”，“着”表示持续，不能与“一遍”搭配，应说“把机翼检查了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
