INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "流动的空气，通常指风或呼吸时进出的气体。", "primary_collocate": null, "pronunciation": "qì liú", "ipa": "tɕʰi˥˩ liou˧˥", "syllable_count": 2, "sentences": [{"text": "风车作为中世纪最具象征性的技术装置，通过叶片捕捉气流动能，驱动磨坊碾磨谷物或抽排沼泽积水。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这一过程的核心在于升力的生成机制——机翼上表面的气流因曲率较大而流速加快，导致压力降低；相比之下，下表面的气流流速较慢，压力相对较高。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种压力差垂直于气流方向，形成向上的净力，即升力。", "target_word": "气流", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "气流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一股气流从门缝里吹进来。", "target_word": "气流", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机遇到气流，上下摇了起来。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里的气流把风筝送上了天。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸气时，气流从鼻子进入身体。", "target_word": "气流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股气流", "label": "量词"}, {"form": "上升气流", "label": "复合"}], "register": "中性", "sense_fingerprint": "流动的空气，如风或呼吸的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：气流 qì liú，意思是流动的空气。"}, {"text": "细流", "is_correct": false, "explanation": "细流 xìliú 的声母 x 与 q 不同，声调相同（第四声），意思是细小的水流。"}, {"text": "激流", "is_correct": false, "explanation": "激流 jīliú 的声母 j 与 q 不同，声调也变为第一声，意思是急速的水流。"}, {"text": "溪流", "is_correct": false, "explanation": "溪流 xīliú 的声母 x 与 q 不同，声调变为第一声，意思是小河。"}], "explanations": {"气流": "正确：气流 qì liú，意思是流动的空气。", "细流": "细流 xìliú 的声母 x 与 q 不同，声调相同（第四声），意思是细小的水流。", "激流": "激流 jīliú 的声母 j 与 q 不同，声调也变为第一声，意思是急速的水流。", "溪流": "溪流 xīliú 的声母 x 与 q 不同，声调变为第一声，意思是小河。"}, "sentence_index": null, "correct_answer": "气流"}, "level_3": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：“气流”指流动的空气，风车叶片借此获取动能。"}, {"text": "水流", "is_correct": false, "explanation": "语义：风车靠风转动，应当捕捉的是气流，不是水流。"}, {"text": "人流", "is_correct": false, "explanation": "语义：“人流”指人群的移动，与叶片捕捉风的动能无关。"}, {"text": "声浪", "is_correct": false, "explanation": "搭配：叶片靠风的流动转动，不能“捕捉”声浪的动能。"}], "explanations": {"气流": "正确：“气流”指流动的空气，风车叶片借此获取动能。", "水流": "语义：风车靠风转动，应当捕捉的是气流，不是水流。", "人流": "语义：“人流”指人群的移动，与叶片捕捉风的动能无关。", "声浪": "搭配：叶片靠风的流动转动，不能“捕捉”声浪的动能。"}, "sentence_index": 0, "correct_answer": "气流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋里的气流很闷，人都喘不过气。", "explanation": "这里应该用〈空气〉。“闷”形容空气不流通；气流指流动的空气，流动时不能说闷。"}, {"text": "电线里有气流通过。", "explanation": "这里应该用〈电流〉。电线里通过的是电流；气流指流动的空气，不在电线里通过。"}, {"text": "屋外传来一阵奇怪的气流。", "explanation": "这里应该用〈声音〉。“传来”的是声音；气流是流动的空气，不用来表示“传来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气流", "is_correct": true, "explanation": "正确：“一股气流”是从门缝吹进来的流动空气，量词“股”搭配自然。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“吹”进来的是风或气体，水不能被“吹”进门缝。"}, {"text": "怒气", "is_correct": false, "explanation": "语义：“怒气”是情绪，不能从门缝里被吹进来。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不是可以从门缝吹进来的东西。"}], "explanations": {"气流": "正确：“一股气流”是从门缝吹进来的流动空气，量词“股”搭配自然。", "水": "搭配：“吹”进来的是风或气体，水不能被“吹”进门缝。", "怒气": "语义：“怒气”是情绪，不能从门缝里被吹进来。", "脾气": "语义：“脾气”指性情，不是可以从门缝吹进来的东西。"}, "sentence_index": 6, "correct_answer": "气流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河里的气流很急。", "explanation": "这里应该用〈水流〉。河里流动的是水，气流指空气的流动，不能说“河里的气流”。"}, {"text": "他心里憋着一股气流。", "explanation": "这里应该用〈怒气〉。“憋着一股气”指压在心里的情绪；气流只指流动的空气，不能用于情绪。"}, {"text": "气流在血管里很快地流动。", "explanation": "这里应该用〈血流〉。血管里流动的是血液，气流指空气的流动，不能在血管中流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "午后，一颗凉爽的气流从窗口吹进来。", "corrected_sentence": "午后，一股凉爽的气流从窗口吹进来。", "error_description": "错误形式：“一颗凉爽的气流”。正确形式：“一股凉爽的气流”。“气流”要用量词“股”，不能用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几股气流们从门缝里吹进来。", "corrected_sentence": "几股气流从门缝里吹进来。", "error_description": "错误：“们”只用于人或拟人化的人称，不能接在“气流”后表示复数，应去掉“们”，说“几股气流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
