INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个或更多事物之间互相影响、互相作用的过程。", "primary_collocate": null, "pronunciation": "xiāng hù zuò yòng", "ipa": "ɕjɑŋ˥ xu˥˩ tsuo˥˩ jʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "当一架飞机在大气层中穿行时，其机翼与气流之间的相互作用决定了飞行的基本可行性。", "target_word": "相互作用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两种力之间有相互作用。", "target_word": "相互作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "药物之间的相互作用很重要。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳和地球有引力的相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究人员观察了两种蛋白质的相互作用。", "target_word": "相互作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人与环境的相互作用不能忽视。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "分子之间的相互作用决定了物质的性质。", "target_word": "相互作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生很了解药物的相互作用。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "磁铁靠近时，两块磁铁出现了相互作用。", "target_word": "相互作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教学是老师和学生的相互作用过程。", "target_word": "相互作用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "相互作用力", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物之间互相影响的过程，名词用法，科学语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互作用", "is_correct": true, "explanation": "正确：相互作用指两个事物互相影响的过程，句中指机翼与气流之间的互相影响。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是外观属性，不能描述两者互相影响的过程。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是买卖中的数额，与气流和机翼的作用无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感官属性，不能决定飞行的可行性。"}], "explanations": {"相互作用": "正确：相互作用指两个事物互相影响的过程，句中指机翼与气流之间的互相影响。", "颜色": "语义：颜色是外观属性，不能描述两者互相影响的过程。", "价格": "语义：价格是买卖中的数额，与气流和机翼的作用无关。", "味道": "语义：味道是感官属性，不能决定飞行的可行性。"}, "sentence_index": 0, "correct_answer": "相互作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的相互作用有三张卷子，我一上午就做完了。", "explanation": "这里应该用〈试卷〉。相互作用是抽象的过程，不能用“张”计量，也不能指卷子。"}, {"text": "这块蛋糕的相互作用很甜，大家都很爱吃。", "explanation": "这里应该用〈味道〉。相互作用指事物之间互相影响的过程，不能用来形容食物的甜淡。"}, {"text": "这家公司去年的相互作用很便宜，所以大家都买了。", "explanation": "这里应该用〈产品〉。相互作用是抽象的过程，不能说“便宜”，也不能被购买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互作用", "is_correct": true, "explanation": "正确：分子之间互相影响的过程决定了物质的性质。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，与分子之间的作用无关。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不存在于分子之间，句中是物理化学语境。"}, {"text": "亲情", "is_correct": false, "explanation": "搭配：“亲情”用于人与人之间，不与“分子之间”搭配。"}], "explanations": {"相互作用": "正确：分子之间互相影响的过程决定了物质的性质。", "工资": "语义：工资是劳动报酬，与分子之间的作用无关。", "歌曲": "语义：歌曲不存在于分子之间，句中是物理化学语境。", "亲情": "搭配：“亲情”用于人与人之间，不与“分子之间”搭配。"}, "sentence_index": 6, "correct_answer": "相互作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节课里有一块相互作用很有意思。", "explanation": "这里应该用〈种〉或〈个〉。“块”用于成块的实物，相互作用是抽象的过程，不能用“块”计量。"}, {"text": "老师和学生之间有深厚的相互作用。", "explanation": "这里应该用〈感情〉。相互作用指双方互相影响的过程，不能用来形容感情的深浅。"}, {"text": "学生承受着很大的相互作用。", "explanation": "这里应该用〈压力〉。相互作用指双方互相影响的过程，不能被“承受”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师和学生之间地相互作用影响了学习效果。", "corrected_sentence": "老师和学生之间的相互作用影响了学习效果。", "error_description": "结构助词错误：修饰名词“相互作用”应用“的”，“地”用于修饰动词，不能放在名词前。正确说法是“老师和学生之间的相互作用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两种物质之间产生着了很微妙的相互作用。", "corrected_sentence": "两种物质之间产生了很微妙的相互作用。", "error_description": "体标错误：“着”与“了”不能叠用在同一个动词后。这里表示已经出现的结果，应只用“了”：“产生了很微妙的相互作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
