INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指承受的负担或紧张状态。", "primary_collocate": null, "pronunciation": "yā lì", "ipa": "ja˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "长期的压力会影响健康。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作压力太大，他晚上睡不好。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，同学们的压力都很大。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都要面对很多压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动可以帮你减轻压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有给我们压力，只是鼓励我们。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在压力下做出了决定。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸最近压力很大，常常叹气。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对压力，要学会放松自己。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐能缓解压力。", "target_word": "压力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "壓力", "label": "繁体"}], "register": "中性", "sense_fingerprint": "承受的负担、紧张状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压力", "is_correct": true, "explanation": "压力：指长期承受的负担或紧张状态，与“影响健康”相符。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“长期的速度”不成立，速度不是会影响健康的事物。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会长期影响健康，与句意不符。"}, {"text": "面积", "is_correct": false, "explanation": "语义：面积不会长期影响健康，与句意不符。"}], "explanations": {"压力": "压力：指长期承受的负担或紧张状态，与“影响健康”相符。", "速度": "搭配：“长期的速度”不成立，速度不是会影响健康的事物。", "颜色": "语义：颜色不会长期影响健康，与句意不符。", "面积": "语义：面积不会长期影响健康，与句意不符。"}, "sentence_index": 0, "correct_answer": "压力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的压力很好，一口气跑了十公里。", "explanation": "这里应该用〈体力〉。“压力”指承受的负担或紧张状态，不指身体的力气；说身体的力气要用“体力”。"}, {"text": "这道菜的压力太咸了，几乎没法吃。", "explanation": "这里应该用〈味道〉。“压力”指承受的负担或紧张状态，不指食物的口味；说口味要用“味道”。"}, {"text": "这辆车的压力很快，一下子就超过了前车。", "explanation": "这里应该用〈速度〉。“压力”指承受的负担或紧张状态，不指车的快慢；说车的快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压力", "is_correct": true, "explanation": "压力：指人在紧张或负担之下的状态，与“做出决定”的语境相符。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“在…下”后接的是状态或条件，“音量”不能作为做决定的条件。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不能作为做决定的条件，与句中的心理状态不符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包与“做出决定”无关，不能作为条件。"}], "explanations": {"压力": "压力：指人在紧张或负担之下的状态，与“做出决定”的语境相符。", "音量": "搭配：“在…下”后接的是状态或条件，“音量”不能作为做决定的条件。", "花朵": "语义：花朵不能作为做决定的条件，与句中的心理状态不符。", "面包": "语义：面包与“做出决定”无关，不能作为条件。"}, "sentence_index": 6, "correct_answer": "压力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把压力从书架上搬了下来，放在桌子上。", "explanation": "这里应该用〈书〉。“压力”指承受的负担或紧张状态，是抽象的，不是能搬动的实物；要说搬东西，应该换成“书”。"}, {"text": "这块布的压力很厚，可以做冬衣。", "explanation": "这里应该用〈厚度〉。“压力”指承受的负担或紧张状态，不指布的厚薄；说布的厚薄要用“厚度”。"}, {"text": "这首歌的压力很优美，我反复听了好几遍。", "explanation": "这里应该用〈旋律〉。“压力”指承受的负担或紧张状态，不指歌曲的旋律；说歌曲的好听之处要用“旋律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他感到一只很大的压力。", "corrected_sentence": "他感到一股很大的压力。", "error_description": "量词错误：“压力”是抽象名词，应该用“股”（一股压力），不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有很压力，常常睡不好。", "corrected_sentence": "他有很大的压力，常常睡不好。", "error_description": "错误：“很”是副词，不能直接修饰名词“压力”，应加形容词“大”，写作“很大的压力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
