INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12151, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "正确：“好”与“差”构成反义，指质量、状况良好。"}, {"text": "快", "is_correct": false, "explanation": "快：形容速度，与“差”不构成反义。"}, {"text": "大", "is_correct": false, "explanation": "大：形容大小，与“差”不构成反义。"}, {"text": "长", "is_correct": false, "explanation": "长：形容长短，与“差”不构成反义。"}], "correct_answer": "好", "explanations": {"好": "正确：“好”与“差”构成反义，指质量、状况良好。", "快": "快：形容速度，与“差”不构成反义。", "大": "大：形容大小，与“差”不构成反义。", "长": "长：形容长短，与“差”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12151, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示不好、不够标准或缺少。", "primary_collocate": null, "pronunciation": "chà", "ipa": "ʈʂʰɑ˥˩", "syllable_count": 1, "sentences": [{"text": "这台旧电脑的运行速度比新的差。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的服务比以前差多了。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在差五分八点，我们快走吧。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还差十块钱，你能借我吗？", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们还差两个人，比赛不能开始。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平比我差。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试他考得很差。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的内容太差，需要重新写。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这道菜，只差一点盐了。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体比去年差了。", "target_word": "差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示不够标准、水平低，或数量上缺少，如“差五分八点”“还差十块钱”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0613f2b4-d7bd-4ccb-9ae8-298ca11c53e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12151, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：差 chà，表示不好、不够或缺少。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是茶。"}, {"text": "查", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是检查。"}, {"text": "察", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是观察。"}], "explanations": {"差": "正确：差 chà，表示不好、不够或缺少。", "茶": "chá（第二声）与 chà（第四声）声调不同，意思是茶。", "查": "chá（第二声）与 chà（第四声）声调不同，意思是检查。", "察": "chá（第二声）与 chà（第四声）声调不同，意思是观察。"}, "sentence_index": null, "correct_answer": "差"}, "level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：“差”表示不如，句中指旧电脑的运行速度不如新的。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”说价格高，不能用来比较运行速度。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”说物体的厚度，不能用来形容运行速度。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来比较运行速度。"}], "explanations": {"差": "正确：“差”表示不如，句中指旧电脑的运行速度不如新的。", "贵": "搭配：“贵”说价格高，不能用来比较运行速度。", "厚": "搭配：“厚”说物体的厚度，不能用来形容运行速度。", "甜": "搭配：“甜”说味道，不能用来比较运行速度。"}, "sentence_index": 0, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服太差了，我买不起。", "explanation": "这里应该用〈贵〉。“差”说质量不好或数量不够，价格高、买不起要用“贵”。"}, {"text": "今天的气温很差，要多穿点衣服。", "explanation": "这里应该用〈低〉。气温只有高低，不能用“差”来说。"}, {"text": "他家离学校很差，要坐一个小时车。", "explanation": "这里应该用〈远〉。距离要用“远”或“近”，不能用“差”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12151, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：差 chà，表示不好、不够或缺少。"}, {"text": "插", "is_correct": false, "explanation": "chā（第一声）与 chà（第四声）声调不同，意思是插入。"}, {"text": "叉", "is_correct": false, "explanation": "chā（第一声）与 chà（第四声）声调不同，意思是叉子。"}, {"text": "查", "is_correct": false, "explanation": "chá（第二声）与 chà（第四声）声调不同，意思是检查。"}], "explanations": {"差": "正确：差 chà，表示不好、不够或缺少。", "插": "chā（第一声）与 chà（第四声）声调不同，意思是插入。", "叉": "chā（第一声）与 chà（第四声）声调不同，意思是叉子。", "查": "chá（第二声）与 chà（第四声）声调不同，意思是检查。"}, "sentence_index": null, "correct_answer": "差"}, "level_3": {"options": [{"text": "差", "is_correct": true, "explanation": "正确：“考得很差”说明成绩不好，与句中的“考试”相符。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，“考得很辣”说不通，不能描述考试情况。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“深”形容深浅，“考得很深”说不通，不能描述成绩。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“考得很远”无法说明成绩的好坏。"}], "explanations": {"差": "正确：“考得很差”说明成绩不好，与句中的“考试”相符。", "辣": "搭配：“辣”形容味道，“考得很辣”说不通，不能描述考试情况。", "深": "搭配：“深”形容深浅，“考得很深”说不通，不能描述成绩。", "远": "搭配：“考得很远”无法说明成绩的好坏。"}, "sentence_index": 6, "correct_answer": "差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的年龄很差，身体还很好。", "explanation": "这里应该用〈大〉。“差”说质量或水平不好，年龄的多少要用“大”或“小”。"}, {"text": "他的身高很差，篮球打得很好。", "explanation": "这里应该用〈高〉。“差”说质量或水平不好，身高的高低要用“高”或“矮”。"}, {"text": "他是我的长辈，辈分很差。", "explanation": "这里应该用〈高〉。“差”说质量不好，辈分的高低要用“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次数学考得差很，老师很失望。", "corrected_sentence": "他这次数学考得很差，老师很失望。", "error_description": "语序错误：程度副词“很”应放在形容词“差”之前，应说“考得很差”，不能说“差很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这学期期中考试考很差，很失望。", "corrected_sentence": "他这学期期中考试考得很差，很失望。", "error_description": "补语错误：“考”后面的状态补语要用“得”，应说“考得很差”，不能说“考很差”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '365c456c-a712-428c-80ca-3ff86dbb1a05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
