INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "在几何中，指一条直线与另一条直线或平面相交成90度角。", "primary_collocate": null, "pronunciation": "chuí zhí yú", "ipa": "ʈʂʰweɪ˧˥ ʈʂɨ˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "这种压力差垂直于气流方向，形成向上的净力，即升力。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这条直线垂直于平面，和平面成90度角。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三角形的高垂直于底边。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子的腿垂直于桌面。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条线相交成直角，所以一条垂直于另一条。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在纸上画了一条垂直于横线的竖线。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙壁垂直于地板，所以房间是方的。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗杆垂直于地面，站得很直。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架的侧板垂直于底板。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆的直径垂直于弦时，会把弦分成两半。", "target_word": "垂直于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垂直於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "几何：直线与直线或平面相交成直角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垂直于", "is_correct": true, "explanation": "正确：垂直于表示压力差与气流方向成直角，才能形成向上的净力。"}, {"text": "平行于", "is_correct": false, "explanation": "语义：平行于与垂直于相反，平行的压力差无法形成向上的净力，与“即升力”相矛盾。"}, {"text": "远离", "is_correct": false, "explanation": "搭配：远离说离开某个处所，不能用来说压力差与气流方向的关系。"}, {"text": "迎着", "is_correct": false, "explanation": "配价：迎着要求一个迎面而来的对象，压力差不能迎着方向，句子也不通。"}], "explanations": {"垂直于": "正确：垂直于表示压力差与气流方向成直角，才能形成向上的净力。", "平行于": "语义：平行于与垂直于相反，平行的压力差无法形成向上的净力，与“即升力”相矛盾。", "远离": "搭配：远离说离开某个处所，不能用来说压力差与气流方向的关系。", "迎着": "配价：迎着要求一个迎面而来的对象，压力差不能迎着方向，句子也不通。"}, "sentence_index": 0, "correct_answer": "垂直于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两条线垂直于同一个点。", "explanation": "这里应该用〈相交于〉。垂直强调两线或线与面成直角，两线在一点相交才用〈相交于〉，不说垂直于一个点。"}, {"text": "他的看法垂直于我的看法。", "explanation": "用法错误：垂直于只用于几何或物理中的直角关系，不表示观点对立；观点相反应说〈相反〉。"}, {"text": "这个想法垂直于大家的期望。", "explanation": "这里应该用〈违背〉。垂直于只用于几何或物理中的直角关系，不用于想法与期望；想法与期望不合应说〈违背〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垂直于", "is_correct": true, "explanation": "正确：墙与地板成直角，房间才是方的。"}, {"text": "倾斜于", "is_correct": false, "explanation": "语义：倾斜表示不成直角，与“房间是方的”相矛盾。"}, {"text": "相距", "is_correct": false, "explanation": "配价：相距要求带距离或时间的宾语，不能直接带“于”接地板。"}, {"text": "位于", "is_correct": false, "explanation": "搭配：位于要求处所宾语，墙壁不说位于地板，应说位于……上。"}], "explanations": {"垂直于": "正确：墙与地板成直角，房间才是方的。", "倾斜于": "语义：倾斜表示不成直角，与“房间是方的”相矛盾。", "相距": "配价：相距要求带距离或时间的宾语，不能直接带“于”接地板。", "位于": "搭配：位于要求处所宾语，墙壁不说位于地板，应说位于……上。"}, "sentence_index": 6, "correct_answer": "垂直于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明垂直于老师，站在他旁边。", "explanation": "用法错误：垂直于只用于线与线、线与面成直角，不用于人与人的位置关系；这里应说〈靠近〉。"}, {"text": "这次比赛中，我们队垂直于对手。", "explanation": "用法错误：垂直于不表示比赛中的对抗；表示两队对抗应说〈对抗〉。"}, {"text": "红色垂直于蓝色，所以这幅画很好看。", "explanation": "用法错误：垂直于不用于颜色对比；颜色相互对照应说〈对比〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根柱子垂直于了地面，才能撑住屋顶。", "corrected_sentence": "这根柱子垂直于地面，才能撑住屋顶。", "error_description": "错误：“垂直于了地面”，“了”加在“垂直于”后面。正确：“垂直于地面”，表示几何关系，不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把尺子垂直于于桌边，才能画出直线。", "corrected_sentence": "这把尺子垂直于桌边，才能画出直线。", "error_description": "错误：“垂直于于桌边”，“于”重复。正确：“垂直于桌边”，“垂直于”只用一个“于”引出对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
