INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12153, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12153, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指几个力合成（相互抵消）后剩下的力，即物体实际受到的合力。", "primary_collocate": null, "pronunciation": "jìng lì", "ipa": "tɕiŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这种压力差垂直于气流方向，形成向上的净力，即升力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风和水的力量抵消后，剩下的就是净力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人用力方向相反，净力很小。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向右推的力大，所以净力向右。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体受到的净力为零时，会保持静止。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拉力减去摩擦力，就是小车受到的净力。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "净力越大，物体加速越快。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子受到的净力向上，所以它升起来了。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队拔河，力一样大时，净力是零。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：先算出净力，再看物体怎么动。", "target_word": "净力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "淨力", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物理：几个力互相抵消后剩下的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12153, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：净力指几个力合成后剩下的力。"}, {"text": "经历", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是经历。"}, {"text": "精力", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是精力。"}, {"text": "敬礼", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是敬礼。"}], "explanations": {"净力": "正确：净力指几个力合成后剩下的力。", "经历": "jīng（第一声）与 jìng（第四声）声调不同，意思是经历。", "精力": "jīng（第一声）与 jìng（第四声）声调不同，意思是精力。", "敬礼": "lǐ（第三声）与 lì（第四声）声调不同，意思是敬礼。"}, "sentence_index": null, "correct_answer": "净力"}, "level_3": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：向上的合力，即升力，就是这里的净力。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力方向与运动相反，不会形成向上的力，与“即升力”相矛盾。"}, {"text": "力气", "is_correct": false, "explanation": "语域：力气是口语中指人的体力，不能用于说明压力差产生升力的物理概念。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力方向向下，不能形成向上的力，与句中“向上”相矛盾。"}], "explanations": {"净力": "正确：向上的合力，即升力，就是这里的净力。", "阻力": "语义：阻力方向与运动相反，不会形成向上的力，与“即升力”相矛盾。", "力气": "语域：力气是口语中指人的体力，不能用于说明压力差产生升力的物理概念。", "重力": "语义：重力方向向下，不能形成向上的力，与句中“向上”相矛盾。"}, "sentence_index": 0, "correct_answer": "净力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车的净力很快，一会儿就到了学校。", "explanation": "这里应该用〈速度〉。净力指力的大小与方向，不表示快慢；说快慢要用〈速度〉。"}, {"text": "他的净力很大，一拳就把门打开了。", "explanation": "用法错误：净力是物理概念，指作用在物体上的合力，不用于说人的力气；人的力气应说〈力气〉。"}, {"text": "这家公司的净力增加了一倍。", "explanation": "用法错误：净力指物理中的合力，不指公司的利润；公司利润应说〈净利润〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12153, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：净力指几个力合成后剩下的力。"}, {"text": "尽力", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（n 与 ng），意思是尽力。"}, {"text": "劲力", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（n 与 ng），意思是力量。"}, {"text": "近利", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（n 与 ng），意思是眼前的利益。"}], "explanations": {"净力": "正确：净力指几个力合成后剩下的力。", "尽力": "jìn 与 jìng 韵尾不同（n 与 ng），意思是尽力。", "劲力": "jìn 与 jìng 韵尾不同（n 与 ng），意思是力量。", "近利": "jìn 与 jìng 韵尾不同（n 与 ng），意思是眼前的利益。"}, "sentence_index": null, "correct_answer": "净力"}, "level_3": {"options": [{"text": "净力", "is_correct": true, "explanation": "正确：净力越大，物体加速越快，符合力学规律。"}, {"text": "摩擦力", "is_correct": false, "explanation": "语义：摩擦力越大，物体越难加速，与“加速越快”相矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不说大小，不能说颜色越大。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离与加速无关，句中“物体加速越快”的因果说不通。"}], "explanations": {"净力": "正确：净力越大，物体加速越快，符合力学规律。", "摩擦力": "语义：摩擦力越大，物体越难加速，与“加速越快”相矛盾。", "颜色": "搭配：颜色不说大小，不能说颜色越大。", "距离": "语义：距离与加速无关，句中“物体加速越快”的因果说不通。"}, "sentence_index": 6, "correct_answer": "净力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱子的净力很大，搬起来很费劲。", "explanation": "这里应该用〈重量〉。净力是几个力合成后的结果，不指物体本身的轻重；说箱子轻重要用〈重量〉。"}, {"text": "这节课的净力很长，同学们都累了。", "explanation": "用法错误：净力是力的概念，不能用来说时间长短；说课的时长应说〈时长〉。"}, {"text": "这道菜的净力很香。", "explanation": "用法错误：净力是物理概念，不用于描述食物；说食物的味道应说〈味道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车受到的净力大得很快，所以越开越快。", "corrected_sentence": "这辆车受到的净力很大，所以越开越快。", "error_description": "错误：“大得很快”。正确：“很大”。净力的大小用“很大”，“大得”后的补语要描述大的程度，不能接“很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个气球受到的净力向下，所以它飞上天了。", "corrected_sentence": "这个气球受到的净力向上，所以它飞上天了。", "error_description": "错误：“净力向下”。正确：“净力向上”。物体朝净力的方向加速，气球飞上天，说明净力向上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
