INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "液体和气体的统称，没有固定形状，容易流动。", "primary_collocate": null, "pronunciation": "liú tǐ", "ipa": "ljou˧˥ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "流体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水和空气都是流体。", "target_word": "流体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "流体可以流动，也没有固定的形状。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "液体和气体合起来叫流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气是一种看不见的流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机在流体里飞行，会受到力的影响。", "target_word": "流体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流体流得越快，压力就越小。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学物理时，我们先学流体的特点。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜是流动得很慢的流体。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管子里的流体从左边流到右边。", "target_word": "流体", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "流體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "流体：液体和气体的统称，没有固定形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固体", "is_correct": false, "explanation": "语义：固体没有流动性，伯努利定理只适用于流动的流体，“固体速度”无法与静压联系。"}, {"text": "流体", "is_correct": true, "explanation": "正确。伯努利定理描述的是液体和气体的流动，流体速度与静压的关系只对流体成立。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与流速无关，“温度速度”说不通，也无法与静压建立伯努利式的联系。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“静压”是流体内部压力的概念，电流不与之搭配，电流的大小说“强度”。"}], "explanations": {"固体": "语义：固体没有流动性，伯努利定理只适用于流动的流体，“固体速度”无法与静压联系。", "流体": "正确。伯努利定理描述的是液体和气体的流动，流体速度与静压的关系只对流体成立。", "温度": "语义：温度与流速无关，“温度速度”说不通，也无法与静压建立伯努利式的联系。", "电流": "搭配：“静压”是流体内部压力的概念，电流不与之搭配，电流的大小说“强度”。"}, "sentence_index": 0, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天要喝够两升流体。", "explanation": "这里应该用〈液体〉。流体指液体和气体的统称，说“喝”的时候只用〈液体〉或〈水〉。"}, {"text": "这张桌子是用流体做的，可以放很多书。", "explanation": "这里应该用〈木头〉。流体能流动、没有固定形状，做桌子的材料要用〈木头〉这类固体。"}, {"text": "妈妈在厨房里把流体切成了小块。", "explanation": "这里应该用〈豆腐〉。流体没有固定形状，不能切成小块；能切的食材要用〈豆腐〉这类固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头是固体，不会流动，“石头流得越快”说不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是固态金属，不能说“流得越快”，与压力的变化也无关。"}, {"text": "光线", "is_correct": false, "explanation": "搭配：光线说“传播”，不说“流得越快”，与“压力就越小”也不搭配。"}, {"text": "流体", "is_correct": true, "explanation": "正确。流体能够流动，流速越快，静压越小，这正是伯努利原理的内容。"}], "explanations": {"石头": "语义：石头是固体，不会流动，“石头流得越快”说不通。", "钢铁": "语义：钢铁是固态金属，不能说“流得越快”，与压力的变化也无关。", "光线": "搭配：光线说“传播”，不说“流得越快”，与“压力就越小”也不搭配。", "流体": "正确。流体能够流动，流速越快，静压越小，这正是伯努利原理的内容。"}, "sentence_index": 6, "correct_answer": "流体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种流体很硬，能做成锋利的刀。", "explanation": "这里应该用〈金属〉。流体能流动、没有固定形状，不能说“很硬”，也做不成有固定形状的刀，这类材料要用〈金属〉。"}, {"text": "他用剪刀把流体剪成了两段。", "explanation": "这里应该用〈绳子〉。流体没有固定形状，不能用剪刀剪断；能剪断的东西要用〈绳子〉这类有形的材料。"}, {"text": "我用手能抓起流体，堆成一座小沙堆。", "explanation": "这里应该用〈沙子〉。流体会流动，抓不起来，能堆成沙堆的颗粒要用〈沙子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个锅里的糖浆是一种流动得很慢流体。", "corrected_sentence": "那个锅里的糖浆是一种流动得很慢的流体。", "error_description": "错误：“流动得很慢”修饰“流体”时，中间要加结构助词“的”，应说“流动得很慢的流体”。漏掉“的”，定语与中心词之间没有连接，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验室的架子上放着几种流体们，都能流动。", "corrected_sentence": "实验室的架子上放着几种流体，都能流动。", "error_description": "错误：“几种”已经表示数量，“流体”是物质名词，后面不能再加“们”，应说“几种流体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指事物发展确定不移，不可避免。", "primary_collocate": null, "pronunciation": "bì rán", "ipa": "pi˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "必然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "努力学习，必然会有好成绩。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气越来越冷，树叶必然会掉下来。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不吃早饭，上午必然会觉得饿。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展必然带来环境问题。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直不锻炼，身体必然会变差。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人越多，声音必然越大。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车越来越多，路上必然会堵车。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天熬夜，第二天必然没有精神。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天过后，夏天必然会来。", "target_word": "必然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "必然性", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物发展确定不移，一定会出现某种结果，无法避免", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43abfa4c-343c-4bb7-89da-1317173c8205') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必然", "is_correct": true, "explanation": "「必然」表示事物发展确定不移，符合伯努利定理的结论。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：「偶然」指偶尔发生，与定理所说的必然关系相矛盾。"}, {"text": "或许", "is_correct": false, "explanation": "语义：「或许」表示不确定，与「经典物理解释」的确定结论矛盾。"}, {"text": "断然", "is_correct": false, "explanation": "搭配：「断然」多用于拒绝、否定等决断语境，不修饰「伴随」这类客观关系。"}], "explanations": {"必然": "「必然」表示事物发展确定不移，符合伯努利定理的结论。", "偶然": "语义：「偶然」指偶尔发生，与定理所说的必然关系相矛盾。", "或许": "语义：「或许」表示不确定，与「经典物理解释」的确定结论矛盾。", "断然": "搭配：「断然」多用于拒绝、否定等决断语境，不修饰「伴随」这类客观关系。"}, "sentence_index": 0, "correct_answer": "必然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你必然早点回家，不要在外面玩。", "explanation": "这里应该用〈必须〉。「必然」说客观规律的必定，不表示对人的要求或命令。"}, {"text": "我希望你必然通过这次考试。", "explanation": "这里应该用〈一定〉。「必然」说不以人的意志为转移的结果，不能用来表达愿望。"}, {"text": "我们在街上必然遇见了老同学。", "explanation": "这里应该用〈偶然〉。「必然」指必定会发生，偶然相遇是意外，不能说「必然遇见」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必然", "is_correct": true, "explanation": "「必然」表示必定如此，符合「人越多，声音越大」的规律。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「越……越」所说的规律性相矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：「猛然」表示突然发生，不用于「越……越」这类渐变句式。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：「顺便」表示附带做事，不能修饰「声音越大」的变化。"}], "explanations": {"必然": "「必然」表示必定如此，符合「人越多，声音越大」的规律。", "偶尔": "语义：「偶尔」表示不常发生，与「越……越」所说的规律性相矛盾。", "猛然": "搭配：「猛然」表示突然发生，不用于「越……越」这类渐变句式。", "顺便": "搭配：「顺便」表示附带做事，不能修饰「声音越大」的变化。"}, "sentence_index": 6, "correct_answer": "必然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他明天必然会来，不过我也不太确定。", "explanation": "这里应该用〈可能〉。「必然」表示确定不移，后面又说不确定，前后矛盾；表示有可能要用「可能」。"}, {"text": "我必然喜欢这个颜色。", "explanation": "这里应该用〈肯定〉。「必然」说客观规律的必然，不用于表达个人喜好。"}, {"text": "我们每个星期必然打一次球。", "explanation": "这里应该用〈经常〉。「必然」表示必定发生的结果，不表示次数或习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只要每天练习，你的发音会必然进步。", "corrected_sentence": "只要每天练习，你的发音必然进步。", "error_description": "「会」不能放在副词「必然」之前，应写作「发音必然进步」（或「必然会进步」，此时「会」在「必然」之后），不能写成「会必然进步」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不遵守交通规则，事故很必然会发生。", "corrected_sentence": "不遵守交通规则，事故必然会发生。", "error_description": "副词「必然」不能受「很」修饰，应去掉「很」，写作「事故必然会发生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97d58267-1513-4a3e-9782-24bb578dbf2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "流体垂直作用于表面的压力，是流体本身的压力，不包括因流动而产生的动压。", "primary_collocate": null, "pronunciation": "jìng yā", "ipa": "tɕiŋ˥˩ ja˥˥", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "静压", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "管道里水的静压是用压力表测出来的。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流体静止时，静压等于单位面积上受的力。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水越深，底部的静压越大。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "静压和动压加起来叫总压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师在管壁上测量流体的静压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流得快，静压就会变小。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根水管的静压是两个大气压。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "静压的大小和水的深度有关。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机机翼上方的静压比下方低。", "target_word": "静压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "静压力", "label": "复合"}], "register": "书面", "sense_fingerprint": "流体垂直作用于表面的压力（区别于动压、总压的物理术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "静压", "is_correct": true, "explanation": "正确：静压指流体静止时单位面积上的垂直压力。"}, {"text": "静雅", "is_correct": false, "explanation": "jìng yǎ（第三声）与 jìng yā（第一声）末字声调不同，意思是安静文雅。"}, {"text": "惊讶", "is_correct": false, "explanation": "jīng yà 与 jìng yā 两字声调都不同，意思是对意外的事感到吃惊。"}, {"text": "精雅", "is_correct": false, "explanation": "jīng yǎ 与 jìng yā 两字声调都不同，意思是精致优雅。"}], "explanations": {"静压": "正确：静压指流体静止时单位面积上的垂直压力。", "静雅": "jìng yǎ（第三声）与 jìng yā（第一声）末字声调不同，意思是安静文雅。", "惊讶": "jīng yà 与 jìng yā 两字声调都不同，意思是对意外的事感到吃惊。", "精雅": "jīng yǎ 与 jìng yā 两字声调都不同，意思是精致优雅。"}, "sentence_index": null, "correct_answer": "静压"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与流体的速度和压力无关，无法解释升力。"}, {"text": "静压", "is_correct": true, "explanation": "正确：静压是流体的压力，速度增加时随之减小，符合伯努利定理。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”是人，不是流体的物理量，不能“减小”。"}, {"text": "屁股", "is_correct": false, "explanation": "语域：“屁股”是口语，与书面的物理说明不协调，也不指流体的量。"}], "explanations": {"颜色": "语义：“颜色”与流体的速度和压力无关，无法解释升力。", "静压": "正确：静压是流体的压力，速度增加时随之减小，符合伯努利定理。", "老师": "语义：“老师”是人，不是流体的物理量，不能“减小”。", "屁股": "语域：“屁股”是口语，与书面的物理说明不协调，也不指流体的量。"}, "sentence_index": 0, "correct_answer": "静压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这阵大风的静压很猛。", "explanation": "这里应该用〈动压〉。风吹来的冲击力来自空气的流动，属于动压；静压是流体本身垂直作用于表面的压力，不用“猛”来形容。"}, {"text": "他心里感到很大的静压。", "explanation": "这里应该用〈压力〉。静压是流体物理学上的压力，不能用来指人的心理压力。"}, {"text": "这根管子里的水的静压很烫。", "explanation": "这里应该用〈温度〉。静压是流体静止时的压力，不能用来说冷热；水的冷热要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白天", "is_correct": false, "explanation": "语义：白天与空气流速无关，句意不通。"}, {"text": "静压", "is_correct": true, "explanation": "正确：空气流得快，流体的静压就会减小。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不是流体的物理量，空气流得快不会使树木“变小”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与书面的物理叙述不符，也不指压力。"}], "explanations": {"白天": "语义：白天与空气流速无关，句意不通。", "静压": "正确：空气流得快，流体的静压就会减小。", "树木": "语义：树木不是流体的物理量，空气流得快不会使树木“变小”。", "玩意儿": "语域：“玩意儿”是口语，与书面的物理叙述不符，也不指压力。"}, "sentence_index": 6, "correct_answer": "静压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个螺丝钉的静压很大。", "explanation": "这里应该用〈压强〉。静压只指流体静止时的压力，固体螺丝钉受到的压力用压强。"}, {"text": "这块石头的静压很大。", "explanation": "这里应该用〈重量〉。静压是流体的压力，石头是固体，不能用静压说它的分量。"}, {"text": "这辆车的静压很快。", "explanation": "这里应该用〈速度〉。静压是压力，不能用来描述快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师测出了一根静压值。", "corrected_sentence": "工程师测出了一个静压值。", "error_description": "量词错误：“静压值”是一个数值，应用“个”；“根”指条状的东西，不能修饰静压值。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管子里的静压降起来了。", "corrected_sentence": "管子里的静压降下来了。", "error_description": "补语错误：压力下降应说“降下来”；“起来”表示向上，不能与“降”搭配，应改为“降下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保留", "is_correct": false, "explanation": "与“减小”不是反义关系，指保存下来，不改变数量。"}, {"text": "增大", "is_correct": true, "explanation": "正确：“增大”与“减小”反义，指数量或程度由小变大。"}, {"text": "锁定", "is_correct": false, "explanation": "与“减小”不是反义关系，指固定住，不表示数量变化。"}, {"text": "检查", "is_correct": false, "explanation": "与“减小”不是反义关系，指查看是否正确。"}], "correct_answer": "增大", "explanations": {"保留": "与“减小”不是反义关系，指保存下来，不改变数量。", "增大": "正确：“增大”与“减小”反义，指数量或程度由小变大。", "锁定": "与“减小”不是反义关系，指固定住，不表示数量变化。", "检查": "与“减小”不是反义关系，指查看是否正确。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安装", "is_correct": false, "explanation": "与“减小”不是反义关系，指把设备装好。"}, {"text": "增大", "is_correct": true, "explanation": "正确：“增大”与“减小”反义，指数量或程度由小变大。"}, {"text": "清洗", "is_correct": false, "explanation": "与“减小”不是反义关系，指把东西弄干净。"}, {"text": "翻译", "is_correct": false, "explanation": "与“减小”不是反义关系，指把一种语言转换成另一种。"}], "correct_answer": "增大", "explanations": {"安装": "与“减小”不是反义关系，指把设备装好。", "增大": "正确：“增大”与“减小”反义，指数量或程度由小变大。", "清洗": "与“减小”不是反义关系，指把东西弄干净。", "翻译": "与“减小”不是反义关系，指把一种语言转换成另一种。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（数量、程度等）由大变小，或使其由大变小。", "primary_collocate": null, "pronunciation": "jiǎn xiǎo", "ipa": "tɕjɛn˨˩˦ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "减小", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "光滑的路面能减小轮胎的摩擦。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想办法减小实验的误差。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的形状可以减小空气阻力。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把角度减小一点，图就好看了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个城市的差距在慢慢减小。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种包装减小了盒子的体积。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车速减小以后，刹车距离也短了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电视的音量减小一点。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力减小时，气球会慢慢变大。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减小了", "label": "体标"}, {"form": "减小过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使数量、程度（如速度、误差、阻力）由大变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固定", "is_correct": false, "explanation": "语义：“固定”表示不变，与前句“速度增加伴随的变化”矛盾。"}, {"text": "减小", "is_correct": true, "explanation": "正确：速度增加时，静压随之减小，“减小”表示数量从大变小。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”是动作，不表示数量变小，句意不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“静压”是物理量，不能“呼吸”，搭配不当。"}], "explanations": {"固定": "语义：“固定”表示不变，与前句“速度增加伴随的变化”矛盾。", "减小": "正确：速度增加时，静压随之减小，“减小”表示数量从大变小。", "测量": "语义：“测量”是动作，不表示数量变小，句意不通。", "呼吸": "搭配：“静压”是物理量，不能“呼吸”，搭配不当。"}, "sentence_index": 0, "correct_answer": "减小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一起减小了这道数学题。", "explanation": "这里应该用〈解〉。“减小”表示数量或程度变小，不能用于解题；解题要用〈解〉。"}, {"text": "他的思想减小了很多。", "explanation": "这里应该用〈转变〉。减小指东西变小或数量、程度变少，思想不能这样计量；思想的变化要说“转变”。"}, {"text": "他把椅子往后减小了一点。", "explanation": "这里应该用〈挪〉。移动位置用“挪”，“减小”不能说椅子向后减小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是作品、风景，不能带“体积”作宾语。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：包装可以装饰盒子，但不能“装饰”体积，句意不通。"}, {"text": "减小", "is_correct": true, "explanation": "正确：这种包装使盒子的体积变小，“减小”表示体积从大变小。"}, {"text": "搞定", "is_correct": false, "explanation": "语域：“搞定”是口语，与书面的说明语境不符，也不表示体积变小。"}], "explanations": {"欣赏": "搭配：“欣赏”的对象是作品、风景，不能带“体积”作宾语。", "装饰": "语义：包装可以装饰盒子，但不能“装饰”体积，句意不通。", "减小": "正确：这种包装使盒子的体积变小，“减小”表示体积从大变小。", "搞定": "语域：“搞定”是口语，与书面的说明语境不符，也不表示体积变小。"}, "sentence_index": 6, "correct_answer": "减小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十减小三等于七。", "explanation": "这里应该用〈减〉。算术中的减去用“减”；“减小”表示数量变小，不用于计算。"}, {"text": "工资里减小了五百元社保。", "explanation": "这里应该用〈扣除〉。从工资里去掉款项用“扣除”；“减小”指数量或程度变小。"}, {"text": "他的年龄减小了三岁。", "explanation": "这里应该用〈增长〉。年龄只会增加，不能说“减小”；年龄的变化要说“增长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新的设计把机器的噪音减小着很多。", "corrected_sentence": "新的设计把机器的噪音减小了很多。", "error_description": "体标错误：“减小”后带程度补语“很多”表示已完成的变化，应用“了”，不能用表示持续的“着”，应说“减小了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把音量减小了一个。", "corrected_sentence": "我把音量减小了一点。", "error_description": "量词错误：表示“减小”的程度要用“一点”，“一个”不能用来修饰程度变化，应说“减小了一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
