INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指具有典范性、权威性的著作或事物；也形容事物具有典范性、权威性。", "primary_collocate": null, "pronunciation": "jīng diǎn", "ipa": "tɕiŋ˥˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "根据伯努利定理，流体速度的增加必然伴随着静压的减小，这为升力提供了经典物理解释。", "target_word": "经典", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这本书是中国文学的经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们多读经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "《红楼梦》是一部经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小读过很多古代经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影已经成了经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛顿的书是物理学的经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要读经典，也要读新书。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些经典著作影响了很多人。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经典作品值得读很多遍。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经典著作", "label": "复合"}], "register": "中性", "sense_fingerprint": "具有典范性、权威性的著作或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确答案。经典 jīng diǎn，指具有典范性、权威性的著作或事物。"}, {"text": "景点", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景点。"}, {"text": "清点", "is_correct": false, "explanation": "qīng 与 jīng 声母不同，意思是清查、点数。"}, {"text": "星点", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是星星般的小点。"}], "explanations": {"经典": "正确答案。经典 jīng diǎn，指具有典范性、权威性的著作或事物。", "景点": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景点。", "清点": "qīng 与 jīng 声母不同，意思是清查、点数。", "星点": "xīng 与 jīng 声母不同，意思是星星般的小点。"}, "sentence_index": null, "correct_answer": "经典"}, "level_3": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确。「经典物理解释」指典范、权威的解释，与前文依据伯努利定理的论述相符。"}, {"text": "荒诞", "is_correct": false, "explanation": "语义：「荒诞」与前文「根据伯努利定理……必然」的严谨推导相矛盾，不能说提供了荒诞的解释。"}, {"text": "错误", "is_correct": false, "explanation": "语义：「错误」与伯努利定理所依据的正确原理冲突，不能作为升力解释的答案。"}, {"text": "含糊", "is_correct": false, "explanation": "搭配：「含糊」多修饰说法、措辞，与「必然伴随」的明确推导不搭配。"}], "explanations": {"经典": "正确。「经典物理解释」指典范、权威的解释，与前文依据伯努利定理的论述相符。", "荒诞": "语义：「荒诞」与前文「根据伯努利定理……必然」的严谨推导相矛盾，不能说提供了荒诞的解释。", "错误": "语义：「错误」与伯努利定理所依据的正确原理冲突，不能作为升力解释的答案。", "含糊": "搭配：「含糊」多修饰说法、措辞，与「必然伴随」的明确推导不搭配。"}, "sentence_index": 0, "correct_answer": "经典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只经典。", "explanation": "这里应该用〈部〉。经典指具有典范性的著作，量词用「部」；「只」用于动物等，不能修饰经典。"}, {"text": "这部刚写完的草稿已经是经典了，还没有人读过。", "explanation": "这里误用了〈经典〉。「经典」指经过时间检验、具有权威性的著作，刚写完、还没人读过的作品不能称为经典，应说〈新作〉。"}, {"text": "妈妈用经典炒了一盘菜。", "explanation": "这里应该用〈青菜〉。经典指具有典范性的著作或事物，不能用来炒菜；炒菜的食材要用〈青菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确。「物理学的经典」指物理学中具有典范性的著作，与「牛顿的书」相符。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学体裁，与「物理学」的科学内容不符，不能说「物理学的小说」。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的儿童故事，与「物理学」的科学内容矛盾。"}, {"text": "段子", "is_correct": false, "explanation": "语域：「段子」是口语化的笑话，不适用于描述严谨的科学著作。"}], "explanations": {"经典": "正确。「物理学的经典」指物理学中具有典范性的著作，与「牛顿的书」相符。", "小说": "语义：小说是文学体裁，与「物理学」的科学内容不符，不能说「物理学的小说」。", "童话": "语义：童话是虚构的儿童故事，与「物理学」的科学内容矛盾。", "段子": "语域：「段子」是口语化的笑话，不适用于描述严谨的科学著作。"}, "sentence_index": 6, "correct_answer": "经典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借了三张经典。", "explanation": "这里应该用〈部〉。「张」用于平面物体，不能用于著作；经典指著作时量词用「部」。"}, {"text": "他把经典泡水喝了一杯。", "explanation": "这里应该用〈茶叶〉。经典指典范著作或事物，不能泡水喝；泡水喝的要用〈茶叶〉。"}, {"text": "他的新经典刚刚出版，还没人读过。", "explanation": "这里应该用〈作品〉。经典指经过时间检验的典范著作，刚出版的新书还不能称为经典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套书是一只外国经典。", "corrected_sentence": "这套书是一部外国经典。", "error_description": "量词错误：「经典」指著作时量词应用「部」，「只」只用于动物等。应说「一部外国经典」，不说「一只外国经典」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他推荐了几部的经典作品给我。", "corrected_sentence": "他推荐了几部经典作品给我。", "error_description": "结构错误：数量短语“几部”修饰名词时不加“的”，应说“几部经典作品”，不说“几部的经典作品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示数量或程度不够，达不到需要或要求。", "primary_collocate": null, "pronunciation": "bù zú yǐ", "ipa": "pu˥˩ tsu˧˥ i˨˩˦", "syllable_count": 3, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "不足以", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这点钱不足以买一台电脑。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有一个例子，不足以说明问题。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人的力量不足以完成这个工作。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的经验还不足以带领大家。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水不足以让全村人喝一个月。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一次成功不足以证明方法是对的。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光有热情，不足以做好这件事。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三天的时间不足以看完这么多书。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个理由不足以让人相信。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "足以", "label": "肯定式"}], "register": "书面", "sense_fingerprint": "不足以：数量或程度不够，达不到需要或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不足以", "is_correct": true, "explanation": "正确。「并不足以完全描述」表示伯努利原理解释力不够，与「然而」的转折一致。"}, {"text": "足以", "is_correct": false, "explanation": "语义：去掉「不」后，「并足以」说伯努利原理已经足够，与「然而」引出的转折及后文「需要综合分析」相矛盾。"}, {"text": "能够", "is_correct": false, "explanation": "语义：「并能够完全描述」肯定了伯努利原理的完备性，与「然而」及后文的综合分析矛盾。"}, {"text": "必须", "is_correct": false, "explanation": "搭配：「并必须」不是常见搭配，「必须」表示义务或必要，与「完全描述」的能力判断不搭配。"}], "explanations": {"不足以": "正确。「并不足以完全描述」表示伯努利原理解释力不够，与「然而」的转折一致。", "足以": "语义：去掉「不」后，「并足以」说伯努利原理已经足够，与「然而」引出的转折及后文「需要综合分析」相矛盾。", "能够": "语义：「并能够完全描述」肯定了伯努利原理的完备性，与「然而」及后文的综合分析矛盾。", "必须": "搭配：「并必须」不是常见搭配，「必须」表示义务或必要，与「完全描述」的能力判断不搭配。"}, "sentence_index": 0, "correct_answer": "不足以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间很大，所以不足以住下三个人。", "explanation": "这里应该用〈足以〉。「很大」说明空间够用，表示够用应用「足以」；「不足以」表示不够，与语境矛盾。"}, {"text": "他很有经验，所以不足以带领大家。", "explanation": "这里应该用〈足以〉。「很有经验」说明能力够，应用「足以」，不能用「不足以」。"}, {"text": "他很聪明，所以不足以解决这道题。", "explanation": "这里应该用〈足以〉。「很聪明」说明能力够，应用「足以」表示能力足够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不足以", "is_correct": true, "explanation": "正确。「一次成功不足以证明方法是对的」表示一次成功的证据力不够。"}, {"text": "不由得", "is_correct": false, "explanation": "搭配：「不由得」表示人不自觉地做某事，主语「一次成功」不是人，句子不通。"}, {"text": "不得不", "is_correct": false, "explanation": "搭配：「不得不」表示被迫，主语应是人，「一次成功不得不证明」说不通。"}, {"text": "不肯", "is_correct": false, "explanation": "搭配：「不肯」的主语应是有意愿的人，用于「一次成功」不通顺。"}], "explanations": {"不足以": "正确。「一次成功不足以证明方法是对的」表示一次成功的证据力不够。", "不由得": "搭配：「不由得」表示人不自觉地做某事，主语「一次成功」不是人，句子不通。", "不得不": "搭配：「不得不」表示被迫，主语应是人，「一次成功不得不证明」说不通。", "不肯": "搭配：「不肯」的主语应是有意愿的人，用于「一次成功」不通顺。"}, "sentence_index": 6, "correct_answer": "不足以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些证据很充分，所以不足以证明他有罪。", "explanation": "这里应该用〈足以〉。「很充分」说明证据够用，应用「足以」，用「不足以」与语境矛盾。"}, {"text": "他准备得非常充分，所以不足以通过考试。", "explanation": "这里应该用〈足以〉。「准备得非常充分」说明条件够，应用「足以」，用「不足以」与语境矛盾。"}, {"text": "他的薪水很高，所以不足以让他买房。", "explanation": "这里应该用〈足以〉。「很高」说明收入够用，应用「足以」表示足够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点钱没足以请大家吃饭。", "corrected_sentence": "这点钱不足以请大家吃饭。", "error_description": "否定词错误：「足以」前的否定词应是「不」，说「不足以」，不说「没足以」；「没」不能与「足以」搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱不足以支付了房租。", "corrected_sentence": "这笔钱不足以支付房租。", "error_description": "「不足以」表示能力或条件不够，后面的动词不能再带「了」表示完成，应说「不足以支付房租」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
