INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12166, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "定律是经过检验和证明的，反映事物之间必然联系的普遍规律。", "primary_collocate": null, "pronunciation": "dìng lǜ", "ipa": "tiŋ˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "定律", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每一次平稳起降，都是对物理定律严谨遵循的结果，也彰显了工程智慧在复杂系统中实现可控性的卓越能力。", "target_word": "定律", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "牛顿发现了万有引力定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条定律是科学家多年研究的结果。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个学生都要记住这条物理定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能量守恒定律告诉我们，能量不会消失。", "target_word": "定律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多实验都证明了这个定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "定律不是人写出来的规定，而是自然的规律。", "target_word": "定律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写下了三条定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "物体的运动要遵守这些定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "书面", "sense_fingerprint": "定律：经检验证明、反映事物必然联系的普遍规律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公式", "is_correct": false, "explanation": "语义：牛顿第三定律说的是一条自然规律，不是数学式子，“牛顿第三公式”与之不符。"}, {"text": "定律", "is_correct": true, "explanation": "正确。牛顿第三定律是牛顿提出的一条普遍规律，“定律”是这里唯一符合的词。"}, {"text": "物理", "is_correct": false, "explanation": "搭配：“第三”要修饰可数的规律或条款，“物理”是学科名，不能用“第三”来计数。"}, {"text": "定义", "is_correct": false, "explanation": "语义：定义是对概念的界定，不是可以被实验检验的规律，“牛顿第三定义”说不通。"}], "explanations": {"公式": "语义：牛顿第三定律说的是一条自然规律，不是数学式子，“牛顿第三公式”与之不符。", "定律": "正确。牛顿第三定律是牛顿提出的一条普遍规律，“定律”是这里唯一符合的词。", "物理": "搭配：“第三”要修饰可数的规律或条款，“物理”是学科名，不能用“第三”来计数。", "定义": "语义：定义是对概念的界定，不是可以被实验检验的规律，“牛顿第三定义”说不通。"}, "sentence_index": 0, "correct_answer": "定律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下棋时大家都要遵守定律。", "explanation": "这里应该用〈规则〉。定律指经过检验、反映事物必然联系的自然规律，下棋的约定要用〈规则〉。"}, {"text": "我们明天的定律是去爬山。", "explanation": "这里应该用〈计划〉。定律指经过检验的自然规律，打算要做的事要用〈计划〉。"}, {"text": "学生要遵守学校的定律。", "explanation": "这里应该用〈规定〉。学校对学生的要求是人定的规定，不是自然规律，不用「定律」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是实物，实验证明的是规律或论断，“证明了这张桌子”说不通。"}, {"text": "定律", "is_correct": true, "explanation": "正确。“证明”的对象是定律这样的规律，符合上下文。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不是可以被实验证明的对象，句子说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“证明”的对象是论断或理论，颜色不能被证明，应与“证明”搭配的是“理论”“结论”。"}], "explanations": {"桌子": "语义：桌子是实物，实验证明的是规律或论断，“证明了这张桌子”说不通。", "定律": "正确。“证明”的对象是定律这样的规律，符合上下文。", "作者": "语义：作者是人，不是可以被实验证明的对象，句子说不通。", "颜色": "搭配：“证明”的对象是论断或理论，颜色不能被证明，应与“证明”搭配的是“理论”“结论”。"}, "sentence_index": 6, "correct_answer": "定律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们国家的定律规定，未成年人不能喝酒。", "explanation": "这里应该用〈法律〉。定律指自然界的规律，国家制定的强制性规定要用〈法律〉。"}, {"text": "数学课上，老师讲了勾股定律的证明方法。", "explanation": "这里应该用〈定理〉。数学中由公理推出的结论叫定理，勾股定理不能说成“勾股定律”，定律指自然规律。"}, {"text": "这只是个定律，还没有人能证明它。", "explanation": "这里应该用〈假说〉。定律是经过检验和证明的规律，还没被证明的想法要用〈假说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些规律都是经过检验定律。", "corrected_sentence": "这些规律都是经过检验的定律。", "error_description": "错误：“经过检验”修饰“定律”时，中间要加结构助词“的”，应说“经过检验的定律”。漏掉“的”，定语与中心词之间没有连接，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物理课上我们学了几条定律们，都很重要。", "corrected_sentence": "物理课上我们学了几条定律，都很重要。", "error_description": "错误：「几条」已经表示数量，且「们」只用于指人，不能加在「定律」后面，应说「几条定律」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
