INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "攻角是指飞行器机翼弦线与来流方向之间的夹角，它影响升力和阻力的大小。", "primary_collocate": null, "pronunciation": "gōng jiǎo", "ipa": "kʊŋ˥ tɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "攻角", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "飞机抬头时，攻角会变大。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "攻角太大，机翼就会失去升力。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测量机翼的攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员要注意攻角的变化。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "攻角越大，空气的阻力也越大。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机的攻角是十度。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风洞实验可以测出不同的攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，飞行员会调整攻角。", "target_word": "攻角", "complexity_tier": "T3", "furigana": "gōng jiǎo", "sentence_source": "generated"}, {"text": "他把攻角调小了一点。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "专业", "sense_fingerprint": "机翼弦线与来流方向的夹角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻角", "is_correct": true, "explanation": "“机翼通过攻角向下偏转气流”符合攻角的含义：机翼与来流的夹角可以偏转气流。"}, {"text": "升力", "is_correct": false, "explanation": "语义：升力是作用力，不能作为偏转气流的途径。"}, {"text": "阻力", "is_correct": false, "explanation": "语义：阻力是阻碍运动的力，不能用来偏转气流。"}, {"text": "气流", "is_correct": false, "explanation": "语义：气流本身就是被偏转的对象，放在“通过”之后语义重复且不通。"}], "explanations": {"攻角": "“机翼通过攻角向下偏转气流”符合攻角的含义：机翼与来流的夹角可以偏转气流。", "升力": "语义：升力是作用力，不能作为偏转气流的途径。", "阻力": "语义：阻力是阻碍运动的力，不能用来偏转气流。", "气流": "语义：气流本身就是被偏转的对象，放在“通过”之后语义重复且不通。"}, "sentence_index": 0, "correct_answer": "攻角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段山路的攻角很大。", "explanation": "这里应该用〈坡度〉。攻角专指机翼或飞行物与气流的夹角，山路的倾斜程度应用坡度。"}, {"text": "光线的攻角是三十度。", "explanation": "这里应该用〈入射角〉。攻角只用于飞行器与气流之间，光线的入射角应用入射角。"}, {"text": "他抬头看飞机，攻角很大。", "explanation": "这里应该用〈仰角〉。攻角指飞行器与气流的夹角，观察者抬头看物体的角度应用仰角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攻角", "is_correct": true, "explanation": "“这架飞机的攻角是十度”表示机翼与气流的夹角为十度，与“度”的计量相符。"}, {"text": "高度", "is_correct": false, "explanation": "语义：高度是距离地面的长度，不以“度”计量，与“十度”不符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度的单位是公里或米每秒，不能用“度”计量。"}, {"text": "油量", "is_correct": false, "explanation": "搭配：油量不用“度”来计量，“油量是十度”搭配不当。"}], "explanations": {"攻角": "“这架飞机的攻角是十度”表示机翼与气流的夹角为十度，与“度”的计量相符。", "高度": "语义：高度是距离地面的长度，不以“度”计量，与“十度”不符。", "速度": "语义：速度的单位是公里或米每秒，不能用“度”计量。", "油量": "搭配：油量不用“度”来计量，“油量是十度”搭配不当。"}, "sentence_index": 6, "correct_answer": "攻角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把收音机的攻角调小了一点。", "explanation": "这里应该用〈音量〉。攻角是机翼与气流的夹角，收音机的声音大小应用音量。"}, {"text": "他在辩论中把攻角调小了一点。", "explanation": "这里应该用〈语气〉。攻角是机翼与气流的夹角，比喻辩论中的态度应用语气，不能用攻角。"}, {"text": "他站在攻角上看风景。", "explanation": "这里应该用〈阳台〉。攻角是角度，不是可以站立的场所，站在阳台上看风景应用阳台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两只攻角不一样。", "corrected_sentence": "这两个攻角不一样。", "error_description": "攻角的量词是“个”，不用“只”（“只”多用于动物或成对物品中的一个）。应说“这两个攻角”，不能说“这两只攻角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞行员把攻角大调了一些。", "corrected_sentence": "飞行员把攻角调大了一些。", "error_description": "结果补语“大”应放在“调”之后，正确说法是“调大”，不能说“大调”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "向上", "is_correct": true, "explanation": "向上与向下是反义词，表示从低处朝高处的方向。"}, {"text": "慢慢", "is_correct": false, "explanation": "慢慢表示速度缓慢，与方向无关，不是向下的反义词。"}, {"text": "突然", "is_correct": false, "explanation": "突然表示出乎意料地发生，与方向无关，不构成反义。"}, {"text": "立刻", "is_correct": false, "explanation": "立刻表示马上，说的是时间，与向下的方向没有反义关系。"}], "correct_answer": "向上", "explanations": {"向上": "向上与向下是反义词，表示从低处朝高处的方向。", "慢慢": "慢慢表示速度缓慢，与方向无关，不是向下的反义词。", "突然": "突然表示出乎意料地发生，与方向无关，不构成反义。", "立刻": "立刻表示马上，说的是时间，与向下的方向没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "向上", "is_correct": true, "explanation": "向上与向下是反义词，表示从低处朝高处的方向。"}, {"text": "不断", "is_correct": false, "explanation": "不断表示持续、接连不停，与方向无关，不是向下的反义词。"}, {"text": "缓缓", "is_correct": false, "explanation": "缓缓形容动作慢，与方向无关，不构成反义。"}, {"text": "立即", "is_correct": false, "explanation": "立即表示马上，说的是时间，与向下没有反义关系。"}], "correct_answer": "向上", "explanations": {"向上": "向上与向下是反义词，表示从低处朝高处的方向。", "不断": "不断表示持续、接连不停，与方向无关，不是向下的反义词。", "缓缓": "缓缓形容动作慢，与方向无关，不构成反义。", "立即": "立即表示马上，说的是时间，与向下没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "action", "definition": "表示从高处向低处的方向或动作。", "primary_collocate": null, "pronunciation": "xiàng xià", "ipa": "ɕjɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "向下", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请向下看，地上有一只猫。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从山上向下流。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向下走了几步。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯向下运行，到了一楼。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向下望着，心里有点怕。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水顺着屋顶向下流。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把手向下压一压。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球向下滚了很远。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿向下飞，落在树枝上。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动作朝着低处的方向进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向下", "is_correct": true, "explanation": "xiàng xià 意思是从高处向低处的方向。"}, {"text": "乡下", "is_correct": false, "explanation": "xiāng xià（第一声）与 xiàng xià（第四声）声调不同，意思是乡村。"}, {"text": "线下", "is_correct": false, "explanation": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是线下、不在网络上。"}, {"text": "现下", "is_correct": false, "explanation": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是现在。"}], "explanations": {"向下": "xiàng xià 意思是从高处向低处的方向。", "乡下": "xiāng xià（第一声）与 xiàng xià（第四声）声调不同，意思是乡村。", "线下": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是线下、不在网络上。", "现下": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是现在。"}, "sentence_index": null, "correct_answer": "向下"}, "level_3": {"options": [{"text": "向下", "is_correct": true, "explanation": "“向下”表示攻角朝低处偏转气流，与句意一致。"}, {"text": "向上", "is_correct": false, "explanation": "语义：气流向上偏转，反作用力就向下，与后文“推动机翼上升”“产生升力”矛盾。"}, {"text": "向前", "is_correct": false, "explanation": "搭配：气流向前偏转时，反作用力是水平的，无法说明产生升力所需的垂直方向。"}, {"text": "向后", "is_correct": false, "explanation": "语义：气流向后偏转后反作用力向前，推不动机翼上升，与“产生升力”矛盾。"}], "explanations": {"向下": "“向下”表示攻角朝低处偏转气流，与句意一致。", "向上": "语义：气流向上偏转，反作用力就向下，与后文“推动机翼上升”“产生升力”矛盾。", "向前": "搭配：气流向前偏转时，反作用力是水平的，无法说明产生升力所需的垂直方向。", "向后": "语义：气流向后偏转后反作用力向前，推不动机翼上升，与“产生升力”矛盾。"}, "sentence_index": 0, "correct_answer": "向下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向下了三天的雨。", "explanation": "这里应该用〈下〉。向下表示动作朝低处的方向，不能当动词表示下雨。"}, {"text": "这次考试他的成绩向下了。", "explanation": "这里应该用〈下降〉。向下只表示动作朝低处进行，后面要接动作，不能单独表示成绩变差。"}, {"text": "我们向下讨论这个问题吧。", "explanation": "这里应该用〈往下〉，表示接着说下去。向下只表示朝低处的空间方向，不能用来表示接着讨论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向下", "is_correct": true, "explanation": "雨水顺着屋顶的斜面流，方向是向下，与“顺着屋顶”一致。"}, {"text": "往上", "is_correct": false, "explanation": "语义：雨水顺着屋顶的斜面只能往低处流，往上与“顺着屋顶”矛盾。"}, {"text": "朝上", "is_correct": false, "explanation": "语义：朝上的流动与屋顶斜面的走向相反，句子描述的是下流。"}, {"text": "倒着", "is_correct": false, "explanation": "搭配：“倒着流”说的是方向颠倒，与“顺着屋顶”搭配不当。"}], "explanations": {"向下": "雨水顺着屋顶的斜面流，方向是向下，与“顺着屋顶”一致。", "往上": "语义：雨水顺着屋顶的斜面只能往低处流，往上与“顺着屋顶”矛盾。", "朝上": "语义：朝上的流动与屋顶斜面的走向相反，句子描述的是下流。", "倒着": "搭配：“倒着流”说的是方向颠倒，与“顺着屋顶”搭配不当。"}, "sentence_index": 6, "correct_answer": "向下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向下了公共汽车。", "explanation": "这里应该用〈下〉。向下表示动作方向，不能带“公共汽车”作宾语表示下车。"}, {"text": "他向下买了一套房子。", "explanation": "这里应该用〈买下〉。向下只表示朝低处的方向或动作，不能修饰买房。"}, {"text": "天气越来越向下了。", "explanation": "这里应该用〈冷〉等形容词。向下表示空间上朝低处的动作方向，不能描述天气变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸟向下着飞了一段距离。", "corrected_sentence": "小鸟向下飞了一段距离。", "error_description": "错误：“向下着飞”；正确：“向下飞”。“向下”之后不能直接加“着”，应说“向下飞了一段距离”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的眼泪顺着脸颊向下着流。", "corrected_sentence": "他的眼泪顺着脸颊向下流。", "error_description": "错误：“向下着流”；正确：“向下流”。“向下”是表示方向的状语，后面不能加“着”，应直接接动词“流”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体或身体改变方向，朝向另一边。", "primary_collocate": null, "pronunciation": "piān zhuǎn", "ipa": "pʰjɛn˥ ʈʂwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "偏转", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "风一吹，小船慢慢偏转了方向。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁场让电子的路线向右偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线从空气进入水里，方向会偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车突然向左偏转，差点撞到树。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星的天线慢慢偏转，对准了信号源。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机遇到侧风，机头向北偏转了五度。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子弹碰到石头，飞行方向偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风靠近海岸时，路线突然偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "指针受磁铁影响，向一边偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏转了", "label": "体标"}, {"form": "偏轉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物体或身体改变原来的方向，转向另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏转", "is_correct": true, "explanation": "“偏转”指通过攻角让气流改变方向，与句意一致。"}, {"text": "偏离", "is_correct": false, "explanation": "语义：“偏离”指自己离开某条路线（如偏离航线），不能表示让气流改变方向。"}, {"text": "吹动", "is_correct": false, "explanation": "语义：吹动是空气自己流动的动作，机翼不能用攻角来“吹”气流。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却是降低温度，机翼的攻角不能用来冷却气流，句意不通。"}], "explanations": {"偏转": "“偏转”指通过攻角让气流改变方向，与句意一致。", "偏离": "语义：“偏离”指自己离开某条路线（如偏离航线），不能表示让气流改变方向。", "吹动": "语义：吹动是空气自己流动的动作，机翼不能用攻角来“吹”气流。", "冷却": "语义：冷却是降低温度，机翼的攻角不能用来冷却气流，句意不通。"}, "sentence_index": 0, "correct_answer": "偏转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的车轮偏转了一圈。", "explanation": "这里应该用〈转动〉。偏转指方向改变，不指物体绕轴转一圈。"}, {"text": "他偏转了事实，想让大家相信他的说法。", "explanation": "这里应该用〈歪曲〉。偏转指物体方向的改变，不能用来说改变事实的内容。"}, {"text": "他把话题偏转开了，不愿意谈这件事。", "explanation": "这里应该用〈转移〉。偏转指物体方向的改变，不指把话题岔到别处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏转", "is_correct": true, "explanation": "“偏转”指飞机在侧风中机头改变方向，与“了五度”的幅度一致。"}, {"text": "颠倒", "is_correct": false, "explanation": "语义：颠倒是整个翻转过来，与机头小幅度改变方向的意思不符。"}, {"text": "摇摆", "is_correct": false, "explanation": "语义：摇摆是来回晃动，与“向北”的单向转向不符。"}, {"text": "反转", "is_correct": false, "explanation": "搭配：反转要说“反转过来”或“反转到某方向”，不能直接用于“机头向北……了五度”。"}], "explanations": {"偏转": "“偏转”指飞机在侧风中机头改变方向，与“了五度”的幅度一致。", "颠倒": "语义：颠倒是整个翻转过来，与机头小幅度改变方向的意思不符。", "摇摆": "语义：摇摆是来回晃动，与“向北”的单向转向不符。", "反转": "搭配：反转要说“反转过来”或“反转到某方向”，不能直接用于“机头向北……了五度”。"}, "sentence_index": 6, "correct_answer": "偏转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工资偏转了五百元。", "explanation": "这里应该用〈增加〉。偏转指方向的改变，工资数额的增加应用增加。"}, {"text": "这张桌子的高度偏转了十厘米。", "explanation": "这里应该用〈调整〉。偏转指方向的改变，高度的改动应用调整。"}, {"text": "他对这件事的看法有些偏转。", "explanation": "这里应该用〈偏颇〉。偏转指物体方向的改变，描述看法有偏向要用偏颇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风把船头偏转了到一边。", "corrected_sentence": "风把船头偏转到了一边。", "error_description": "错误：“偏转了到”；正确：“偏转到了”。“了”应该放在表示结果的“到一边”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把镜头向左偏转得一点。", "corrected_sentence": "他把镜头向左偏转了一点。", "error_description": "错误：“偏转得一点”；正确：“偏转了一点”。这里表示已经完成的调整，应用“了”，“得”不能直接接“一点”作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
