INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12171, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，连接两个分句，表示前后对比，如“A…，B则…”。", "primary_collocate": null, "pronunciation": "zé", "ipa": "tsɤ˧˥", "syllable_count": 1, "sentences": [{"text": "东部雨水很多，西部则很干燥。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥喜欢唱歌，弟弟则喜欢画画。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱吃甜的，妹妹则爱吃辣的。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，冬天则非常冷。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市人很多，这个小城则很安静。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢喝茶，他则喜欢喝咖啡。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家做饭，爸爸则出去买菜了。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢早起，他太太则喜欢晚睡。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方人爱吃面，南方人则爱吃米饭。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白天这里很吵，到了晚上则安静下来。", "target_word": "则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "连词；连接两个分句，表示前后对比，常说“A…，B则…”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be2b17fa-c08d-40b7-9a9a-4277d5c11bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12171, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "则", "is_correct": true, "explanation": "则 zé，连词，表示前后对比。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 zé 声母不同（zh 与 z），意思是折叠。"}, {"text": "贼", "is_correct": false, "explanation": "zéi（第二声）与 zé 韵母不同（ei 与 e），意思是小偷。"}, {"text": "哲", "is_correct": false, "explanation": "zhé 与 zé 声母不同（zh 与 z），意思是哲学、智慧。"}, {"text": "蛇", "is_correct": false, "explanation": "shé 与 zé 声母不同（sh 与 z），意思是蛇。"}, {"text": "德", "is_correct": false, "explanation": "dé 与 zé 声母不同（d 与 z），意思是道德。"}], "explanations": {"则": "则 zé，连词，表示前后对比。", "折": "zhé（第二声）与 zé 声母不同（zh 与 z），意思是折叠。", "贼": "zéi（第二声）与 zé 韵母不同（ei 与 e），意思是小偷。", "哲": "zhé 与 zé 声母不同（zh 与 z），意思是哲学、智慧。", "蛇": "shé 与 zé 声母不同（sh 与 z），意思是蛇。", "德": "dé 与 zé 声母不同（d 与 z），意思是道德。"}, "sentence_index": null, "correct_answer": "则"}, "level_3": {"options": [{"text": "则", "is_correct": true, "explanation": "则：连词，表示前后对比，“东部……”与“西部……”形成对比。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示同样或并列，与前后对比的关系不合。"}, {"text": "就", "is_correct": false, "explanation": "语义：“就”表示顺承或结果，不表示对比。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复或追加，不表示对比。"}], "explanations": {"则": "则：连词，表示前后对比，“东部……”与“西部……”形成对比。", "也": "语义：“也”表示同样或并列，与前后对比的关系不合。", "就": "语义：“就”表示顺承或结果，不表示对比。", "又": "语义：“又”表示重复或追加，不表示对比。"}, "sentence_index": 0, "correct_answer": "则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在报上看到一则招聘广告。", "explanation": "这里的〈则〉是量词，用于广告，不表示对比或承接。"}, {"text": "今天报纸上有一则新闻。", "explanation": "这里的〈则〉是量词，用于新闻，不表示对比。"}, {"text": "他戒烟有两个原因：一则为了健康，二则为了省钱。", "explanation": "这里的〈则〉用于列举原因，不表示对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12171, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "则", "is_correct": true, "explanation": "则 zé，表示前后对比，实际情况不同。"}, {"text": "格", "is_correct": false, "explanation": "gé 与 zé 声母不同（g 与 z），意思是格子。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 zé 声母不同（g 与 z），意思是隔开。"}, {"text": "舌", "is_correct": false, "explanation": "shé 与 zé 声母不同（sh 与 z），意思是舌头。"}, {"text": "得", "is_correct": false, "explanation": "dé 与 zé 声母不同（d 与 z），意思是获得。"}], "explanations": {"则": "则 zé，表示前后对比，实际情况不同。", "格": "gé 与 zé 声母不同（g 与 z），意思是格子。", "隔": "gé 与 zé 声母不同（g 与 z），意思是隔开。", "舌": "shé 与 zé 声母不同（sh 与 z），意思是舌头。", "得": "dé 与 zé 声母不同（d 与 z），意思是获得。"}, "sentence_index": null, "correct_answer": "则"}, "level_3": {"options": [{"text": "则", "is_correct": true, "explanation": "则：表示前后对比，“妈妈在家做饭”与“爸爸出去买菜”形成对比。"}, {"text": "因为", "is_correct": false, "explanation": "语义：因为表示原因，“妈妈做饭”并不构成“爸爸出门”的原因。"}, {"text": "因而", "is_correct": false, "explanation": "搭配：因而要求前文为原因，这里前后没有因果关系。"}, {"text": "从而", "is_correct": false, "explanation": "语义：从而表示结果，与这里前后分别叙述的关系不合。"}], "explanations": {"则": "则：表示前后对比，“妈妈在家做饭”与“爸爸出去买菜”形成对比。", "因为": "语义：因为表示原因，“妈妈做饭”并不构成“爸爸出门”的原因。", "因而": "搭配：因而要求前文为原因，这里前后没有因果关系。", "从而": "语义：从而表示结果，与这里前后分别叙述的关系不合。"}, "sentence_index": 6, "correct_answer": "则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案有两点好处：一则成本低，二则效果好。", "explanation": "这里的〈则〉用于列举，“一则……二则……”，不表示对比或承接。"}, {"text": "这是一则寓言，很有意思。", "explanation": "这里的〈则〉是量词，用于寓言，不表示对比。"}, {"text": "他讲了一则笑话，大家都笑了。", "explanation": "这里的〈则〉是量词，用于笑话，不表示对比或承接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末他去看书，妹妹在则家看电视。", "corrected_sentence": "周末他去看书，妹妹则在家看电视。", "error_description": "错误：“在则家”；正确：“则在家”。“则”是连词，应放在后一分句主语“妹妹”之后、“在家”之前，不能插进“在家”中间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥很高，弟弟却则很矮。", "corrected_sentence": "哥哥很高，弟弟则很矮。", "error_description": "错误：“却则”；正确：“则”。“则”本身已表示对比，不能与“却”叠用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不等", "is_correct": true, "explanation": "“不等”指彼此不相等，与“相等”构成反义关系。"}, {"text": "平坦", "is_correct": false, "explanation": "“平坦”形容表面没有起伏，与“相等”的数量或程度无关，不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、不模糊，与“相等”不是相对的关系。"}, {"text": "迟缓", "is_correct": false, "explanation": "“迟缓”形容速度慢或反应慢，与“相等”没有反义关系。"}], "correct_answer": "不等", "explanations": {"不等": "“不等”指彼此不相等，与“相等”构成反义关系。", "平坦": "“平坦”形容表面没有起伏，与“相等”的数量或程度无关，不构成反义。", "清楚": "“清楚”形容明白、不模糊，与“相等”不是相对的关系。", "迟缓": "“迟缓”形容速度慢或反应慢，与“相等”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不等", "is_correct": true, "explanation": "“不等”指不相等，与“相等”构成反义关系。"}, {"text": "寂静", "is_correct": false, "explanation": "“寂静”形容没有声音，与“相等”的数量或程度无关。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地不硬，与“相等”没有反义关系。"}, {"text": "锋利", "is_correct": false, "explanation": "“锋利”形容刀刃等尖锐，与“相等”不构成反义。"}], "correct_answer": "不等", "explanations": {"不等": "“不等”指不相等，与“相等”构成反义关系。", "寂静": "“寂静”形容没有声音，与“相等”的数量或程度无关。", "柔软": "“柔软”形容质地不硬，与“相等”没有反义关系。", "锋利": "“锋利”形容刀刃等尖锐，与“相等”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指两个或多个事物在数量、程度、性质等方面完全相同。", "primary_collocate": null, "pronunciation": "xiāng děng", "ipa": "ɕjaŋ˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "相等", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两个盒子的重量相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个角的大小相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这四根木条的长度相等，可以拼成一个正方形框。", "target_word": "相等", "complexity_tier": "T3", "furigana": "zhè sì gēn mù tiáo de cháng dù xiāng děng, kě yǐ pīn chéng yí gè zhèng fāng xíng kuàng", "sentence_source": "generated"}, {"text": "这两条路的长度相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个班的人数几乎相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队的力量相等，比赛很难分胜负。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆的半径都相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的钱和我的钱数量相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等号两边的数一定相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相等", "label": "否定"}], "register": "中性", "sense_fingerprint": "两个或多个事物在数量、程度、性质上完全相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相等", "is_correct": true, "explanation": "“相等”指大小完全相同，与“且反向的力”配合，符合牛顿第三定律对作用力与反作用力的描述。"}, {"text": "相邻", "is_correct": false, "explanation": "语义：“相邻”指位置挨着，不能用来说力的数值相同。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体积或个子，不用来形容力的大小。"}, {"text": "相交", "is_correct": false, "explanation": "语义：“相交”指线或面彼此穿过，不用来形容力的大小。"}], "explanations": {"相等": "“相等”指大小完全相同，与“且反向的力”配合，符合牛顿第三定律对作用力与反作用力的描述。", "相邻": "语义：“相邻”指位置挨着，不能用来说力的数值相同。", "高大": "语义：“高大”形容体积或个子，不用来形容力的大小。", "相交": "语义：“相交”指线或面彼此穿过，不用来形容力的大小。"}, "sentence_index": 0, "correct_answer": "相等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两件衬衫的款式相等。", "explanation": "这里应该用〈相同〉。相等用于长度、数量、程度等可以量化的情况，款式、颜色要用相同。"}, {"text": "他和爸爸的性格很相等。", "explanation": "这里应该用〈相似〉。相等强调数量或程度完全一样，描述性格的接近要用相似。"}, {"text": "我们的意见很相等。", "explanation": "这里应该用〈一致〉。相等指数量或程度完全相同，意见的统一要用一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相等", "is_correct": true, "explanation": "“相等”指实力或数量完全相同，与“比赛很难分胜负”的语境一致。"}, {"text": "宽阔", "is_correct": false, "explanation": "语义：“宽阔”形容空间或面积，不用来形容力量。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指事物古老、不新鲜，与两队力量的比较无关。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人的态度，不能用来描述两队的力量。"}], "explanations": {"相等": "“相等”指实力或数量完全相同，与“比赛很难分胜负”的语境一致。", "宽阔": "语义：“宽阔”形容空间或面积，不用来形容力量。", "陈旧": "语义：“陈旧”指事物古老、不新鲜，与两队力量的比较无关。", "懒惰": "语义：“懒惰”形容人的态度，不能用来描述两队的力量。"}, "sentence_index": 6, "correct_answer": "相等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件外套与你的气质很相等。", "explanation": "这里应该用〈相称〉。相等指数量或程度完全相同，外套与气质的协调要用相称。"}, {"text": "这个孩子和父亲很相等。", "explanation": "这里应该用〈相像〉。相等用于数量或程度的比较，说人的长相接近要用相像。"}, {"text": "我们俩的名字很相等。", "explanation": "这里应该用〈相同〉。相等用于可以量化的数量或程度，名字是否一样要用相同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我比他的身高相等。", "corrected_sentence": "我和他的身高相等。", "error_description": "“相等”表示两者相同，比较对象要用“和/跟……相等”，不能用“比”。应把“比”改为“和”，说“我和他的身高相等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把两块布的长度相等。", "corrected_sentence": "他们把两块布的长度弄得相等。", "error_description": "“相等”是形容词，不能直接放在“把”的后面作谓语。要表示使两块布的长度变得相等，需要补上“弄得”，应说“把……弄得相等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同向", "is_correct": true, "explanation": "正确：“同向”与“反向”构成反义，一个说方向相同，一个说方向相反。"}, {"text": "平行", "is_correct": false, "explanation": "“平行”说两条线方向一致且不相交，不是“方向相反”的对立面。"}, {"text": "垂直", "is_correct": false, "explanation": "“垂直”说两者成直角，不是方向相反，也不构成反义。"}, {"text": "相等", "is_correct": false, "explanation": "“相等”说数量或程度一样，与方向无关，不构成反义。"}], "correct_answer": "同向", "explanations": {"同向": "正确：“同向”与“反向”构成反义，一个说方向相同，一个说方向相反。", "平行": "“平行”说两条线方向一致且不相交，不是“方向相反”的对立面。", "垂直": "“垂直”说两者成直角，不是方向相反，也不构成反义。", "相等": "“相等”说数量或程度一样，与方向无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同向", "is_correct": true, "explanation": "正确：“同向”与“反向”构成反义，一个说方向相同，一个说方向相反。"}, {"text": "平稳", "is_correct": false, "explanation": "“平稳”说状态安定、没有起伏，与方向无关，不构成反义。"}, {"text": "斜向", "is_correct": false, "explanation": "“斜向”指既非相同也非相反的方向，与“反向”不构成反义。"}, {"text": "恒定", "is_correct": false, "explanation": "“恒定”说数值或状态不变，与方向相反无关，不构成反义。"}], "correct_answer": "同向", "explanations": {"同向": "正确：“同向”与“反向”构成反义，一个说方向相同，一个说方向相反。", "平稳": "“平稳”说状态安定、没有起伏，与方向无关，不构成反义。", "斜向": "“斜向”指既非相同也非相反的方向，与“反向”不构成反义。", "恒定": "“恒定”说数值或状态不变，与方向相反无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "方向完全相反的，用于描述力或动作的方向关系", "primary_collocate": null, "pronunciation": "fǎn xiàng", "ipa": "fan˨˩ ɕjaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "然而，仅依赖伯努利原理并不足以完全描述复杂的真实流动现象，因此现代空气动力学更倾向于结合牛顿第三定律进行综合分析：机翼通过攻角向下偏转气流，气流则以相等且反向的力推动机翼上升，从而产生升力。", "target_word": "反向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "与之同时存在的还有阻力，这是空气对飞机前进运动施加的反向力，可细分为压差阻力、摩擦阻力以及诱导阻力等多种类型。", "target_word": "反向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "风从前面吹来，给车一个反向的力。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个反向的力一样大，箱子不动。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，我感到一股反向的力。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向前推，我用反向的力拉。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭向下喷气，就得到反向推力。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水向东流，船要用反向的力才能停。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反向的力越大，车停得越快。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹簧给手一个反向的力。", "target_word": "反向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "方向完全相反的（形容词，修饰力、运动等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：反向（fǎn xiàng）意思是方向完全相反。"}, {"text": "返乡", "is_correct": false, "explanation": "声调不同：第一音节都是 fǎn，第二音节 xiāng（第一声）与 xiàng（第四声）声调不同，返乡意思是回到家乡。"}, {"text": "反响", "is_correct": false, "explanation": "声调不同：第二音节 xiǎng（第三声）与 xiàng（第四声）声调不同，反响意思是回声或反应。"}, {"text": "饭香", "is_correct": false, "explanation": "声调不同：fàn（第四声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，饭香意思是饭的香气。"}, {"text": "翻箱", "is_correct": false, "explanation": "声调不同：fān（第一声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，翻箱意思是翻找箱子。"}], "explanations": {"反向": "正确：反向（fǎn xiàng）意思是方向完全相反。", "返乡": "声调不同：第一音节都是 fǎn，第二音节 xiāng（第一声）与 xiàng（第四声）声调不同，返乡意思是回到家乡。", "反响": "声调不同：第二音节 xiǎng（第三声）与 xiàng（第四声）声调不同，反响意思是回声或反应。", "饭香": "声调不同：fàn（第四声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，饭香意思是饭的香气。", "翻箱": "声调不同：fān（第一声）与 fǎn（第三声）不同，xiāng（第一声）与 xiàng（第四声）也不同，翻箱意思是翻找箱子。"}, "sentence_index": null, "correct_answer": "反向"}, "level_3": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：“反向”说方向完全相反，与“相等且反向的力”推动机翼上升相符。"}, {"text": "同向", "is_correct": false, "explanation": "语义：“同向”说方向相同，与气流向下、机翼受反向力向上的牛顿第三定律描述相矛盾。"}, {"text": "水平", "is_correct": false, "explanation": "语义：“水平”指与地面平行的方向，不能推动机翼上升，与“上升”相矛盾。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“静止”形容物体的状态，不能直接修饰“力”。"}], "explanations": {"反向": "正确：“反向”说方向完全相反，与“相等且反向的力”推动机翼上升相符。", "同向": "语义：“同向”说方向相同，与气流向下、机翼受反向力向上的牛顿第三定律描述相矛盾。", "水平": "语义：“水平”指与地面平行的方向，不能推动机翼上升，与“上升”相矛盾。", "静止": "搭配：“静止”形容物体的状态，不能直接修饰“力”。"}, "sentence_index": 0, "correct_answer": "反向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们对这件事的看法完全反向。", "explanation": "这里应该用〈相反〉。“反向”多用于方向、力或运动，对事情的看法、观点的对立要说“相反”。"}, {"text": "两派的立场反向。", "explanation": "这里应该用〈对立〉。“反向”指方向相反，立场之间的对峙要说“对立”。"}, {"text": "这与他的想法反向。", "explanation": "这里应该用〈相悖〉。“反向”指方向或力的相反，与想法、道理相抵触要说“相悖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反向", "is_correct": true, "explanation": "正确：“反向推力”指与喷气方向相反的推力，与“火箭向下喷气”相符。"}, {"text": "同步", "is_correct": false, "explanation": "搭配：“同步”指时间上一致，不能修饰“推力”。"}, {"text": "慢性", "is_correct": false, "explanation": "语义：“慢性”指病程长、发展缓慢，与“推力”的意义不相关。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“红色”指颜色，不能说“红色推力”。"}], "explanations": {"反向": "正确：“反向推力”指与喷气方向相反的推力，与“火箭向下喷气”相符。", "同步": "搭配：“同步”指时间上一致，不能修饰“推力”。", "慢性": "语义：“慢性”指病程长、发展缓慢，与“推力”的意义不相关。", "红色": "搭配：“红色”指颜色，不能说“红色推力”。"}, "sentence_index": 6, "correct_answer": "反向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两块布的颜色反向。", "explanation": "这句“反向”用于颜色，颜色之间没有方向关系，应该用〈迥异〉。“反向”只用于描述力或动作的方向相反。"}, {"text": "这两个孩子的年龄反向。", "explanation": "这句“反向”用于年龄，年龄之间只有数值的差距，应该用〈悬殊〉。“反向”只用于描述力或动作的方向相反。"}, {"text": "我和弟弟的体重反向。", "explanation": "这句“反向”用于体重，体重之间只有数量的差别，应该用〈相差〉。“反向”只用于描述力或动作的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两股很反向的力把绳子拉直了。", "corrected_sentence": "两股反向的力把绳子拉直了。", "error_description": "错误：“很反向”。“反向”是非等级形容词，不能加“很”修饰。正确说法是“两股反向的力把绳子拉直了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用反向得力拉住了门。", "corrected_sentence": "我用反向的力拉住了门。", "error_description": "错误：“反向得力”。“反向”修饰名词“力”，结构助词应用“的”，不能用“得”。正确为“我用反向的力拉住了门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将某种事物或力量加在另一个事物或人身上。", "primary_collocate": null, "pronunciation": "shī jiā", "ipa": "ʂɻ̩˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "与之同时存在的还有阻力，这是空气对飞机前进运动施加的反向力，可细分为压差阻力、摩擦阻力以及诱导阻力等多种类型。", "target_word": "施加", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在当代全球化经济图景中，快时尚产业的崛起不仅重塑了消费者的穿衣模式，更对地球脆弱的水资源系统施加了前所未有的压力。", "target_word": "施加", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师没有对我们施加压力。", "target_word": "施加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对箱子施加了一个向上的力。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该对孩子施加太大的压力。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在木板上施加压力，把它压平。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对这家公司施加了很大影响。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对员工施加压力，要大家加班。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对这个国家施加过很多压力。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个力施加在桌子上，桌子动了。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "施加了", "label": "体标"}, {"form": "施加着", "label": "体标"}, {"form": "施加过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把压力、影响或力加到人或物上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施加", "is_correct": true, "explanation": "正确。施加 shī jiā，指把力量、压力或影响加在人或物上。"}, {"text": "事假", "is_correct": false, "explanation": "shì jià 与 shī jiā 两个字声调都不同，“事假”意思是因私事请的假。"}, {"text": "私家", "is_correct": false, "explanation": "sī 与 shī 声母不同（s 与 sh），“私家”意思是私人的，如“私家车”。"}, {"text": "世家", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，“世家”意思是世代有名望的家族。"}, {"text": "时价", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）、jià（第四声）与 jiā（第一声）声调都不同，“时价”意思是当时的价格。"}], "explanations": {"施加": "正确。施加 shī jiā，指把力量、压力或影响加在人或物上。", "事假": "shì jià 与 shī jiā 两个字声调都不同，“事假”意思是因私事请的假。", "私家": "sī 与 shī 声母不同（s 与 sh），“私家”意思是私人的，如“私家车”。", "世家": "shì（第四声）与 shī（第一声）声调不同，“世家”意思是世代有名望的家族。", "时价": "shí（第二声）与 shī（第一声）、jià（第四声）与 jiā（第一声）声调都不同，“时价”意思是当时的价格。"}, "sentence_index": null, "correct_answer": "施加"}, "level_3": {"options": [{"text": "施加", "is_correct": true, "explanation": "正确。施加表示把力加在对象上，与“空气对飞机前进运动施加的反向力”相符。"}, {"text": "偏爱", "is_correct": false, "explanation": "语义：“偏爱”的施事须是有意识的人，空气不能偏爱飞机的运动。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”的施事须是人，空气不能赞美飞机的运动。"}, {"text": "忍受", "is_correct": false, "explanation": "搭配：“忍受”的施事须是有感受的人或动物，空气对飞机的运动不能忍受。"}], "explanations": {"施加": "正确。施加表示把力加在对象上，与“空气对飞机前进运动施加的反向力”相符。", "偏爱": "语义：“偏爱”的施事须是有意识的人，空气不能偏爱飞机的运动。", "赞美": "语义：“赞美”的施事须是人，空气不能赞美飞机的运动。", "忍受": "搭配：“忍受”的施事须是有感受的人或动物，空气对飞机的运动不能忍受。"}, "sentence_index": 0, "correct_answer": "施加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在汤里施加了一勺盐。", "explanation": "这里应该用〈加〉。施加指把力量、压力或影响加在人或物上，往汤里放调料要说加。"}, {"text": "他在墙上施加了一层油漆。", "explanation": "这里应该用〈涂〉。施加指把力量、压力或影响加在人或物上，往墙上刷油漆要说涂。"}, {"text": "我向老师施加了感谢。", "explanation": "这里应该用〈表示〉。施加的对象是力量、压力或影响，感谢是情感表达，应说表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施加", "is_correct": true, "explanation": "正确。施加表示把影响加在对象上，与“政府对这家公司施加了很大影响”相符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”是自己得到好处，不能“对公司享受影响”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“对公司……了很大影响”句意矛盾。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”的宾语多是文章、意见，不能说发表“影响”。"}], "explanations": {"施加": "正确。施加表示把影响加在对象上，与“政府对这家公司施加了很大影响”相符。", "享受": "语义：“享受”是自己得到好处，不能“对公司享受影响”。", "拒绝": "语义：“拒绝”表示不接受，与“对公司……了很大影响”句意矛盾。", "发表": "搭配：“发表”的宾语多是文章、意见，不能说发表“影响”。"}, "sentence_index": 6, "correct_answer": "施加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨施加了很大的损失。", "explanation": "这里应该用〈造成〉。施加的对象是力量或影响，“损失”是结果，应说造成。"}, {"text": "这件事施加了大家的注意。", "explanation": "这里应该用〈引起〉。施加用于压力、力量或影响，“注意”应说引起。"}, {"text": "领导施加了一个决定。", "explanation": "这里应该用〈做〉。决定是人做出的，不能说施加，应说做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把墙面施加了压力。", "corrected_sentence": "工人对墙面施加了压力。", "error_description": "“施加”的受事要用介词“对”引出，不能用“把”字句，应将“把”改为“对”，写作“工人对墙面施加了压力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们正在对这块石头施加了一点力。", "corrected_sentence": "我们正在对这块石头施加一点力。", "error_description": "“正在”表示动作正在进行，不能与完成体“了”同用，应去掉“了”，写作“我们正在对这块石头施加一点力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "“合并”指把分开的部分合成一体，与“细分”的意思相对。"}, {"text": "挑选", "is_correct": false, "explanation": "“挑选”指从多者中选出，与“细分”的意思无相对关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指使损坏的东西恢复正常，与“细分”无反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "“提醒”指让人注意，与“细分”没有反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "“合并”指把分开的部分合成一体，与“细分”的意思相对。", "挑选": "“挑选”指从多者中选出，与“细分”的意思无相对关系。", "修理": "“修理”指使损坏的东西恢复正常，与“细分”无反义关系。", "提醒": "“提醒”指让人注意，与“细分”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "“合并”指把分开的部分合成一体，与“细分”的意思相对。"}, {"text": "浇灌", "is_correct": false, "explanation": "“浇灌”指把水注入土地或植物，与“细分”无反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“细分”没有相对的关系。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指使东西不损坏，与“细分”无反义关系。"}], "correct_answer": "合并", "explanations": {"合并": "“合并”指把分开的部分合成一体，与“细分”的意思相对。", "浇灌": "“浇灌”指把水注入土地或植物，与“细分”无反义关系。", "观察": "“观察”指仔细看，与“细分”没有相对的关系。", "保存": "“保存”指使东西不损坏，与“细分”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将整体事物按照某种标准分成若干较小的部分。", "primary_collocate": null, "pronunciation": "xì fēn", "ipa": "ɕi˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "与之同时存在的还有阻力，这是空气对飞机前进运动施加的反向力，可细分为压差阻力、摩擦阻力以及诱导阻力等多种类型。", "target_word": "细分", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师把这个问题细分成三个小问题。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把客户细分为老人、学生和上班族。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以把工作细分成几个步骤。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店把商品细分后，顾客找东西更方便。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班级可以细分成四个学习小组。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店把图书细分为文学、历史和科学。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者先把市场细分，再决定卖给谁。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的科室还可以细分成很多小科。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告内容很多，可以把它细分为几个部分。", "target_word": "细分", "complexity_tier": "T3", "furigana": "zhè fèn bào gào nèi róng hěn duō, kě yǐ bǎ tā xì fēn wéi jǐ gè bù fen", "sentence_source": "generated"}], "morphological_forms": [{"form": "细分了", "label": "体标"}, {"form": "细分化", "label": "复合"}, {"form": "細分", "label": "繁体"}], "register": "书面", "sense_fingerprint": "按某种标准把整体分成若干较小的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "细分", "is_correct": true, "explanation": "“细分”指按某种标准把整体分成若干较小的部分。"}, {"text": "细粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，“细粉”指很细的粉末。"}, {"text": "戏份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，“戏份”指角色在戏中的分量。"}, {"text": "吸粉", "is_correct": false, "explanation": "xī fěn 与 xì fēn 两个音节声调都不同，“吸粉”指吸引粉丝。"}], "explanations": {"细分": "“细分”指按某种标准把整体分成若干较小的部分。", "细粉": "fěn（第三声）与 fēn（第一声）声调不同，“细粉”指很细的粉末。", "戏份": "fèn（第四声）与 fēn（第一声）声调不同，“戏份”指角色在戏中的分量。", "吸粉": "xī fěn 与 xì fēn 两个音节声调都不同，“吸粉”指吸引粉丝。"}, "sentence_index": null, "correct_answer": "细分"}, "level_3": {"options": [{"text": "细分", "is_correct": true, "explanation": "“细分”表示把整体按标准分成较小部分，与“可……为……多种类型”相符。"}, {"text": "合并", "is_correct": false, "explanation": "语义：“合并”指把几部分合为一体，与“分为多种类型”的意思相反。"}, {"text": "叠加", "is_correct": false, "explanation": "搭配：“叠加”要说“叠加在……上”，不能说“叠加为”。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大”指范围或规模变大，与分成若干部分的意思不符。"}], "explanations": {"细分": "“细分”表示把整体按标准分成较小部分，与“可……为……多种类型”相符。", "合并": "语义：“合并”指把几部分合为一体，与“分为多种类型”的意思相反。", "叠加": "搭配：“叠加”要说“叠加在……上”，不能说“叠加为”。", "扩大": "语义：“扩大”指范围或规模变大，与分成若干部分的意思不符。"}, "sentence_index": 0, "correct_answer": "细分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板把几个部门细分成一个大部门。", "explanation": "这里应该用〈合并〉。细分是把整体分成较小的部分，把几个部门合为一个要用合并。"}, {"text": "这几所学校细分为一所。", "explanation": "这里应该用〈归并〉。细分是把整体分成若干部分，把几所学校并为一所要用归并。"}, {"text": "他们把两张桌子细分了。", "explanation": "这里应该用〈分开〉。细分指按标准划分整体，把两件东西隔开要用分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细分", "is_correct": true, "explanation": "“细分”指按标准把图书分成较小的类别，与“为文学、历史和科学”相符。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”指用刀等把东西割开，图书不是这样分类的。"}, {"text": "分配", "is_correct": false, "explanation": "配价：“分配”要说“分配给……”，不能说“分配为……”。"}, {"text": "堆放", "is_correct": false, "explanation": "语义：“堆放”指把东西摞在一处，图书不是这样分类的，也不能说堆放为类别。"}], "explanations": {"细分": "“细分”指按标准把图书分成较小的类别，与“为文学、历史和科学”相符。", "切开": "语义：“切开”指用刀等把东西割开，图书不是这样分类的。", "分配": "配价：“分配”要说“分配给……”，不能说“分配为……”。", "堆放": "语义：“堆放”指把东西摞在一处，图书不是这样分类的，也不能说堆放为类别。"}, "sentence_index": 6, "correct_answer": "细分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个组织因为内部争论而细分了。", "explanation": "这里应该用〈分裂〉。细分指按标准划分整体，组织因争论而散裂要用分裂。"}, {"text": "这对恋人因为误会细分了。", "explanation": "这里应该用〈分手〉。细分指按标准划分整体，恋人的断绝关系要用分手。"}, {"text": "这支队伍在山里被敌人细分了。", "explanation": "这里应该用〈分散〉。细分指按标准划分，队伍被敌人冲散要用分散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书可以细分三个章节。", "corrected_sentence": "这本书可以细分成三个章节。", "error_description": "“细分”后面要用“成”或“为”引出结果，漏掉“成”不符合说法。应说“细分成三个章节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商店把货物细分在三类。", "corrected_sentence": "这家商店把货物细分成三类。", "error_description": "错误：“细分在三类”；正确：“细分成三类”。“在”表示处所，不能引出细分的结果，结果要用“成”或“为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
