INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "压差是指两个位置或系统之间的压力数值差。", "primary_collocate": null, "pronunciation": "yā chā", "ipa": "ja˥ ʈʂʰa˥", "syllable_count": 2, "sentences": [{"text": "与之同时存在的还有阻力，这是空气对飞机前进运动施加的反向力，可细分为压差阻力、摩擦阻力以及诱导阻力等多种类型。", "target_word": "压差", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "压差", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两个房间的压差很大，门很难推开。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仪表显示，两个气室的压差是五十帕。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用表测量水管两端的压差。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压差越大，水流得越快。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能自动调节压差。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洁净室里的压差要保持稳定。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过滤器堵了，前后压差就会变大。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，我们记录了两端的压差变化。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "两个位置或系统之间压力的数值差（名词，科技术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压差", "is_correct": true, "explanation": "正确：“压差阻力”指由前后压力差产生的阻力，符合文中的分类。"}, {"text": "温差", "is_correct": false, "explanation": "语义：“温差”指温度的差值，与阻力的分类无关。"}, {"text": "压强", "is_correct": false, "explanation": "搭配：阻力不说“压强阻力”，“压强”指单位面积上的压力，不能修饰“阻力”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”指颜色，不能说“颜色阻力”。"}], "explanations": {"压差": "正确：“压差阻力”指由前后压力差产生的阻力，符合文中的分类。", "温差": "语义：“温差”指温度的差值，与阻力的分类无关。", "压强": "搭配：阻力不说“压强阻力”，“压强”指单位面积上的压力，不能修饰“阻力”。", "颜色": "搭配：“颜色”指颜色，不能说“颜色阻力”。"}, "sentence_index": 0, "correct_answer": "压差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块钢板的压差是两毫米。", "explanation": "这里应该用〈厚度〉。“压差”指压力的数值差，长度要说“厚度”，不能用“毫米”计量。"}, {"text": "这块蛋糕的压差是半斤。", "explanation": "这里应该用〈重量〉。“压差”指两处压力的数值差，物体有多重要说“重量”。"}, {"text": "这台机器的压差是每分钟五十次。", "explanation": "这里应该用〈频率〉。“压差”指压力的数值差，每分钟的次数要说“频率”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压差", "is_correct": true, "explanation": "正确：“调节压差”指调整两处的压力差，符合机器的功能。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“调节”不能用于“年龄”。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”是过去发生的事，机器无法调节。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：“辈分”指人际之间的长幼关系，与机器无关。"}], "explanations": {"压差": "正确：“调节压差”指调整两处的压力差，符合机器的功能。", "年龄": "搭配：“调节”不能用于“年龄”。", "历史": "语义：“历史”是过去发生的事，机器无法调节。", "辈分": "语义：“辈分”指人际之间的长幼关系，与机器无关。"}, "sentence_index": 6, "correct_answer": "压差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的压差很大。", "explanation": "这里应该用〈差距〉。“压差”指两个位置之间的压力数值差，不能用来形容一个人；人的能力或条件之间的差距要说“差距”。"}, {"text": "这里的压差是十五度。", "explanation": "这里应该用〈温差〉。“压差”指压力的数值差，温度之差要说“温差”，不能用“度”计量。"}, {"text": "这场比赛的压差很大。", "explanation": "这里应该用〈分差〉。“压差”指压力的数值差，比赛双方的得分之差要说“分差”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台泵两端的压差达了到五十帕。", "corrected_sentence": "这台泵两端的压差达到了五十帕。", "error_description": "错误：“达了到”。补语“到”必须紧贴动词“达”，“了”应放在补语之后，写作“达到了”；正确为“这台泵两端的压差达到了五十帕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管道两端地压差超过了安全值。", "corrected_sentence": "管道两端的压差超过了安全值。", "error_description": "错误：“两端地压差”。“压差”前的修饰语应用“的”，不能用“地”。正确为“管道两端的压差超过了安全值”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
