INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个物体接触并相对运动时，产生的阻碍运动的力。", "primary_collocate": null, "pronunciation": "mó cā zǔ lì", "ipa": "mwo˧˥ tsʰa˥ tsu˨˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "与之同时存在的还有阻力，这是空气对飞机前进运动施加的反向力，可细分为压差阻力、摩擦阻力以及诱导阻力等多种类型。", "target_word": "摩擦阻力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "摩擦阻力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "冰面很滑，摩擦阻力很小。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋底有花纹，能增大摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎和地面之间有摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在水里游泳，也要克服摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给机器加油可以减小摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机表面光滑，摩擦阻力就小。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摩擦阻力会让滑动的木箱慢慢停下。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表面越粗糙，摩擦阻力越大。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "两物体接触并相对运动时产生的阻碍运动的力（名词，科技术语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：摩擦阻力是阻力的一种，与压差阻力、诱导阻力并列。"}, {"text": "重力", "is_correct": false, "explanation": "语义：重力是地球对物体的吸引力，不是空气对飞机施加的阻力。"}, {"text": "推力", "is_correct": false, "explanation": "语义：推力使飞机前进，与阻碍运动的阻力方向相反，不能并列在阻力的类型之下。"}, {"text": "升力", "is_correct": false, "explanation": "搭配：“细分为”后接的是阻力的类型，升力与阻力相对，不能与阻力类型并列。"}], "explanations": {"摩擦阻力": "正确：摩擦阻力是阻力的一种，与压差阻力、诱导阻力并列。", "重力": "语义：重力是地球对物体的吸引力，不是空气对飞机施加的阻力。", "推力": "语义：推力使飞机前进，与阻碍运动的阻力方向相反，不能并列在阻力的类型之下。", "升力": "搭配：“细分为”后接的是阻力的类型，升力与阻力相对，不能与阻力类型并列。"}, "sentence_index": 0, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "月亮绕着地球转，是因为两者之间有摩擦阻力。", "explanation": "这里应该用〈引力〉。摩擦阻力是接触时阻碍运动的力，月地相隔遥远且并不接触，维系其运行的力要用引力。"}, {"text": "两家公司之间的摩擦阻力越来越大。", "explanation": "这里应该用〈矛盾〉。摩擦阻力是物理上的力，公司之间的冲突要用矛盾。"}, {"text": "木头能浮在水面上，是因为受到了摩擦阻力。", "explanation": "这里应该用〈浮力〉。摩擦阻力是接触时阻碍运动的力，把木头托起来的力要用浮力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：给机器加油可以减小的，正是两个接触面之间的摩擦阻力。"}, {"text": "体积", "is_correct": false, "explanation": "语义：加油不能使机器的体积变小，“减小体积”与加油的作用无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：机器的年龄不能通过加油减小，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色属于外观，加油不会改变机器的颜色，“减小颜色”说不通。"}], "explanations": {"摩擦阻力": "正确：给机器加油可以减小的，正是两个接触面之间的摩擦阻力。", "体积": "语义：加油不能使机器的体积变小，“减小体积”与加油的作用无关。", "年龄": "语义：机器的年龄不能通过加油减小，句意不通。", "颜色": "语义：颜色属于外观，加油不会改变机器的颜色，“减小颜色”说不通。"}, "sentence_index": 6, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车能向前开，是因为发动机提供了摩擦阻力。", "explanation": "这里应该用〈动力〉。摩擦阻力是阻碍运动的力，让汽车前进的力要用动力。"}, {"text": "苹果落到地上，是因为它受到的摩擦阻力太大。", "explanation": "这里应该用〈重力〉。摩擦阻力是阻碍运动的力，使苹果下落的力要用重力。"}, {"text": "用绳子拉车时，车前进的力来自摩擦阻力。", "explanation": "这里应该用〈拉力〉。摩擦阻力是阻碍运动的力，绳子拉动物体的力要用拉力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种鞋底的摩擦阻力小很。", "corrected_sentence": "这种鞋底的摩擦阻力很小。", "error_description": "错误：副词“很”应放在形容词“小”之前，写作“很小”，不能放在“小”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车轮轴承换了新油后，摩擦阻力减了小。", "corrected_sentence": "车轮轴承换了新油后，摩擦阻力减小了。", "error_description": "错误：“了”应放在补语“小”之后，写作“减小了”，不能写成“减了小”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
