INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用某种方法引导别人做某事，有时是好的，有时是坏的。", "primary_collocate": null, "pronunciation": "yòu dǎo", "ipa": "jou̯˥˩ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这条广告的标题很夸张，就是为了诱导人们点进去。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用有趣的问题诱导学生思考。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生耐心诱导病人说出心里的想法。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈诱导弟弟说出了真话。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有直接说答案，而是诱导大家自己找。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家用打折诱导顾客买更多东西。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人常常诱导孩子说出家里的地址。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想诱导我把钱借给他，我没有答应。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的故事能诱导孩子爱上读书。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子诱导老人在手机上输入密码。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱导了", "label": "体标"}, {"form": "诱导过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用方法引导别人去做某事，可好可坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "诱导", "is_correct": true, "explanation": "正确：诱导，用某种方法引导别人做某事。"}, {"text": "游到", "is_correct": false, "explanation": "声调不同：游到 yóu dào 的两个音节声调都与 yòu dǎo 不同，意思是游水抵达。"}, {"text": "有道", "is_correct": false, "explanation": "声调不同：有道 yǒu dào 与 yòu dǎo 的声调都不同，意思是有道理。"}, {"text": "右脑", "is_correct": false, "explanation": "声母不同：nǎo 与 dǎo 只差声母 n 与 d，意思是右半边的大脑。"}, {"text": "油道", "is_correct": false, "explanation": "声调不同：油道 yóu dào 的两个音节声调都与 yòu dǎo 不同，指输送润滑油的通道。"}], "explanations": {"诱导": "正确：诱导，用某种方法引导别人做某事。", "游到": "声调不同：游到 yóu dào 的两个音节声调都与 yòu dǎo 不同，意思是游水抵达。", "有道": "声调不同：有道 yǒu dào 与 yòu dǎo 的声调都不同，意思是有道理。", "右脑": "声母不同：nǎo 与 dǎo 只差声母 n 与 d，意思是右半边的大脑。", "油道": "声调不同：油道 yóu dào 的两个音节声调都与 yòu dǎo 不同，指输送润滑油的通道。"}, "sentence_index": null, "correct_answer": "诱导"}, "level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "正确：“为了诱导人们点进去”指用夸张的标题引导人去点击，符合诱导的义项。"}, {"text": "加热", "is_correct": false, "explanation": "语义：加热是给物体升温，不能用来引导人点进去。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却是降温，与引导人的行为无关。"}, {"text": "膨胀", "is_correct": false, "explanation": "语义：膨胀指体积变大，不能用来表示引导人的行为。"}], "explanations": {"诱导": "正确：“为了诱导人们点进去”指用夸张的标题引导人去点击，符合诱导的义项。", "加热": "语义：加热是给物体升温，不能用来引导人点进去。", "冷却": "语义：冷却是降温，与引导人的行为无关。", "膨胀": "语义：膨胀指体积变大，不能用来表示引导人的行为。"}, "sentence_index": 0, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大雨诱导了河水上涨。", "explanation": "这里应该用〈导致〉。诱导指用方法引导人做事，大雨造成河水上涨要用导致。"}, {"text": "这次地震诱导了山体滑坡。", "explanation": "这里应该用〈引发〉。诱导的对象是人，自然灾害引起的后果要用引发。"}, {"text": "这次事故诱导了大量损失。", "explanation": "这里应该用〈导致〉。诱导指引导人的行为，事故造成的损失要用导致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "正确：“坏人常常诱导孩子说出地址”，诱导指用方法引导人，带有隐蔽的意味，与坏人的身份相合。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：帮助是善意的行为，与坏人引出孩子地址的意图相矛盾。"}, {"text": "保护", "is_correct": false, "explanation": "语义：保护是防止伤害，句子却是让孩子说出地址，与坏人的身份不符。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：表扬的对象应是值得称赞的行为，“说出家里的地址”不是可以表扬的事，搭配不成立。"}], "explanations": {"诱导": "正确：“坏人常常诱导孩子说出地址”，诱导指用方法引导人，带有隐蔽的意味，与坏人的身份相合。", "帮助": "语义：帮助是善意的行为，与坏人引出孩子地址的意图相矛盾。", "保护": "语义：保护是防止伤害，句子却是让孩子说出地址，与坏人的身份不符。", "表扬": "搭配：表扬的对象应是值得称赞的行为，“说出家里的地址”不是可以表扬的事，搭配不成立。"}, "sentence_index": 6, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这项政策能诱导经济快速增长。", "explanation": "这里应该用〈推动〉。诱导的对象是人的行为，经济快速增长要用推动。"}, {"text": "这条规定诱导了学生的自由。", "explanation": "这里应该用〈限制〉。诱导指用方法引导人做事，限制学生的自由要用限制。"}, {"text": "坚持运动能诱导身体健康。", "explanation": "这里应该用〈促进〉。诱导指用方法引导人做事，身体健康的改善要用促进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师用游戏诱导孩子们地学汉字。", "corrected_sentence": "老师用游戏诱导孩子们学汉字。", "error_description": "错误：“孩子们地学汉字”。“诱导＋人＋做某事”是兼语句，兼语“孩子们”和后面的动词“学”之间不能加“地”，应删去；正确为“老师用游戏诱导孩子们学汉字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师诱导学生们了思考。", "corrected_sentence": "老师诱导学生们思考。", "error_description": "错误：“学生们了思考”。“了”不能插在兼语“学生们”与动词“思考”之间，应删去；正确为“老师诱导学生们思考”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
