INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机的身体部分，包括机舱和机翼等。", "primary_collocate": null, "pronunciation": "jī shēn", "ipa": "tɕi˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "这架飞机的机身很长。", "target_word": "机身", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人正在检查机身有没有裂缝。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机身上画着一只红色的大鸟。", "target_word": "机身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落时，机身轻轻抖了一下。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种飞机的机身是用轻金属做的。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机身两边各有一个大机翼。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他绕着机身走了一圈，看看有没有问题。", "target_word": "机身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把新机翼装到了机身上。", "target_word": "机身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机身受到撞击后，要马上检查。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机身上有一道长长的划痕，需要重新刷漆。", "target_word": "机身", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "飞机的主体结构，连接机翼、机舱和尾部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12182, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "机身", "is_correct": true, "explanation": "jī shēn，指飞机的主体部分，包括机舱和机翼相连的结构。"}, {"text": "击伤", "is_correct": false, "explanation": "jī shāng（-ang）与 jī shēn（-en）韵母不同，意思是打伤、撞伤。"}, {"text": "机声", "is_correct": false, "explanation": "jī shēng（-eng）与 jī shēn（-en）韵母不同，意思是机器发出的声音。"}, {"text": "资深", "is_correct": false, "explanation": "zī shēn（z-）与 jī shēn（j-）声母不同，意思是资历深。"}], "explanations": {"机身": "jī shēn，指飞机的主体部分，包括机舱和机翼相连的结构。", "击伤": "jī shāng（-ang）与 jī shēn（-en）韵母不同，意思是打伤、撞伤。", "机声": "jī shēng（-eng）与 jī shēn（-en）韵母不同，意思是机器发出的声音。", "资深": "zī shēn（z-）与 jī shēn（j-）声母不同，意思是资历深。"}, "sentence_index": null, "correct_answer": "机身"}, "level_3": {"options": [{"text": "跑道", "is_correct": false, "explanation": "语义：跑道是机场的设施，不属于飞机，不能说飞机的跑道很长。"}, {"text": "机身", "is_correct": true, "explanation": "“机身”是飞机的主体部分，可以说长短，符合“很长”的搭配。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“很长”形容物体的尺寸，不能用来形容乘客。"}, {"text": "机场", "is_correct": false, "explanation": "语义：机场是地面设施，不是飞机的一部分，不能说这架飞机的机场很长。"}], "explanations": {"跑道": "语义：跑道是机场的设施，不属于飞机，不能说飞机的跑道很长。", "机身": "“机身”是飞机的主体部分，可以说长短，符合“很长”的搭配。", "乘客": "搭配：“很长”形容物体的尺寸，不能用来形容乘客。", "机场": "语义：机场是地面设施，不是飞机的一部分，不能说这架飞机的机场很长。"}, "sentence_index": 0, "correct_answer": "机身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋大楼的机身很高，远远就能看见。", "explanation": "这里应该用〈楼身〉。机身专指飞机的机体，高楼的主体要说楼身。"}, {"text": "这辆车的机身被刮了一道划痕，需要重新喷漆。", "explanation": "这里应该用〈车身〉。机身专指飞机的主体，汽车的主体要说车身。"}, {"text": "这艘小船的机身漏水了，要马上修。", "explanation": "这里应该用〈船身〉。机身专指飞机，船的主体要说船身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不能绕着它走一圈检查有没有问题。"}, {"text": "机身", "is_correct": true, "explanation": "“机身”是飞机的主体，可以绕着它走一圈检查。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“绕着……走一圈”用于有形的物体，空气不能这样绕行检查。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是无法绕着走一圈检查的，句中的“检查问题”也不指天空。"}], "explanations": {"课本": "语义：课本是书，不能绕着它走一圈检查有没有问题。", "机身": "“机身”是飞机的主体，可以绕着它走一圈检查。", "空气": "搭配：“绕着……走一圈”用于有形的物体，空气不能这样绕行检查。", "天空": "语义：天空是无法绕着走一圈检查的，句中的“检查问题”也不指天空。"}, "sentence_index": 6, "correct_answer": "机身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵大树的机身很粗，要两个人才能抱住。", "explanation": "这里应该用〈树身〉。机身专指飞机的机体，树的主干要说树身。"}, {"text": "这条鱼的机身很长，有一米多。", "explanation": "这里应该用〈鱼身〉。机身专指飞机，鱼的躯干要说鱼身。"}, {"text": "这匹马的机身很健壮，跑起来很快。", "explanation": "这里应该用〈身躯〉。机身指飞机的机体，马的躯体要说身躯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵机身的颜色很亮，像是新漆的。", "corrected_sentence": "这个机身的颜色很亮，像是新漆的。", "error_description": "量词错误：“机身”应搭配“个”，不能说“这朵机身”。“朵”多用于花、云等，与飞机的机体不搭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这架飞机的机身把撞坏了。", "corrected_sentence": "这架飞机的机身被撞坏了。", "error_description": "句式错误：“机身”是被撞的对象，应用“被”字句，说“机身被撞坏了”；“把”字句要有宾语，“机身把撞坏了”缺少宾语，应把“把”改为“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
