INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体被切开后露出的平面或物体的横断表面。", "primary_collocate": null, "pronunciation": "jié miàn", "ipa": "tɕjɛ˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "压差阻力在机身截面剧烈变化处尤为显著。", "target_word": "截面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把木头锯开后，截面很平。", "target_word": "截面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看这根铁管的截面是圆的。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机翼的截面像一个扁扁的水滴。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师测量了钢梁的截面大小。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "截面越大，这根电线能通过的电流就越大。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用显微镜观察树枝的截面。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块金属的截面上有很多小孔。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水管的截面越小，水流得越快。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沿着这条线切开，截面会是长方形。", "target_word": "截面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "横截面", "label": "复合"}, {"form": "截面积", "label": "复合"}], "register": "科技", "sense_fingerprint": "物体横向切开后的平面，常用于工程和物理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12183, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "截面", "is_correct": true, "explanation": "jié miàn，指物体被切开后露出的平面。"}, {"text": "界面", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是交界处的表面或界面。"}, {"text": "斜面", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是倾斜的平面。"}, {"text": "街面", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是街道、街上。"}], "explanations": {"截面": "jié miàn，指物体被切开后露出的平面。", "界面": "jiè（第四声）与 jié（第二声）声调不同，意思是交界处的表面或界面。", "斜面": "xié 与 jié 声母不同（x 与 j），意思是倾斜的平面。", "街面": "jiē（第一声）与 jié（第二声）声调不同，意思是街道、街上。"}, "sentence_index": null, "correct_answer": "截面"}, "level_3": {"options": [{"text": "速度", "is_correct": false, "explanation": "搭配：“剧烈变化处”指形状或截面的变化，“速度”与此语境不搭配。"}, {"text": "截面", "is_correct": true, "explanation": "“截面”指物体横向切开后的平面，机身截面的变化影响阻力，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是气动阻力分析中的几何对象，此处讨论的不是颜色。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是乘坐设施，与气流和阻力无关，不能说机身座位剧烈变化。"}], "explanations": {"速度": "搭配：“剧烈变化处”指形状或截面的变化，“速度”与此语境不搭配。", "截面": "“截面”指物体横向切开后的平面，机身截面的变化影响阻力，符合句意。", "颜色": "语义：颜色不是气动阻力分析中的几何对象，此处讨论的不是颜色。", "座位": "语义：座位是乘坐设施，与气流和阻力无关，不能说机身座位剧烈变化。"}, "sentence_index": 0, "correct_answer": "截面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的截面有一道划痕，需要重新喷漆。", "explanation": "这里应该用〈侧面〉。截面指切开后露出的平面，车身的一侧要说侧面。"}, {"text": "这本书的截面上印着作者的照片。", "explanation": "这里应该用〈封面〉。截面指切开后露出的平面，书最外面印照片的一面要说封面。"}, {"text": "这只箱子的截面上印着公司的名字。", "explanation": "这里应该用〈表面〉。截面指横切后的断面，箱子外面印字的一面要说表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跑道", "is_correct": false, "explanation": "语义：跑道是机场的设施，不能用显微镜观察，也不是树枝的部分。"}, {"text": "截面", "is_correct": true, "explanation": "“截面”指切开后露出的平面，用显微镜观察树枝的截面很合理。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不是树枝的一部分，不能用显微镜观察。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能说树枝的体重。"}], "explanations": {"跑道": "语义：跑道是机场的设施，不能用显微镜观察，也不是树枝的部分。", "截面": "“截面”指切开后露出的平面，用显微镜观察树枝的截面很合理。", "乘客": "语义：乘客是人，不是树枝的一部分，不能用显微镜观察。", "体重": "搭配：“体重”用于人或动物，不能说树枝的体重。"}, "sentence_index": 6, "correct_answer": "截面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地的截面有一百平方米，可以种很多菜。", "explanation": "这里应该用〈面积〉。截面指切开后露出的平面，土地的大小要说面积。"}, {"text": "这条路的截面很长，一直延伸到山脚下。", "explanation": "这里应该用〈长度〉。截面指切开后露出的平面，路的长短要说长度。"}, {"text": "这把椅子的截面很重，搬起来很费力。", "explanation": "这里应该用〈重量〉。截面指切开后露出的平面，东西的轻重要说重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根铜线的一只截面是圆形的。", "corrected_sentence": "这根铜线的一个截面是圆形的。", "error_description": "量词错误：“截面”应搭配“个”，不能说“一只截面”。“只”多用于动物或成对物件中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块木头的截面磨的很光滑。", "corrected_sentence": "这块木头的截面磨得很光滑。", "error_description": "补语错误：动词后的程度补语要用“得”，写成“的”是误用。正确形式为“磨得很光滑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "和缓", "is_correct": true, "explanation": "和缓指温和、不猛烈，与剧烈意义相对。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆形容声音清亮，与剧烈的程度没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或色彩，与剧烈不构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指事情或事物头绪多，与剧烈没有反义关系。"}], "correct_answer": "和缓", "explanations": {"和缓": "和缓指温和、不猛烈，与剧烈意义相对。", "清脆": "清脆形容声音清亮，与剧烈的程度没有反义关系。", "明亮": "明亮形容光线或色彩，与剧烈不构成反义。", "复杂": "复杂指事情或事物头绪多，与剧烈没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "猛烈，强烈。", "primary_collocate": null, "pronunciation": "jù liè", "ipa": "tɕy˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说他现在不能做剧烈运动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头突然剧烈地疼起来。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海上的风浪越来越剧烈。", "target_word": "剧烈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "跑完一千米，我的心跳非常剧烈。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剧烈的咳嗽让她睡不着。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和同学为这件事发生了剧烈的争吵。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息后，他内心的痛苦非常剧烈。", "target_word": "剧烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛双方的对抗十分剧烈。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月菜价的波动很剧烈。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冷热的剧烈变化让很多人感冒了。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "剧烈地", "label": "副词形式"}, {"form": "劇烈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "程度很强、很猛，多形容运动、疼痛、变化、反应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧烈", "is_correct": true, "explanation": "剧烈修饰“运动”，表示强度很大，符合语境，可以填入空格。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：清淡多用于形容饮食，不能说“清淡运动”。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：寂静指没有声音，与运动的动态特点不符。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡形容态度或感情，不能修饰运动。"}], "explanations": {"剧烈": "剧烈修饰“运动”，表示强度很大，符合语境，可以填入空格。", "清淡": "搭配：清淡多用于形容饮食，不能说“清淡运动”。", "寂静": "语义：寂静指没有声音，与运动的动态特点不符。", "冷淡": "语义：冷淡形容态度或感情，不能修饰运动。"}, "sentence_index": 0, "correct_answer": "剧烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对绘画有一种非常剧烈的兴趣。", "explanation": "这里应该用〈浓厚〉。兴趣的程度要说“浓厚”；剧烈表示动作或变化猛烈，不与“兴趣”搭配。"}, {"text": "这次经历给我留下了非常剧烈的印象。", "explanation": "这里应该用〈深刻〉。印象的深浅要说“深刻”；剧烈表示动作或变化猛烈，不用来形容印象。"}, {"text": "这道菜的味道非常剧烈。", "explanation": "这里应该用〈浓〉。味道的浓淡要说“很浓”；剧烈表示动作或变化猛烈，不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧烈", "is_correct": true, "explanation": "剧烈修饰“痛苦”，表示程度强，符合语境，可以填入空格。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮形容光线，不能用来形容痛苦。"}, {"text": "平淡", "is_correct": false, "explanation": "语义：平淡指平静无波，与“非常”所强调的痛苦程度相矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆形容声音，不能修饰痛苦。"}], "explanations": {"剧烈": "剧烈修饰“痛苦”，表示程度强，符合语境，可以填入空格。", "明亮": "搭配：明亮形容光线，不能用来形容痛苦。", "平淡": "语义：平淡指平静无波，与“非常”所强调的痛苦程度相矛盾。", "清脆": "搭配：清脆形容声音，不能修饰痛苦。"}, "sentence_index": 6, "correct_answer": "剧烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子剧烈地放在墙角。", "explanation": "这里误把〈剧烈〉当作“用力、重重地”来用；剧烈指动作猛烈、动荡，平稳地把桌子放在墙角不能用剧烈，应说〈轻轻地〉。"}, {"text": "妈妈剧烈地教我做饭。", "explanation": "这里误把〈剧烈〉当作“严厉、狠狠地”来用；剧烈指动作猛烈，教做饭是耐心指导的活动，应说〈耐心地〉。"}, {"text": "他剧烈地睡了一整夜。", "explanation": "这里误把〈剧烈〉当作“沉、深”来用；睡觉是安静的状态，剧烈表示猛烈，应说〈安稳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在操场上剧烈的跑来跑去。", "corrected_sentence": "孩子们在操场上剧烈地跑来跑去。", "error_description": "剧烈修饰动词“跑”时要用“地”，写成“的”是误用。正确形式为“剧烈地跑”，“剧烈的”只能修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风刮的很剧烈，树枝都弯了。", "corrected_sentence": "风刮得很剧烈，树枝都弯了。", "error_description": "补语错误：“刮”后的程度补语要用“得”，写成“的”是误用。正确形式为“刮得很剧烈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
