INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示某事物出自某处、某人或某事，即其出处或由来。", "primary_collocate": null, "pronunciation": "lái yuán yú", "ipa": "lai˧˥ ɥɛn˧˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "这个故事的灵感来源于作者的童年。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的自信来源于多年的努力。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多新词来源于网络。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种习惯来源于小时候的生活。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的快乐常常来源于小事。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日来源于一个古老的传说。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好成绩来源于每天认真复习。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些知识来源于书本，也来源于生活。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的名字来源于一个地名。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的很多成语来源于历史故事。", "target_word": "来源于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "抽象事物（灵感、习惯、词语、自信等）的出处或由来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来源于", "is_correct": true, "explanation": "来源于表示灵感的出处，符合语境，可以填入空格。"}, {"text": "高于", "is_correct": false, "explanation": "语义：高于表示超过、比较高低，灵感不能拿来与童年比高低。"}, {"text": "位于", "is_correct": false, "explanation": "搭配：位于指处于某个处所，灵感不能“位于”某处。"}, {"text": "等于", "is_correct": false, "explanation": "语义：等于表示相同，与灵感的来处不符。"}], "explanations": {"来源于": "来源于表示灵感的出处，符合语境，可以填入空格。", "高于": "语义：高于表示超过、比较高低，灵感不能拿来与童年比高低。", "位于": "搭配：位于指处于某个处所，灵感不能“位于”某处。", "等于": "语义：等于表示相同，与灵感的来处不符。"}, "sentence_index": 0, "correct_answer": "来源于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书来源于我。", "explanation": "这里应该用〈属于〉。来源于说事物从何而来，书归谁所有要用属于，不能用来源于。"}, {"text": "这次会议来源于下午三点。", "explanation": "这里应该用〈在〉。来源于指事物的出处，不指时间点；表示时间要用在下午三点。"}, {"text": "这座公园来源于城市的北边。", "explanation": "这里应该用〈位于〉。来源于说事物从何而来，公园的方位要用位于，不能用来源于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来源于", "is_correct": true, "explanation": "来源于表示好成绩的原因，符合语境，可以填入空格。"}, {"text": "超过", "is_correct": false, "explanation": "语义：超过表示数量或程度的比较，与成绩和复习的因果关系不符。"}, {"text": "违背", "is_correct": false, "explanation": "语义：违背指不遵守，与好成绩的原因相反。"}, {"text": "缺乏", "is_correct": false, "explanation": "语义：缺乏表示不够、没有，说好成绩“缺乏”每天认真复习，与句意矛盾。"}], "explanations": {"来源于": "来源于表示好成绩的原因，符合语境，可以填入空格。", "超过": "语义：超过表示数量或程度的比较，与成绩和复习的因果关系不符。", "违背": "语义：违背指不遵守，与好成绩的原因相反。", "缺乏": "语义：缺乏表示不够、没有，说好成绩“缺乏”每天认真复习，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "来源于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我来源于学校走回家。", "explanation": "这里应该用〈从〉。来源于只说事物的出处，不能表示人从某处出发的动作；“从学校走回家”的起点要用从。"}, {"text": "他来源于好心帮了我。", "explanation": "这里应该用〈出于〉。来源于说事物的出处，不表示行为的动机；“出于好心”要用出于，不能用来源于。"}, {"text": "这辆汽车来源于交通工具。", "explanation": "这里应该用〈属于〉。来源于说事物的出处，不表示类别归属；“汽车属于交通工具”才是类别关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个想法来源于了一个故事。", "corrected_sentence": "这个想法来源于一个故事。", "error_description": "“来源于”是表示出处的动词，后面不能加“了”。写成“来源于了”是误用，正确形式为“来源于一个故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把灵感来源于一本旧书。", "corrected_sentence": "我的灵感来源于一本旧书。", "error_description": "“来源于”不是处置动词，不能用“把”把“灵感”提到动词前；“灵感”是主语，应用“的”连接。正确形式为“我的灵感来源于一本旧书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
