INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在数学中，分数由分子和分母组成，分子表示所取的份数。", "primary_collocate": null, "pronunciation": "fēn zǐ", "ipa": "fən˥ tsɨ˨˩", "syllable_count": 2, "sentences": [{"text": "分数五分之二的分子是二。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在分数四分之三里，分子是三。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子比分母大的分数叫假分数。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分数的分子是五，分母是八。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分母不变，分子越大，分数就越大。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把分子和分母都除以二。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分数线上面的数是分子。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子是零，这个分数就是零。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把分子写成了七，应该是九。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子和分母之间有一条横线。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分子：分数线上面的数，表示所取的份数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "正确：五分之二的分子是二，“分子”指分数线上面的数。"}, {"text": "分母", "is_correct": false, "explanation": "语义：分母是分数线下面的数，五分之二的分母是五，“分母是二”与分数的结构相反。"}, {"text": "分数", "is_correct": false, "explanation": "语义：句中已说“分数五分之二”，“分数”本身是整个数，不能指分数线上面的数。"}, {"text": "整数", "is_correct": false, "explanation": "搭配：“……的整数是二”不成立，“整数”不能作为分数中的一部分。"}], "explanations": {"分子": "正确：五分之二的分子是二，“分子”指分数线上面的数。", "分母": "语义：分母是分数线下面的数，五分之二的分母是五，“分母是二”与分数的结构相反。", "分数": "语义：句中已说“分数五分之二”，“分数”本身是整个数，不能指分数线上面的数。", "整数": "搭配：“……的整数是二”不成立，“整数”不能作为分数中的一部分。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "八分之五的分子是八。", "explanation": "这里应该用〈分母〉。八分之五的分母是八，分子是五，分子不能写成八。"}, {"text": "这个分数有一只分子。", "explanation": "这里应该用〈个〉。〈只〉不用来计量分数的组成部分，应说“一个分子”。"}, {"text": "这个分子的分数是五。", "explanation": "这里把〈分子〉当成了整体，分子只是分数线上面表示所取份数的那个数，它不代表整体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "正确：分数线上面的数就是分子。"}, {"text": "小数", "is_correct": false, "explanation": "语义：小数是带小数点的数，不指分数线上面的数，句子读起来不成立。"}, {"text": "算式", "is_correct": false, "explanation": "搭配：“分数线上面的数是”后面接的应是一个数，不能说“算式”。"}, {"text": "余数", "is_correct": false, "explanation": "语义：余数是除法中剩下的数，与分数线的位置无关，句子读起来不成立。"}], "explanations": {"分子": "正确：分数线上面的数就是分子。", "小数": "语义：小数是带小数点的数，不指分数线上面的数，句子读起来不成立。", "算式": "搭配：“分数线上面的数是”后面接的应是一个数，不能说“算式”。", "余数": "语义：余数是除法中剩下的数，与分数线的位置无关，句子读起来不成立。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分子写在分数线下面，分母写在上面。", "explanation": "分子应写在分数线上面，这里把它的位置写到了线下面，位置说反了。"}, {"text": "这个分数有一张分子。", "explanation": "这里应该用〈个〉。〈张〉用于纸张等扁平的东西，分子是表示份数的数，不用“张”计量。"}, {"text": "老师在黑板上写了一本分子。", "explanation": "这里应该用〈个〉。〈本〉用于书籍、本子，分子是一个数，不用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我分子填错了。", "corrected_sentence": "我把分子填错了。", "error_description": "处置式错误：“分子”作“填错”的受事，需用“把”引出并放在“分子”之前，省略“把”后句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师分子改成了五。", "corrected_sentence": "老师把分子改成了五。", "error_description": "处置式错误：“分子”作“改成”的受事，需用“把”引出，省略“把”后句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
