INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "黏性指物体表面具有黏附或粘连的性质，容易附着在其他物体上。", "primary_collocate": null, "pronunciation": "nián xìng", "ipa": "njɛn˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种双面胶的黏性很强，撕下来以后还能粘住别的东西。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "这种口香糖的黏性很强，容易粘在鞋底上。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "橡皮泥放久了，黏性就变差了。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "这种标签纸黏性不够，一撕就掉。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "糯米团的黏性很大，粘在手上很难洗掉。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "这块胶布的黏性很好，贴在伤口上不易脱落。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "雨天泥巴黏性大，鞋子容易沾满泥。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "这种玻璃胶黏性好，能把瓷砖牢牢粘住。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "检查胶水时，要先确认它的黏性。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}, {"text": "年糕蒸久了黏性更大，会粘在碗上。", "target_word": "黏性", "complexity_tier": "T3", "furigana": "nián xìng", "sentence_source": "generated"}], "morphological_forms": [{"form": "粘性", "label": "异形词"}], "register": "中性", "sense_fingerprint": "物体表面黏附、粘住其他东西的性质（如胶、糖、泥的粘连）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黏性", "is_correct": true, "explanation": "正确：黏性指物体表面粘住其他东西的性质，双面胶撕下后还能粘住别的东西，正是由此。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“密度”指单位体积的质量，不能用“很强”来形容双面胶。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说的是冷热，不能用“很强”来形容双面胶。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”说的是空间大小，不能用“很强”来形容双面胶。"}], "explanations": {"黏性": "正确：黏性指物体表面粘住其他东西的性质，双面胶撕下后还能粘住别的东西，正是由此。", "密度": "搭配：“密度”指单位体积的质量，不能用“很强”来形容双面胶。", "温度": "搭配：“温度”说的是冷热，不能用“很强”来形容双面胶。", "体积": "搭配：“体积”说的是空间大小，不能用“很强”来形容双面胶。"}, "sentence_index": 0, "correct_answer": "黏性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的黏性很强，一碰就碎。", "explanation": "这里应该用〈脆性〉。黏性指粘住东西的性质，形容材料一碰就碎要用脆性。"}, {"text": "这种合金的黏性很高，刀都砍不动。", "explanation": "这里应该用〈硬度〉。黏性指粘住东西的性质，形容材料抵抗切割、刀砍不动要用硬度。"}, {"text": "这件毛衣的黏性很好，冬天穿着很暖和。", "explanation": "这里应该用〈保暖性〉。黏性指物体表面粘住其他东西的性质，衣服穿着暖和要说保暖性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黏性", "is_correct": true, "explanation": "正确：黏性指物体表面粘住其他东西的性质，泥巴沾在鞋上正是由此。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：雨天的泥巴松软，硬度不会大，与“雨天”的语境相矛盾。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：泥巴不发光，“亮度大”与“雨天泥巴”的描写不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”应说“高”或“低”，不说“大”，“价格大”搭配不当。"}], "explanations": {"黏性": "正确：黏性指物体表面粘住其他东西的性质，泥巴沾在鞋上正是由此。", "硬度": "语义：雨天的泥巴松软，硬度不会大，与“雨天”的语境相矛盾。", "亮度": "语义：泥巴不发光，“亮度大”与“雨天泥巴”的描写不符。", "价格": "搭配：“价格”应说“高”或“低”，不说“大”，“价格大”搭配不当。"}, "sentence_index": 6, "correct_answer": "黏性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种橡皮的黏性很好，拉长后能很快恢复原状。", "explanation": "这里应该用〈弹性〉。黏性指粘住东西的性质，形容拉长后能恢复原状要用弹性。"}, {"text": "这块绸缎的黏性很好，看上去很亮。", "explanation": "这里应该用〈光泽〉。黏性指粘附的性质，形容布料表面发亮、有光泽要用光泽。"}, {"text": "这根绳子的黏性很好，拉不断。", "explanation": "这里应该用〈韧性〉。黏性形容粘住的能力，形容材料不易断裂要用韧性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "胶带有一张很强的黏性，粘得很牢。", "corrected_sentence": "胶带有一种很强的黏性，粘得很牢。", "error_description": "量词错误：“黏性”是抽象的性质，前面应用量词“种”，不能用“张”（“张”用于纸张、桌子等平面物品）。正确说法是“一种很强的黏性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年糕有一根很强的黏性，粘在碗上很难洗掉。", "corrected_sentence": "年糕有一种很强的黏性，粘在碗上很难洗掉。", "error_description": "量词错误：“黏性”前应用量词“种”，“根”用于细长的物体，不能用来修饰性质名词“黏性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
