INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12191, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "粗糙度指物体表面或材料的不平整、不光滑的程度，通常用于描述表面质感或加工精度。", "primary_collocate": null, "pronunciation": "cū cāo dù", "ipa": "tsʰu˥˥ tsʰaʊ˥˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "粗糙度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块金属表面的粗糙度很高。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用仪器测量零件的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粗糙度越小，表面就越光滑。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木板打磨以后，粗糙度降低了。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的粗糙度比那张大。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器零件对粗糙度有严格要求。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表面粗糙度会影响摩擦力的大小。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用砂纸调整了桌面的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验中，我们检查了每块板的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面粗糙度", "label": "复合"}], "register": "科技", "sense_fingerprint": "粗糙度：表面不平整的程度，用于描述表面质感或加工精度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bfebba-bc72-41eb-b676-3a5d37f4b25e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗糙度", "is_correct": true, "explanation": "正确：“表面粗糙度”是摩擦阻力的影响因素，符合句中的科技语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与摩擦阻力的影响因素无关，不能用于“受……影响”。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：表面不说“重量”，与“受表面……和雷诺数影响”搭配不当。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度是线性尺寸，与表面特性无关。"}], "explanations": {"粗糙度": "正确：“表面粗糙度”是摩擦阻力的影响因素，符合句中的科技语境。", "颜色": "语义：颜色与摩擦阻力的影响因素无关，不能用于“受……影响”。", "重量": "搭配：表面不说“重量”，与“受表面……和雷诺数影响”搭配不当。", "长度": "语义：长度是线性尺寸，与表面特性无关。"}, "sentence_index": 0, "correct_answer": "粗糙度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块钢板的粗糙度很高，不容易变形。", "explanation": "这里应该用〈硬度〉。粗糙度只说表面的粗细，说不容易变形要用“硬度”。"}, {"text": "这张照片的粗糙度是三十摄氏度。", "explanation": "这里应该用〈温度〉。摄氏度计量的是温度，粗糙度只描述表面的粗细。"}, {"text": "今天空气的粗糙度很高，闷得人喘不过气。", "explanation": "这里应该用〈湿度〉。空气潮湿与否要说“湿度”，粗糙度不用于描述空气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粗糙度", "is_correct": true, "explanation": "正确：机器零件的加工质量常以表面粗糙度作为严格要求，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是味觉或嗅觉的感受，不是零件的加工指标。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是人的情绪，零件没有心情，不能作为加工要求。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不是零件加工的检验指标。"}], "explanations": {"粗糙度": "正确：机器零件的加工质量常以表面粗糙度作为严格要求，符合句意。", "味道": "语义：味道是味觉或嗅觉的感受，不是零件的加工指标。", "心情": "语义：心情是人的情绪，零件没有心情，不能作为加工要求。", "气味": "语义：气味不是零件加工的检验指标。"}, "sentence_index": 6, "correct_answer": "粗糙度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的粗糙度很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”说的是颜色，粗糙度只描述表面粗细。"}, {"text": "这箱苹果的粗糙度是十公斤。", "explanation": "这里应该用〈重量〉。用公斤计量的是重量，粗糙度不能用公斤来表示。"}, {"text": "从学校到家的粗糙度很远。", "explanation": "这里应该用〈距离〉。两地远近要说“距离”，粗糙度只描述物体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木头有一只特别的粗糙度。", "corrected_sentence": "这块木头有一种特别的粗糙度。", "error_description": "错误形式：一只粗糙度；正确形式：一种粗糙度。原因：“只”用于动物或成对东西中的一个，抽象名词“粗糙度”要用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "技术员测了这块板的一只粗糙度。", "corrected_sentence": "技术员测了这块板的粗糙度。", "error_description": "错误形式：一只粗糙度；正确形式：粗糙度。原因：“只”用于动物或成对东西中的一个，抽象名词“粗糙度”不能用“只”计量，应去掉量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
