INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12192, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "雷诺数是流体力学中用来判断流体流动状态（层流或湍流）的无量纲数。", "primary_collocate": null, "pronunciation": "léi nuò shù", "ipa": "leɪ˧˥ nwɔ˥˩ ʂu˥˩", "syllable_count": 3, "sentences": [{"text": "压差阻力源于飞机前后方的压力不平衡，尤其在机身截面剧烈变化处尤为显著；摩擦阻力则来源于空气分子与飞机表面之间的黏性剪切作用，受表面粗糙度和雷诺数影响极大；而诱导阻力则是升力的副产品，由翼尖涡流引起局部下洗气流所致，其强度随升力增大而增强。", "target_word": "雷诺数", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "雷诺数可以判断水流是层流还是湍流。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管里的雷诺数越大，水流越容易变成湍流。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师先算出了管道的雷诺数。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷诺数没有单位，只是一个数。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机设计中，雷诺数是重要的数据。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速度变快以后，雷诺数也变大了。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员用流速和水深算出这条河的雷诺数。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雷诺数太小，流体就会平稳地流动。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生在课上学习了雷诺数的计算。", "target_word": "雷诺数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "临界雷诺数", "label": "复合"}], "register": "科技", "sense_fingerprint": "雷诺数：流体力学中判断层流或湍流的无量纲数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bfebba-bc72-41eb-b676-3a5d37f4b25e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雷诺数", "is_correct": true, "explanation": "正确：雷诺数是判断流动状态的无量纲数，句中说摩擦阻力“受……影响极大”，与之相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指人或动物身体的温度，与空气分子之间的黏性剪切作用无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是经济概念，不是流体力学中的物理量，不能影响摩擦阻力。"}, {"text": "产地", "is_correct": false, "explanation": "语义：产地指来源地，不是流体的影响因素，句中“受……影响”说不通。"}], "explanations": {"雷诺数": "正确：雷诺数是判断流动状态的无量纲数，句中说摩擦阻力“受……影响极大”，与之相符。", "体温": "语义：体温指人或动物身体的温度，与空气分子之间的黏性剪切作用无关。", "价格": "语义：价格是经济概念，不是流体力学中的物理量，不能影响摩擦阻力。", "产地": "语义：产地指来源地，不是流体的影响因素，句中“受……影响”说不通。"}, "sentence_index": 0, "correct_answer": "雷诺数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根管子的雷诺数有两米长。", "explanation": "这里应该用〈长度〉。雷诺数是没有单位的数，不能用“米”来说长短。"}, {"text": "这架飞机的雷诺数已经超过了声速。", "explanation": "这里应该用〈马赫数〉。马赫数是飞行速度与声速之比，可以与声速比较；雷诺数只用来判断流动状态，不能与速度比较。"}, {"text": "这根管子的雷诺数是三十摄氏度。", "explanation": "这里应该用〈温度〉。雷诺数是无量纲数，不用摄氏度计量；温度才用摄氏度表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雷诺数", "is_correct": true, "explanation": "正确：雷诺数随流速变化，句中“变快以后……也变大了”指它随速度增大而增大。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“变大”搭配，不能说颜色变大了。"}, {"text": "姓名", "is_correct": false, "explanation": "语义：姓名是人的称呼，不存在随速度变大而变大的情况，句子语义不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的心理特征，与流体速度的变化无关，不能说变大了。"}], "explanations": {"雷诺数": "正确：雷诺数随流速变化，句中“变快以后……也变大了”指它随速度增大而增大。", "颜色": "搭配：“颜色”不能与“变大”搭配，不能说颜色变大了。", "姓名": "语义：姓名是人的称呼，不存在随速度变大而变大的情况，句子语义不通。", "性格": "语义：性格是人的心理特征，与流体速度的变化无关，不能说变大了。"}, "sentence_index": 6, "correct_answer": "雷诺数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的雷诺数是每秒两米。", "explanation": "这里应该用〈流速〉。雷诺数是无量纲数，没有单位，不能用“每秒两米”这样的速度单位来表示；描述速度要用流速。"}, {"text": "管道里的雷诺数超过了一百帕。", "explanation": "这里应该用〈压强〉。压强以帕为单位，雷诺数无单位，不能拿“一百帕”与它比较大小。"}, {"text": "工程师往水箱里加了雷诺数。", "explanation": "这里应该用〈清水〉。雷诺数是一个无量纲的数字，不是能加进水箱的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们算出了这台雷诺数。", "corrected_sentence": "我们算出了这个雷诺数。", "error_description": "错误在于量词：“雷诺数”应用“个”计量，“台”多用于机器等具体物件，不能用来计量雷诺数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经算过这只雷诺数了。", "corrected_sentence": "他们已经算过这个雷诺数了。", "error_description": "错误在于目标词“雷诺数”的量词：“雷诺数”应用“个”计量，“只”用于动物或成对的东西，不能用来计量雷诺数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
