INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指气流沿物体表面向下方的流动，常见于航空术语中。", "primary_collocate": null, "pronunciation": "xià xǐ", "ipa": "ɕja˥˩ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "直升机起飞时，下洗会把地上的沙子吹起来。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员要注意前面飞机留下的下洗。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下洗太强，小飞机会很难控制。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机翼产生的下洗会让后面的飞机晃动。", "target_word": "下洗", "complexity_tier": "T3", "furigana": "xià xǐ", "sentence_source": "generated"}, {"text": "直升机的下洗让树叶一直在动。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，下洗是飞机飞行时产生的向下气流。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机离地面近时，下洗会变得更明显。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上学了下洗对飞行的影响。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下洗吹到海面上，水花四处飞。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机的下洗把桌上的纸吹走了。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "航空术语，飞机或旋翼产生的向下气流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29912ec1-1b02-4999-9515-ab237eadac0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下洗", "is_correct": true, "explanation": "正确。下洗指飞机或旋翼产生的向下气流，正是能把地上沙子吹起来的那种气流。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“会把地上的沙子吹起来”要求施力者是气流一类的事物，书包不能产生这种作用。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，与起飞时的空气运动无关，句子说的是吹沙子。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是食物，不是气流，无法在直升机起飞时把沙子吹起来。"}], "explanations": {"下洗": "正确。下洗指飞机或旋翼产生的向下气流，正是能把地上沙子吹起来的那种气流。", "书包": "搭配：“会把地上的沙子吹起来”要求施力者是气流一类的事物，书包不能产生这种作用。", "蛋糕": "语义：蛋糕是食物，与起飞时的空气运动无关，句子说的是吹沙子。", "蜂蜜": "语义：蜂蜜是食物，不是气流，无法在直升机起飞时把沙子吹起来。"}, "sentence_index": 0, "correct_answer": "下洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "热气球借助下洗飞上了天空。", "explanation": "这里应该用〈上升气流〉。下洗是向下流动的气流，不能托起热气球上升。"}, {"text": "爆炸产生的下洗把窗户震碎了。", "explanation": "这里应该用〈气浪〉。下洗专指沿物体表面向下流动的气流，爆炸的冲击波是向四周扩散的，不能用下洗。"}, {"text": "下洗让滑翔机在山谷上空慢慢升高。", "explanation": "这里应该用〈热气流〉。下洗指向下吹的气流，不能让滑翔机向上升高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下洗", "is_correct": true, "explanation": "正确。下洗是飞机附近的向下气流，飞机离地面近时它会变得更明显。"}, {"text": "日历", "is_correct": false, "explanation": "语义：日历是纸张或电子版的日期表，不是气流，无法“变得更明显”。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“变得更明显”描述可感知的现象，篮球不能作这种主语。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛花的器物，与飞机和地面的气流无关。"}], "explanations": {"下洗": "正确。下洗是飞机附近的向下气流，飞机离地面近时它会变得更明显。", "日历": "语义：日历是纸张或电子版的日期表，不是气流，无法“变得更明显”。", "篮球": "搭配：“变得更明显”描述可感知的现象，篮球不能作这种主语。", "花瓶": "语义：花瓶是盛花的器物，与飞机和地面的气流无关。"}, "sentence_index": 6, "correct_answer": "下洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湍急的下洗把石头冲走了。", "explanation": "这里应该用〈水流〉。下洗只指空气向下的流动，不用于描述水中的流动。"}, {"text": "一股下洗从北方南下，气温骤降。", "explanation": "这里应该用〈寒流〉。下洗只指局部气流沿物体表面向下流动，不能描述大范围冷空气从北方南下。"}, {"text": "下洗让风筝越飞越高。", "explanation": "这里应该用〈上升气流〉。下洗是向下流动的气流，不能把风筝托得越来越高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机翼后面有一只下洗，小飞机容易晃动。", "corrected_sentence": "机翼后面有一股下洗，小飞机容易晃动。", "error_description": "量词错误：“下洗”是气流，应说“一股下洗”；“只”用于动物或单个个体，不能用于气流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直升机掠过时，我们感到一根下洗。", "corrected_sentence": "直升机掠过时，我们感到一阵下洗。", "error_description": "量词错误：“下洗”是气流，应说“一阵下洗”；“根”用于细长的东西，不能用于气流。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
