INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "某种力量或现象的强弱程度", "primary_collocate": null, "pronunciation": "qiáng dù", "ipa": "tɕʰjɑŋ˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "台风的强度正在增加。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场雨的强度不大，不用带伞。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家在预报台风的强度。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳活动的强度每年都不一样。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山喷发的强度让人害怕。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司竞争的强度越来越高。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场冲突的强度已经降低了。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海浪的强度到了晚上变小了。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电流的强度用安培来表示。", "target_word": "强度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次暴雪的强度是十年来最大的。", "target_word": "强度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強度", "label": "繁体"}], "register": "中性", "sense_fingerprint": "台风、降雨、电流等力量或自然现象的强弱程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfa6fc4b-3b94-4372-8dfa-3cb1d7e50379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确答案：强度，qiáng dù，指力量或自然现象的强弱程度。"}, {"text": "强大", "is_correct": false, "explanation": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。"}, {"text": "强盗", "is_correct": false, "explanation": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。"}, {"text": "强固", "is_correct": false, "explanation": "gù（第四声）与 dù 声母不同（g 与 d），意思是坚固、稳固。"}], "explanations": {"强度": "正确答案：强度，qiáng dù，指力量或自然现象的强弱程度。", "强大": "dà（第四声）与 dù（第四声）韵母不同，意思是力量大。", "强盗": "dào（第四声）与 dù（第四声）韵母不同，意思是抢夺财物的人。", "强固": "gù（第四声）与 dù 声母不同（g 与 d），意思是坚固、稳固。"}, "sentence_index": null, "correct_answer": "强度"}, "level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「正在增加」说台风的强弱程度，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“增加”说数量或程度，颜色要说“变深”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：台风没有体重，句子说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：台风没有性格，句子说不通。"}], "explanations": {"强度": "正确：「正在增加」说台风的强弱程度，符合句意。", "颜色": "搭配：“增加”说数量或程度，颜色要说“变深”。", "体重": "语义：台风没有体重，句子说不通。", "性格": "语义：台风没有性格，句子说不通。"}, "sentence_index": 0, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台风的移动强度每小时五十公里。", "explanation": "这里应该用〈速度〉。强度说力量的强弱，台风移动的快慢要用速度。"}, {"text": "这间教室的强度很大，能坐下一百个人。", "explanation": "这里应该用〈面积〉。强度指力量或现象的强弱，能容纳多少人要看面积，不能用强度来说明。"}, {"text": "这台电脑的强度是八个小时，够用了。", "explanation": "这里应该用〈续航〉。强度指力量的强弱，电脑能用多久要说续航。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强度", "is_correct": true, "explanation": "正确：「已经降低了」说冲突的强弱程度，符合句意。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“降低”用于强度、水平，寿命要说“缩短”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：冲突没有身高，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：冲突没有年龄，不能说它的年龄降低。"}], "explanations": {"强度": "正确：「已经降低了」说冲突的强弱程度，符合句意。", "寿命": "搭配：“降低”用于强度、水平，寿命要说“缩短”。", "身高": "语义：冲突没有身高，句子说不通。", "年龄": "语义：冲突没有年龄，不能说它的年龄降低。"}, "sentence_index": 6, "correct_answer": "强度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次展览的强度是十年来最大的。", "explanation": "这里应该用〈规模〉。强度说力量的强弱，展览的大小要用规模。"}, {"text": "这次暴雪的强度是三天。", "explanation": "这里应该用〈持续时间〉。强度说力量的强弱，持续多久要说持续时间。"}, {"text": "车站离这里的强度很远，要走半个小时。", "explanation": "这里应该用〈距离〉。强度指力量或现象的强弱，两地之间的远近要用距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场暴风雨地强度增加了，要早点回家。", "corrected_sentence": "这场暴风雨的强度增加了，要早点回家。", "error_description": "结构助词误用：「地」接在名词「强度」前，修饰名词应用「的」，应改为「暴风雨的强度」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场风暴的很强度太大了，船都不敢出海。", "corrected_sentence": "这场风暴的强度太大了，船都不敢出海。", "error_description": "“很”是副词，只能修饰形容词，不能放在名词“强度”前，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9f4295-840f-4af1-87bc-c2967f68f7cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
