INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示跟从、顺从或任凭的意思。", "primary_collocate": null, "pronunciation": "suí", "ipa": "sweɪ˧˥", "syllable_count": 1, "sentences": [{"text": "你想吃什么就点，我都随你。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去公园还是去电影院，都随你。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师往前走，学生们随老师进了教室。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我不管，随他去吧。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不争吵，总是随大家的决定。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}, {"text": "爸爸出门，弟弟也随爸爸一起走了。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "颜色你选吧，我随你。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走进大门，我们随他进了客厅。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花多少钱，随你，我不问。", "target_word": "随", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说去哪儿，我就随她去哪儿。", "target_word": "随", "complexity_tier": "T3", "furigana": "suí", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "跟从、顺从，任凭对方决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29912ec1-1b02-4999-9515-ab237eadac0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "随", "is_correct": true, "explanation": "随（suí，第二声）：跟从、顺从的意思。"}, {"text": "岁", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是年岁。"}, {"text": "髓", "is_correct": false, "explanation": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}, {"text": "虽", "is_correct": false, "explanation": "suī（第一声）与 suí（第二声）声调不同，意思是虽然。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}], "explanations": {"随": "随（suí，第二声）：跟从、顺从的意思。", "岁": "suì（第四声）与 suí（第二声）声调不同，意思是年岁。", "髓": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。", "虽": "suī（第一声）与 suí（第二声）声调不同，意思是虽然。", "碎": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}, "sentence_index": null, "correct_answer": "随"}, "level_3": {"options": [{"text": "随", "is_correct": true, "explanation": "正确。“我都随你”表示任凭对方决定，符合前半句“你想吃什么就点”的语境。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：前句说“你想吃什么就点”，“责怪你”与这种迁就的语气相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝你”与“你想吃什么就点”的语境冲突。"}, {"text": "挡", "is_correct": false, "explanation": "搭配：“挡你”不能表示任凭对方决定，这个动词不能这样搭配。"}], "explanations": {"随": "正确。“我都随你”表示任凭对方决定，符合前半句“你想吃什么就点”的语境。", "责怪": "语义：前句说“你想吃什么就点”，“责怪你”与这种迁就的语气相反。", "拒绝": "语义：“拒绝你”与“你想吃什么就点”的语境冲突。", "挡": "搭配：“挡你”不能表示任凭对方决定，这个动词不能这样搭配。"}, "sentence_index": 0, "correct_answer": "随"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我随你借了一本书。", "explanation": "这里应该用〈向〉。“随”表示跟从、任凭，不能引出借东西的对象。"}, {"text": "她随朋友打了个电话。", "explanation": "这里应该用〈给〉。“随”不能引出打电话的对象。"}, {"text": "他随我很生气。", "explanation": "这里应该用〈对〉。“随”不能引出情绪针对的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "随", "is_correct": true, "explanation": "随（suí，第二声）：跟从、顺从的意思。"}, {"text": "碎", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。"}, {"text": "髓", "is_correct": false, "explanation": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。"}, {"text": "穗", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。"}, {"text": "隧", "is_correct": false, "explanation": "suì（第四声）与 suí（第二声）声调不同，意思是隧道。"}], "explanations": {"随": "随（suí，第二声）：跟从、顺从的意思。", "碎": "suì（第四声）与 suí（第二声）声调不同，意思是破碎。", "髓": "suǐ（第三声）与 suí（第二声）声调不同，意思是骨髓。", "穗": "suì（第四声）与 suí（第二声）声调不同，意思是谷穗。", "隧": "suì（第四声）与 suí（第二声）声调不同，意思是隧道。"}, "sentence_index": null, "correct_answer": "随"}, "level_3": {"options": [{"text": "随", "is_correct": true, "explanation": "正确。“我随你”表示听从对方的选择，与“颜色你选吧”的语境一致。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“颜色你选吧”表示交给对方决定，“反对你”与这一语境冲突。"}, {"text": "瞒", "is_correct": false, "explanation": "语义：“瞒你”表示隐瞒对方，与让对方自由选择的语境不符。"}, {"text": "怕", "is_correct": false, "explanation": "搭配：“怕你”表示畏惧对方，与“颜色你选吧，我……你”的语境不搭。"}], "explanations": {"随": "正确。“我随你”表示听从对方的选择，与“颜色你选吧”的语境一致。", "反对": "语义：“颜色你选吧”表示交给对方决定，“反对你”与这一语境冲突。", "瞒": "语义：“瞒你”表示隐瞒对方，与让对方自由选择的语境不符。", "怕": "搭配：“怕你”表示畏惧对方，与“颜色你选吧，我……你”的语境不搭。"}, "sentence_index": 6, "correct_answer": "随"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我随老师请教了一个问题。", "explanation": "这里应该用〈向〉。“随”表示跟从、任凭，不能引出请教的对象。"}, {"text": "他随妹妹买了一件礼物。", "explanation": "这里应该用〈给〉。“随”不能引出受益的对象。"}, {"text": "大家随这个计划都很满意。", "explanation": "这里应该用〈对〉。“随”不能引出评价的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_