INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加大小、数量或程度。", "primary_collocate": null, "pronunciation": "zēng dà", "ipa": "tsəŋ˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "我们要增大练习的量。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂增大了生产力度。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "增大桌子的面积，才能放下这些书。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员增大了发动机的功率。", "target_word": "增大", "complexity_tier": "T3", "furigana": "zēng dà", "sentence_source": "generated"}, {"text": "老师增大了作业的难度。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想增大音量，就按右边的键。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水箱的容量增大了一倍。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生建议不要增大药的用量。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想增大这个城市的销量。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "增大压力后，水流得更快了。", "target_word": "增大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增大了", "label": "完成体"}, {"form": "增大过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使大小、数量或程度变大（及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29912ec1-1b02-4999-9515-ab237eadac0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增大", "is_correct": true, "explanation": "增大：使练习的量变多，与「练习的量」相合，符合句意。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是地方，不能说“打扫练习的量”。"}, {"text": "扩展", "is_correct": false, "explanation": "搭配：“扩展”用于范围、领域，不说练习的量。"}, {"text": "延长", "is_correct": false, "explanation": "语义：“延长”说时间或长度的拉长，与练习的量不相合。"}], "explanations": {"增大": "增大：使练习的量变多，与「练习的量」相合，符合句意。", "打扫": "搭配：“打扫”的对象是地方，不能说“打扫练习的量”。", "扩展": "搭配：“扩展”用于范围、领域，不说练习的量。", "延长": "语义：“延长”说时间或长度的拉长，与练习的量不相合。"}, "sentence_index": 0, "correct_answer": "增大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂增大了产品的质量。", "explanation": "这里应该用〈提高〉。质量、水平的上升用提高，增大只说大小、数量或程度的变大。"}, {"text": "他增大了身体的抵抗力。", "explanation": "这里应该用〈增强〉。抵抗力、能力等抽象的强弱用增强，增大不用于能力。"}, {"text": "节日增大了热闹的气氛。", "explanation": "这里应该用〈增添〉。气氛、乐趣等要用增添，增大只用于具体事物的变大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增大", "is_correct": true, "explanation": "增大：使容量变大一倍，与「把…容量」和「一倍」相合。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：容量不能清洗，也不能按倍数清洗。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”不能以容量为对象，也不接“一倍”。"}, {"text": "移动", "is_correct": false, "explanation": "语义：容量是抽象数量，不能移动。"}], "explanations": {"增大": "增大：使容量变大一倍，与「把…容量」和「一倍」相合。", "清洗": "语义：容量不能清洗，也不能按倍数清洗。", "打开": "搭配：“打开”不能以容量为对象，也不接“一倍”。", "移动": "语义：容量是抽象数量，不能移动。"}, "sentence_index": 6, "correct_answer": "增大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校增大了一个新的专业。", "explanation": "这里应该用〈增设〉。新设立的专业要用增设，增大只说原有事物的变大。"}, {"text": "这次事故增大了他的伤势。", "explanation": "这里应该用〈加重〉。伤势、病情的加重要用加重，增大只说大小的变大。"}, {"text": "这几年，他的职位增大很快。", "explanation": "这里应该用〈提升〉。职位的上升用提升，增大不用于职位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次试验把温度增大了到八十度。", "corrected_sentence": "这次试验把温度增大到了八十度。", "error_description": "错误：“了”放在了补语“到”之前。正确：“增大到了八十度”。表示结果的补语“到”要紧跟“增大”，“了”放在“到”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂去年把产量增大得三成。", "corrected_sentence": "工厂去年把产量增大了三成。", "error_description": "错误：补语标记“得”用错。正确：“增大了三成”。“得”后接形容词或程度短语，表示增加的幅度要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
