INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指利用飞机等航空器在空中飞行的活动，也指与之相关的行业。", "primary_collocate": null, "pronunciation": "háng kōng", "ipa": "/xɑŋ˧˥ kʰʊŋ˥/", "syllable_count": 2, "sentences": [{"text": "他在航空领域工作了十年。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空安全对每位乘客都很重要。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代航空技术发展得非常快。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了中国航空的历史。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空知识能帮我们了解飞机怎么飞。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多航空方面的展品。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢航空，想当飞行员。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航空运输比火车运输快得多。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里新开了一门航空课程。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次航空表演吸引了很多游客。", "target_word": "航空", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "航空公司", "label": "复合词"}, {"form": "航空母舰", "label": "复合词"}, {"form": "航空邮件", "label": "复合词"}], "register": "中性", "sense_fingerprint": "航空|名词|航空器在空中飞行的活动或相关行业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29912ec1-1b02-4999-9515-ab237eadac0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "航空", "is_correct": true, "explanation": "航空指飞行活动或相关行业，可以修饰“领域”，“航空领域”是常见说法。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋是物品，不是可以工作的领域，“在……领域工作”不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“领域”指学科或行业，不能用具体家电来修饰。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语说法，指谋生的职业，与书面语“领域”不搭配，也不指工作的领域。"}], "explanations": {"航空": "航空指飞行活动或相关行业，可以修饰“领域”，“航空领域”是常见说法。", "皮鞋": "语义：皮鞋是物品，不是可以工作的领域，“在……领域工作”不成立。", "冰箱": "搭配：“领域”指学科或行业，不能用具体家电来修饰。", "饭碗": "语域：“饭碗”是口语说法，指谋生的职业，与书面语“领域”不搭配，也不指工作的领域。"}, "sentence_index": 0, "correct_answer": "航空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这架航空真大，能坐三百人。", "explanation": "这里应该用〈飞机〉。航空指飞行这件事或这一行业，不是可以用“架”计数、能载人的实物。"}, {"text": "我们这次航空玩了三天，很开心。", "explanation": "这里应该用〈旅行〉。“旅行”指出去玩的整个过程，可以说“玩了三天”；航空只指在空中飞行，不能指一次出游。"}, {"text": "宇宙飞船要进行一次航空，前往月球。", "explanation": "这里应该用〈航天〉。前往月球属于太空飞行，航空指大气层中的飞行，不包括太空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "航空", "is_correct": true, "explanation": "“从小就喜欢航空”指对飞行行业或活动感兴趣，与“想当飞行员”前后一致。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“喜欢厨房”与后面“想当飞行员”的志向毫无关联，前后不一致。"}, {"text": "江湖", "is_correct": false, "explanation": "语域：“江湖”带文学色彩，与口语叙述“从小就喜欢”不协调，也不指常见的爱好对象。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是地点，与“想当飞行员”的志向毫无关联，句子不成立。"}], "explanations": {"航空": "“从小就喜欢航空”指对飞行行业或活动感兴趣，与“想当飞行员”前后一致。", "厨房": "语义：“喜欢厨房”与后面“想当飞行员”的志向毫无关联，前后不一致。", "江湖": "语域：“江湖”带文学色彩，与口语叙述“从小就喜欢”不协调，也不指常见的爱好对象。", "菜市场": "语义：菜市场是地点，与“想当飞行员”的志向毫无关联，句子不成立。"}, "sentence_index": 6, "correct_answer": "航空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的航空晚点了三个小时。", "explanation": "这里应该用〈航班〉。航班是具体的一趟飞行，可以晚点；航空是抽象的飞行活动或行业，不能晚点。"}, {"text": "我在网上订了航空，明天去北京。", "explanation": "这里应该用〈机票〉。预订的是机票，航空不是可以订的凭证。"}, {"text": "这个航空很大，每天有很多航班。", "explanation": "这里应该用〈机场〉。机场是场所，可以很大、有很多航班；航空不指场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想去航空的公司工作。", "corrected_sentence": "我想去航空公司工作。", "error_description": "错误：“航空的公司”；正确：“航空公司”。“航空”修饰“公司”时直接连用，复合词之间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现在很多年轻人想学航空公司。", "corrected_sentence": "现在很多年轻人想学航空专业。", "error_description": "错误：“学航空公司”；正确：“学航空专业”。“学”的对象是专业或知识，“公司”是企业，不能用来学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物（特别是分子）中各个部分的排列方式或结构形式。", "primary_collocate": null, "pronunciation": "gòu xíng", "ipa": "kou˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "为了实现高效巡航，航空工程师必须在气动构型上进行精细权衡，以最大化升阻比——即单位阻力下所能产生的升力，这是衡量飞行效率的关键指标。", "target_word": "构型", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种分子的构型很特别。", "target_word": "构型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水分子的构型是弯曲的。", "target_word": "构型", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "化学家正在研究这个分子的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改变构型以后，药的性质也变了。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画出了分子构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两种药的构型不同，作用也不同。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用仪器测定了蛋白质的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个化合物有两种不同的构型。", "target_word": "构型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果构型变了，它的功能就会改变。", "target_word": "构型", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种构型", "label": "量词"}, {"form": "分子构型", "label": "复合"}, {"form": "气动构型", "label": "复合"}, {"form": "構型", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "分子或结构中各部分的排列方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b5a66e-7b75-47f7-a8ec-a1433fb6fbd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：听到的是“构型”（gòu xíng），指分子等物体各部分的排列方式。"}, {"text": "钩形", "is_correct": false, "explanation": "gōu（第一声）与 gòu（第四声）声调不同，钩形指像钩子的形状。"}, {"text": "厚型", "is_correct": false, "explanation": "hòu 与 gòu 声母不同（h 与 g），厚型指厚的类型。"}, {"text": "各型", "is_correct": false, "explanation": "gè 与 gòu 韵母不同（e 与 ou），各型指各种类型。"}, {"text": "豆形", "is_correct": false, "explanation": "dòu 与 gòu 声母不同（d 与 g），豆形指像豆子的形状。"}], "explanations": {"构型": "正确：听到的是“构型”（gòu xíng），指分子等物体各部分的排列方式。", "钩形": "gōu（第一声）与 gòu（第四声）声调不同，钩形指像钩子的形状。", "厚型": "hòu 与 gòu 声母不同（h 与 g），厚型指厚的类型。", "各型": "gè 与 gòu 韵母不同（e 与 ou），各型指各种类型。", "豆形": "dòu 与 gòu 声母不同（d 与 g），豆形指像豆子的形状。"}, "sentence_index": null, "correct_answer": "构型"}, "level_3": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：“气动构型”指飞行器的外形布局，与“精细权衡”“升阻比”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与气动布局、升阻比无关，句子不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：升阻比是空气动力指标，不能拿价格去权衡。"}, {"text": "燃料", "is_correct": false, "explanation": "搭配：“气动”修饰外形与布局，不修饰燃料，不说“气动燃料”。"}], "explanations": {"构型": "正确：“气动构型”指飞行器的外形布局，与“精细权衡”“升阻比”的语境相符。", "颜色": "语义：颜色与气动布局、升阻比无关，句子不成立。", "价格": "语义：升阻比是空气动力指标，不能拿价格去权衡。", "燃料": "搭配：“气动”修饰外形与布局，不修饰燃料，不说“气动燃料”。"}, "sentence_index": 0, "correct_answer": "构型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的构型很稳定。", "explanation": "这里应该用〈结构〉。构型指分子或物体中各部分的具体排列，国家这类抽象组织的组成方式要用结构。"}, {"text": "这部小说的构型很巧妙。", "explanation": "这里应该用〈构思〉。构型指具体物体的排列形式，小说的情节安排要用构思。"}, {"text": "今年的构型很突出。", "explanation": "这里应该用〈特点〉。构型指事物内部各部分的排列结构，年份不具备这种结构，要说特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "构型", "is_correct": true, "explanation": "正确：“构型不同”说明两种药的分子排列不同，与“作用也不同”相呼应。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：药物没有年龄，“年龄不同”不能用于两种药。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：药物没有脾气，“脾气不同”在这里不成立。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指人或动物的外貌，不能用于药物。"}], "explanations": {"构型": "正确：“构型不同”说明两种药的分子排列不同，与“作用也不同”相呼应。", "年龄": "语义：药物没有年龄，“年龄不同”不能用于两种药。", "脾气": "语义：药物没有脾气，“脾气不同”在这里不成立。", "容貌": "体貌：“容貌”指人或动物的外貌，不能用于药物。"}, "sentence_index": 6, "correct_answer": "构型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的构型很清楚，大家都听懂了。", "explanation": "这里应该用〈论证〉。构型指物体的排列结构，不能用来评价人的论证是否清楚。"}, {"text": "这个运动员的构型很有名。", "explanation": "这里应该用〈名气〉。构型指物体的排列结构，人的名声不能用构型，要说名气。"}, {"text": "这次比赛的构型很紧张。", "explanation": "这里应该用〈形势〉。构型指事物各部分的排列结构，比赛的局面状况要用形势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个药物有一只稳定的构型。", "corrected_sentence": "这个药物有一种稳定的构型。", "error_description": "量词错误：“构型”前应用量词“种”，“只”用于动物或个体物件，不能用于构型。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种药有一条新的构型。", "corrected_sentence": "这种药有一种新的构型。", "error_description": "量词错误：“构型”前应用量词“种”，“条”用于细长的东西，不能用于构型。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
