INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个人能力范围内能够做到的最大限度；常用于‘尽自己所能’等固定搭配。", "primary_collocate": null, "pronunciation": "suǒ néng", "ipa": "swo˨˩˦ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我会尽自己所能帮助你。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尽自己所能照顾老人。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都尽自己所能去帮忙。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师尽其所能教好每个学生。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要尽我们所能保护环境。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她尽自己所能完成了工作。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生尽他所能救那个孩子。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了家人，他总是尽自己所能。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你尽你所能，把事情做好。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈尽她所能给孩子最好的。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己能力范围内能做到的最大限度，多用于尽……所能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所能", "is_correct": true, "explanation": "正确：所能指自己能力范围内能做到的最大限度，与“尽自己”搭配。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的物件，不是能力范围，不能与“尽”构成这一意义。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向指朝向或目标，不指能力所能达到的程度。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“尽”一般接“力”“能”等表示能力的词，不接“时间”。"}], "explanations": {"所能": "正确：所能指自己能力范围内能做到的最大限度，与“尽自己”搭配。", "钱包": "语义：钱包是装钱的物件，不是能力范围，不能与“尽”构成这一意义。", "方向": "语义：方向指朝向或目标，不指能力所能达到的程度。", "时间": "搭配：“尽”一般接“力”“能”等表示能力的词，不接“时间”。"}, "sentence_index": 0, "correct_answer": "所能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的所能很强。", "explanation": "这里应该用〈能力〉。所能只用于“尽……所能”等说法，指能力所及的最大限度，不用来形容人的能力强弱。"}, {"text": "他下定了所能，要把书读完。", "explanation": "这里应该用〈决心〉。所能指能力所及的最大限度，不能表示意志和决心。"}, {"text": "他的汉语所能很高。", "explanation": "这里应该用〈水平〉。所能指在某事上能做到的最大限度，不能用来说明语言水平的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所能", "is_correct": true, "explanation": "正确：尽他所能，即尽他能力范围内的最大限度去救人。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装物品的袋子，不是能力范围，不能与“尽”构成这一意义。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不指能力所能达到的程度。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“尽”不与“体温”搭配，不能说“尽他体温”。"}], "explanations": {"所能": "正确：尽他所能，即尽他能力范围内的最大限度去救人。", "书包": "语义：书包是装物品的袋子，不是能力范围，不能与“尽”构成这一意义。", "钥匙": "语义：钥匙是开锁的工具，不指能力所能达到的程度。", "体温": "搭配：“尽”不与“体温”搭配，不能说“尽他体温”。"}, "sentence_index": 6, "correct_answer": "所能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的所能很好。", "explanation": "这里应该用〈天气〉。所能指能力所及的最大限度，不能用来描述天气的好坏。"}, {"text": "她的所能很好听。", "explanation": "这里应该用〈声音〉。所能不用来形容声音好听与否，只指能力所及的最大限度。"}, {"text": "这幅画的所能很鲜艳。", "explanation": "这里应该用〈颜色〉。所能不能用来描述事物的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她决定自己所能去学习。", "corrected_sentence": "她决定尽自己所能去学习。", "error_description": "“所能”前应加“尽”，构成“尽……所能”；这里漏了“尽”，应为“尽自己所能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她自己所能陪伴家人。", "corrected_sentence": "她尽自己所能陪伴家人。", "error_description": "错误：漏了“尽”。“尽……所能”是固定说法，应说“尽自己所能”，不能只说“自己所能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
