INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比较、评定事物的大小、多少、轻重、长短、高低等。", "primary_collocate": null, "pronunciation": "héng liáng", "ipa": "xɤŋ³⁵ ljɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "我们常用分数来衡量学生的学习水平。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该用什么标准来衡量一个人是否成功？", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只用钱来衡量一个人的价值。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用考试成绩来衡量学生的进步。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衡量一家餐厅好不好，要看菜的味道。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在衡量这两份工作哪一个更适合自己。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先衡量一下自己的能力，再答应他。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衡量一座城市是否发达，不能只看楼有多高。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用销售额衡量每个员工的工作成绩。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把得失都衡量过了，才做出这个决定。", "target_word": "衡量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衡量了", "label": "完成体"}, {"form": "衡量过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "用标准评定事物的价值或好坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衡量", "is_correct": true, "explanation": "正确。衡量指用一定标准评定高低，与“用分数来……学生的学习水平”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等场所，不能打扫学习水平。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能用分数煮学习水平。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等具体东西，不能洗学习水平。"}], "explanations": {"衡量": "正确。衡量指用一定标准评定高低，与“用分数来……学生的学习水平”相符。", "打扫": "搭配：“打扫”的对象是房间、地面等场所，不能打扫学习水平。", "煮": "搭配：“煮”的对象是食物，不能用分数煮学习水平。", "洗": "搭配：“洗”的对象是衣物、身体等具体东西，不能洗学习水平。"}, "sentence_index": 0, "correct_answer": "衡量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我衡量今天会下雨。", "explanation": "这里应该用〈估计〉。衡量是依据标准比较、评定已有事物，对未来会不会发生的推测要说估计。"}, {"text": "他一眼就衡量出那是他的朋友。", "explanation": "这里应该用〈辨认〉。衡量是比较、评定事物的大小、多少等，认出某人是谁要说辨认。"}, {"text": "他衡量了三加五的结果。", "explanation": "这里应该用〈计算〉。衡量是比较评定事物的数量或价值，求算术结果要说计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衡量", "is_correct": true, "explanation": "正确。衡量指先比较评定，与“你要先衡量一下自己的能力，再答应他”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是场所或物品，不能打扫能力。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语是食物，不能接“能力”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”多接机器、房屋等具体物件，不能接“能力”。"}], "explanations": {"衡量": "正确。衡量指先比较评定，与“你要先衡量一下自己的能力，再答应他”相符。", "打扫": "语义：“打扫”的对象是场所或物品，不能打扫能力。", "吃掉": "搭配：“吃掉”的宾语是食物，不能接“能力”。", "修理": "搭配：“修理”多接机器、房屋等具体物件，不能接“能力”。"}, "sentence_index": 6, "correct_answer": "衡量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他衡量出了一阵笑声。", "explanation": "这里应该用〈发出〉。衡量是依标准比较、评定事物，笑声是发出的，应说发出。"}, {"text": "他一脚衡量了那个球，然后射进了球门。", "explanation": "这里应该用〈踢〉。衡量是比较、评定事物的大小等，用脚击打球要说踢。"}, {"text": "他把那一大片草原衡量成了一首诗。", "explanation": "这里应该用〈写〉。衡量是比较、评定事物，把景物写成诗要说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他衡量了出两种方案的差别。", "corrected_sentence": "他衡量出了两种方案的差别。", "error_description": "“出”是结果补语，应紧跟动词“衡量”，写作“衡量出了”，不能放在“了”的后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在衡量了这些方案。", "corrected_sentence": "他正在衡量这些方案。", "error_description": "“正在”表示动作正在进行，不能与完成体“了”同用，应去掉“了”，写作“他正在衡量这些方案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
