INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体所受重力的大小，也指物体含有物质的多少。", "primary_collocate": null, "pronunciation": "zhòng liàng", "ipa": "tʂʊŋ˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个箱子的重量是十公斤。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机行李的重量不能超过二十公斤。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先称一下这个包的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的重量比那辆小很多。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥不能承受太大的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书包放在秤上，看了看重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块石头的重量大约有五斤。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递按重量收费，越重越贵。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机很轻，重量只有一百五十克。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们测量一下小球的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重量级", "label": "复合"}, {"form": "总重量", "label": "复合"}], "register": "中性", "sense_fingerprint": "物理义：物体的轻重，可用公斤、克等单位计量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重量", "is_correct": true, "explanation": "“重量”指物体的轻重，可以用公斤计量，与“是十公斤”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱数，不能用公斤计量。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：体积用立方单位计量，不能与“公斤”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有公斤数，“颜色是十公斤”不成立。"}], "explanations": {"重量": "“重量”指物体的轻重，可以用公斤计量，与“是十公斤”相符。", "价格": "语义：价格是钱数，不能用公斤计量。", "体积": "搭配：体积用立方单位计量，不能与“公斤”搭配。", "颜色": "语义：颜色没有公斤数，“颜色是十公斤”不成立。"}, "sentence_index": 0, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的重量是五公里。", "explanation": "这里应该用〈长度〉。“重量”指物体受重力的大小和所含物质的多少，不用来说长短；说路有多长要用〈长度〉。"}, {"text": "这个箱子的重量很好，用了三年都没坏。", "explanation": "这里应该用〈质量〉。“重量”指轻重，不用来说东西的好坏。"}, {"text": "这台电脑的重量很便宜，我花了三百块买的。", "explanation": "这里应该用〈价格〉。“重量”不指价钱，说价钱高低要用〈价格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": true, "explanation": "“重量大约有五斤”说石头的轻重，与“斤”相符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度指长短，不用斤计量。"}, {"text": "价值", "is_correct": false, "explanation": "搭配：“价值”不用斤衡量，与“大约有五斤”不搭配。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：硬度指材料坚硬的程度，不是按斤计的数量。"}], "explanations": {"重量": "“重量大约有五斤”说石头的轻重，与“斤”相符。", "长度": "语义：长度指长短，不用斤计量。", "价值": "搭配：“价值”不用斤衡量，与“大约有五斤”不搭配。", "硬度": "语义：硬度指材料坚硬的程度，不是按斤计的数量。"}, "sentence_index": 6, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的重量是五十个。", "explanation": "这里应该用〈数量〉。“重量”用公斤、斤计量，不用个数；说数目多少要用〈数量〉。"}, {"text": "这个箱子的重量是三立方米。", "explanation": "这里应该用〈体积〉。“重量”用公斤计，立方米是体积单位。"}, {"text": "这座楼的重量是一百米。", "explanation": "这里应该用〈高度〉。“重量”以公斤、斤计，米是长度单位，说楼的高矮要用〈高度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个包的重量是五个。", "corrected_sentence": "这个包的重量是五斤。", "error_description": "量词错误：重量的单位应用“斤”，不能用“个”（“个”用于可数事物）。应说“重量是五斤”，不能说“重量是五个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批水果跟重量卖。", "corrected_sentence": "这批水果按重量卖。", "error_description": "错误：“跟重量卖”，正确：“按重量卖”。表示计价依据要用“按”，“跟”不能引出这样的依据。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
