INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "材料因反复受力而逐渐损坏的特性", "primary_collocate": null, "pronunciation": "pí láo", "ipa": "pʰi˧˥ lɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "金属反复受力后会产生疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥梁钢材的疲劳会让桥慢慢损坏。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师担心机翼材料会因长期受力而产生疲劳。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反复弯折铁丝，铁丝会出现疲劳，最后断开。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料疲劳是机器出故障的常见原因。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车轮子长期受力，金属会产生疲劳。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属疲劳让这座旧桥变得不安全。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验显示，塑料也会发生疲劳。", "target_word": "疲劳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢轨每天受压，疲劳会慢慢积累。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止金属疲劳，工厂换了新零件。", "target_word": "疲劳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "疲勞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "材料反复受力后逐渐损坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c05f1681-2c75-46d9-9afe-d9f49a74d5c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12218, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。疲劳指材料因反复受力而逐渐损坏。"}, {"text": "皮毛", "is_correct": false, "explanation": "máo（第二声）与 láo（第二声）声母不同（m 与 l），意思是皮毛，不是材料损坏。"}, {"text": "皮薄", "is_correct": false, "explanation": "báo（第二声）与 láo 声母不同（b 与 l），意思是皮很薄，不是材料损坏。"}, {"text": "皮袍", "is_correct": false, "explanation": "páo（第二声）与 láo 声母不同（p 与 l），意思是毛皮做的长衣，不是材料损坏。"}], "explanations": {"疲劳": "正确答案。疲劳指材料因反复受力而逐渐损坏。", "皮毛": "máo（第二声）与 láo（第二声）声母不同（m 与 l），意思是皮毛，不是材料损坏。", "皮薄": "báo（第二声）与 láo 声母不同（b 与 l），意思是皮很薄，不是材料损坏。", "皮袍": "páo（第二声）与 láo 声母不同（p 与 l），意思是毛皮做的长衣，不是材料损坏。"}, "sentence_index": null, "correct_answer": "疲劳"}, "level_3": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。“产生疲劳”指金属受力反复后逐渐损坏，与句意相符。"}, {"text": "信心", "is_correct": false, "explanation": "语义：金属不会产生信心，“产生信心”只用于人，与金属受力无关。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：金属受力不会发出笑声，“产生笑声”与句子的物理过程矛盾。"}, {"text": "愁绪", "is_correct": false, "explanation": "语域：“愁绪”是文学性用语，描写人的情感，与金属受力的工程语境不协调。"}], "explanations": {"疲劳": "正确答案。“产生疲劳”指金属受力反复后逐渐损坏，与句意相符。", "信心": "语义：金属不会产生信心，“产生信心”只用于人，与金属受力无关。", "笑声": "语义：金属受力不会发出笑声，“产生笑声”与句子的物理过程矛盾。", "愁绪": "语域：“愁绪”是文学性用语，描写人的情感，与金属受力的工程语境不协调。"}, "sentence_index": 0, "correct_answer": "疲劳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根铁管一直闲置在仓库里，几年后就疲劳了。", "explanation": "这里应该用〈老化〉。疲劳指受力反复造成的损坏，闲置不受力而变旧要说老化。"}, {"text": "强酸会让这块金属疲劳。", "explanation": "这里应该用〈腐蚀〉。疲劳指受力反复造成的损坏，化学药品造成的损坏要用腐蚀。"}, {"text": "这块钢板被重物一压就疲劳了。", "explanation": "这里应该用〈变形〉。疲劳指材料反复受力后逐渐损坏，一次受压就弯了要说变形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疲劳", "is_correct": true, "explanation": "正确答案。“金属疲劳”指金属受力反复后的损坏，是这座旧桥不安全的原因。"}, {"text": "光泽", "is_correct": false, "explanation": "语义：金属的光泽与桥的安全无关，“金属光泽让桥不安全”句意不通。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”指愉快的感受，不会让桥变得不安全。"}, {"text": "哲思", "is_correct": false, "explanation": "语域：“哲思”是文学或哲学用语，与工程语境不协调，且句意不通。"}], "explanations": {"疲劳": "正确答案。“金属疲劳”指金属受力反复后的损坏，是这座旧桥不安全的原因。", "光泽": "语义：金属的光泽与桥的安全无关，“金属光泽让桥不安全”句意不通。", "乐趣": "语义：“乐趣”指愉快的感受，不会让桥变得不安全。", "哲思": "语域：“哲思”是文学或哲学用语，与工程语境不协调，且句意不通。"}, "sentence_index": 6, "correct_answer": "疲劳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块金属擦过以后，变得很疲劳。", "explanation": "这里应该用〈发亮〉。疲劳指受力反复造成的损坏，表面擦亮后变亮要说发亮。"}, {"text": "这块金属在炉子里加热一次，就疲劳了。", "explanation": "这里应该用〈软化〉。疲劳指反复受力造成的损坏，只加热一次使金属变软要说软化。"}, {"text": "木板在太阳下晒干以后，就会疲劳。", "explanation": "这里应该用〈开裂〉。疲劳指受力反复造成的损坏，干燥后表面裂开要说开裂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种零件长期受力后会产生一个疲劳，最终断裂。", "corrected_sentence": "这种零件长期受力后会产生疲劳，最终断裂。", "error_description": "错误：抽象的“疲劳”前误加了个体量词“个”。正确：“会产生疲劳”，材料受力后的损坏不加个体量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "钢梁在车流的长期冲击下，内部会产生很疲劳，逐渐失去承载能力。", "corrected_sentence": "钢梁在车流的长期冲击下，内部会产生疲劳，逐渐失去承载能力。", "error_description": "错误：名词“疲劳”前误加了程度副词“很”。正确：“会产生疲劳”，这里“疲劳”是名词，前面不能用“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '913854c3-1e65-4da4-827f-7e6bd796f1d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
