INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指物体或系统在长时间使用后仍能保持其原有功能和性能的能力。", "primary_collocate": null, "pronunciation": "nài jiǔ xìng", "ipa": "nai˥˩ tɕjoʊ˨˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "耐久性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种材料的耐久性很好。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测试桥的耐久性。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电池的耐久性越来越高。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选地板时，我们很看重耐久性。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的耐久性比旧的强。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验证明，这种塑料有很好的耐久性。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了提高耐久性，工厂换了新零件。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车的耐久性要经过多年的路试。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耐久性不好的产品，用不了多久就坏了。", "target_word": "耐久性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "物体或系统长期使用后保持功能和性能的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b5a66e-7b75-47f7-a8ec-a1433fb6fbd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“增强了疲劳颜色”说不通，疲劳指材料反复受力后的状态，与颜色无关。"}, {"text": "耐久性", "is_correct": true, "explanation": "正确：耐久性指长期使用后保持功能的能力，与“疲劳”“增强”搭配自然。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“增强”可以搭配强度、耐久性，不能搭配价格。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是能因疲劳而增强的性质，句意不通。"}], "explanations": {"颜色": "语义：“增强了疲劳颜色”说不通，疲劳指材料反复受力后的状态，与颜色无关。", "耐久性": "正确：耐久性指长期使用后保持功能的能力，与“疲劳”“增强”搭配自然。", "价格": "搭配：“增强”可以搭配强度、耐久性，不能搭配价格。", "温度": "语义：温度不是能因疲劳而增强的性质，句意不通。"}, "sentence_index": 0, "correct_answer": "耐久性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个灯泡的耐久性很亮。", "explanation": "这里应该用〈亮度〉，说“亮度很高”。灯泡的明暗要说亮度；耐久性指长期使用中保持性能的能力，不能用来形容明暗。"}, {"text": "他的耐久性很好，跑完了全程马拉松。", "explanation": "耐久性只用于物体或系统，不用于人；人的持久力要说耐力，这里用“耐久性”指人是错的。"}, {"text": "这个水箱的耐久性是五十升。", "explanation": "这里应该用〈容量〉。五十升是体积，能装多少是容量；耐久性表示长期使用不坏，不能表示体积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在的时间，不能用来形容塑料的好坏，“很好的年龄”不通。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人或动物的性情，不能用来形容塑料。"}, {"text": "耐久性", "is_correct": true, "explanation": "正确：“很好的耐久性”指塑料能长期使用不坏，与“实验证明”的测试语境一致。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”指人说话的腔调，塑料没有口音，“很好的口音”放在这里不成立。"}], "explanations": {"年龄": "语义：“年龄”指存在的时间，不能用来形容塑料的好坏，“很好的年龄”不通。", "脾气": "语义：“脾气”指人或动物的性情，不能用来形容塑料。", "耐久性": "正确：“很好的耐久性”指塑料能长期使用不坏，与“实验证明”的测试语境一致。", "口音": "语义：“口音”指人说话的腔调，塑料没有口音，“很好的口音”放在这里不成立。"}, "sentence_index": 6, "correct_answer": "耐久性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的耐久性足以承受十级地震的冲击。", "explanation": "这里应该用〈强度〉。承受瞬间冲击的能力是强度；耐久性指长期使用中保持性能，不指一次性承受外力。"}, {"text": "这家工厂每天都在生产耐久性。", "explanation": "耐久性是产品的性能，不是可以生产出来的东西，应说“生产产品”或“提高产品的耐久性”。"}, {"text": "这辆汽车的耐久性比那辆快三秒。", "explanation": "这里应该用〈加速性能〉。快三秒说的是加速快慢；耐久性指长期使用中保持性能，不能用来比较快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种材料有一只很好的耐久性。", "corrected_sentence": "这种材料有很好的耐久性。", "error_description": "量词错误：错误形式为“一只”，正确形式为不加量词。耐久性是抽象的性质，“有很好的耐久性”不用个体量词；“只”用于动物或单个的物品，不能修饰耐久性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款玻璃的耐久性很多。", "corrected_sentence": "这款玻璃的耐久性很高。", "error_description": "搭配错误：错误形式为“很多”，正确形式为“很高”。耐久性是抽象的性质，程度用“高”表示；“很多”用于可数的事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指设备、机器或系统在实际运行或工作过程中所处的状态、条件及其表现。", "primary_collocate": null, "pronunciation": "gōng kuàng", "ipa": "kʊŋ⁵⁵ kʰwɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "工况", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器在不同工况下，声音也不一样。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查发动机的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高温工况下，机器很容易坏。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台水泵的工况很好，可以继续用。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先了解设备的工况，再决定怎么修。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑屏幕上显示着机器现在的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车在不同工况下的油耗差别很大。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天都记录机器的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的风机在各种工况下都很安静。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工況", "label": "繁体"}, {"form": "设计工况", "label": "复合"}, {"form": "额定工况", "label": "复合"}], "register": "专业", "sense_fingerprint": "工况：设备在实际运行中所处的状态、条件及其表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工况", "is_correct": true, "explanation": "正确：工况指设备的运行状态和条件，与“极端……下的气动性能”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“极端颜色下的气动性能”不通，颜色与气动性能无关。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不能作为模拟的条件，与“模拟……下的气动性能”冲突。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“极端”修饰条件、环境，不修饰价格，与“下的气动性能”不搭配。"}], "explanations": {"工况": "正确：工况指设备的运行状态和条件，与“极端……下的气动性能”相符。", "颜色": "语义：“极端颜色下的气动性能”不通，颜色与气动性能无关。", "人口": "语义：人口不能作为模拟的条件，与“模拟……下的气动性能”冲突。", "价格": "搭配：“极端”修饰条件、环境，不修饰价格，与“下的气动性能”不搭配。"}, "sentence_index": 0, "correct_answer": "工况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近的学习工况很好，成绩一直在提高。", "explanation": "这里应该用〈状况〉。“工况”只指机器、设备的运行状态，人的学习情况要用“状况”。"}, {"text": "他家的经济工况在这几年变好了。", "explanation": "这里应该用〈情况〉。“工况”只指设备运行状态，家庭经济情况要用“情况”。"}, {"text": "这部电影的工况很好，很多人去看。", "explanation": "这里应该用〈票房〉。“工况”指设备的运行状态，电影的卖座情况要用“票房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工况", "is_correct": true, "explanation": "正确：工况指机器现在的运行状态，屏幕上显示的正是这一状态。"}, {"text": "味道", "is_correct": false, "explanation": "语义：机器没有可以被屏幕显示的味道，与显示的运行数据不符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指出生日期，不能用来表示机器当前的运行状态。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：“显示着……的”后接状态或数值，“作者”不能与之搭配。"}], "explanations": {"工况": "正确：工况指机器现在的运行状态，屏幕上显示的正是这一状态。", "味道": "语义：机器没有可以被屏幕显示的味道，与显示的运行数据不符。", "生日": "语义：“生日”指出生日期，不能用来表示机器当前的运行状态。", "作者": "搭配：“显示着……的”后接状态或数值，“作者”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "工况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近股市的工况很好，很多股票都在涨。", "explanation": "这里应该用〈行情〉。“工况”指设备运行状态，股市走势要用“行情”。"}, {"text": "现场的工况很热烈，大家都在唱歌。", "explanation": "这里应该用〈气氛〉。“工况”不能用来形容人群的情绪和现场氛围。"}, {"text": "病人的工况很稳定，医生说可以出院。", "explanation": "这里应该用〈病情〉。“工况”只用于设备，病人的病情要用“病情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机器在一只高温工况下运行。", "corrected_sentence": "机器在一种高温工况下运行。", "error_description": "错误：“一只”。正确：“一种”。“工况”是抽象名词，“只”用于有个体的具体事物，应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台设备有很好工况。", "corrected_sentence": "这台设备有很好的工况。", "error_description": "错误：“很好工况”，漏了“的”。正确：“很好的工况”。“很好”作定语修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不断重复进行更新或改进的过程，用于描述技术、概念或方法的版本升级。", "primary_collocate": null, "pronunciation": "dié dài", "ipa": "tjɛ˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "此后四十年间，材料科学的迭代推动光伏技术进入指数级进化：多结叠层电池突破光谱响应极限，钙钛矿材料以其低廉成本与柔性特质颠覆传统制造逻辑，而双面组件设计更通过地面反射光捕获使发电量提升20%以上。", "target_word": "迭代", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "材料科学的进步使得复合材料得以广泛应用，不仅减轻了结构重量，还增强了疲劳耐久性；计算流体动力学（CFD）的发展则使工程师能够在虚拟风洞中模拟极端工况下的气动性能，从而在原型制造前完成多轮迭代。", "target_word": "迭代", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这款软件的每次迭代都修复了旧问题。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的迭代速度越来越快。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团队经过三轮迭代，终于完成了设计。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品迭代需要听取用户的意见。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术迭代让旧设备很快没人用了。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型经过多次迭代，效果好多了。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快速迭代是互联网公司的特点。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每一轮迭代之后，工程师都要做测试。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一轮迭代", "label": "量词搭配"}, {"form": "版本迭代", "label": "复合词"}, {"form": "快速迭代", "label": "复合词"}], "register": "书面", "sense_fingerprint": "技术、产品或方法不断更新改进的过程（版本升级）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0a0f57a-406e-4360-81b4-dcb946f1ae89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迭代", "is_correct": true, "explanation": "正确：“迭代”指材料不断更新改进的过程，与“推动光伏技术进入指数级进化”相合。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：色彩不能推动技术进化，与“指数级进化”的语境不合。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：尺寸大小不能推动光伏技术进步，与句中描述的技术突破不合。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味指闻到的味道，不能推动光伏技术进化，句意不通。"}], "explanations": {"迭代": "正确：“迭代”指材料不断更新改进的过程，与“推动光伏技术进入指数级进化”相合。", "色彩": "语义：色彩不能推动技术进化，与“指数级进化”的语境不合。", "尺寸": "语义：尺寸大小不能推动光伏技术进步，与句中描述的技术突破不合。", "气味": "语义：气味指闻到的味道，不能推动光伏技术进化，句意不通。"}, "sentence_index": 0, "correct_answer": "迭代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我们完成了一只迭代。", "explanation": "这里应该用〈轮〉。迭代的计量单位是“轮”，如“一轮迭代”；“只”多用于动物或成对的事物。"}, {"text": "公司今年的员工迭代了很多。", "explanation": "这里应该用〈增加〉。迭代指产品或技术反复更新，不能用来说人员数量变多，数量增长要用“增加”。"}, {"text": "这位工程师是公司的迭代。", "explanation": "迭代指更新改进的过程，不指人。这里要说人的身份，不能用“迭代”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迭代", "is_correct": true, "explanation": "正确：“迭代”指技术不断换新，与“旧设备很快没人用了”的因果相合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料与设备是否被淘汰无关，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与设备被淘汰没有因果关系，句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：人的年龄与设备被淘汰无关，句意不通。"}], "explanations": {"迭代": "正确：“迭代”指技术不断换新，与“旧设备很快没人用了”的因果相合。", "饮料": "语义：饮料与设备是否被淘汰无关，句意不通。", "颜色": "语义：颜色与设备被淘汰没有因果关系，句意不通。", "年龄": "语义：人的年龄与设备被淘汰无关，句意不通。"}, "sentence_index": 6, "correct_answer": "迭代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天发布了一台迭代。", "explanation": "这里应该用〈轮〉。迭代的计量用“轮”，“台”多用于机器，不用于更新的过程。"}, {"text": "他每天早上吃一碗迭代。", "explanation": "这里误用了词义：迭代指更新改进的过程，是抽象的，不能当作食物来吃。"}, {"text": "水的迭代让大地变得湿润。", "explanation": "这里应该用〈循环〉。迭代指技术、产品的版本更新，不用于自然界的水循环。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "团队经过两只迭代，终于完成了设计。", "corrected_sentence": "团队经过两轮迭代，终于完成了设计。", "error_description": "“迭代”的量词应为“轮”，应说“两轮迭代”。用“只”是错误的，“只”多用于动物或成对的事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每一迭代之后，工程师都要做检查。", "corrected_sentence": "每一轮迭代之后，工程师都要做检查。", "error_description": "“每一”后面必须接量词，“迭代”前应加量词“轮”，应说“每一轮迭代”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
