INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "控制技术是指通过一定的手段和方法，使系统或设备按照预定目标运行的技术。", "primary_collocate": null, "pronunciation": "kòng zhì jì shù", "ipa": "kʰʊŋ˥˩ ʈʂʐ̩˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "控制技术", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "现代工厂的生产离不开控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "furigana": "xiàn dài gōng chǎng de shēng chǎn lí bu kāi kòng zhì jì shù", "sentence_source": "generated"}, {"text": "这家公司研究飞机的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制技术能让机器人准确地完成工作。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的控制技术使火车更安全。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学专门学习控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "furigana": "tā zài dà xué zhuān mén xué xí kòng zhì jì shù", "sentence_source": "generated"}, {"text": "工程师用控制技术管理整个工厂的电力。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制技术的进步让生产更快。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统用了最新的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人驾驶汽车需要先进的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "使系统或设备按预定目标运行的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b5a66e-7b75-47f7-a8ec-a1433fb6fbd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说明书", "is_correct": false, "explanation": "语义：说明书不是可以被探索用于调节气流的手段，句意不通。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件不能用来实时调节气流，与后文的“边界层吸入”“合成射流”不符。"}, {"text": "控制技术", "is_correct": true, "explanation": "正确：“主动流动控制技术”指用主动手段调节气流的技术，与后文的“边界层吸入”“合成射流”一致。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“主动流动”修饰的是气流或流体，不能修饰价格。"}], "explanations": {"说明书": "语义：说明书不是可以被探索用于调节气流的手段，句意不通。", "文件": "语义：文件不能用来实时调节气流，与后文的“边界层吸入”“合成射流”不符。", "控制技术": "正确：“主动流动控制技术”指用主动手段调节气流的技术，与后文的“边界层吸入”“合成射流”一致。", "价格": "搭配：“主动流动”修饰的是气流或流体，不能修饰价格。"}, "sentence_index": 0, "correct_answer": "控制技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶的刺绣控制技术很高超。", "explanation": "这里应该用〈技艺〉。手工的精巧技能说技艺；控制技术指使机器或系统按预定目标运行的技术，不能用来形容刺绣。"}, {"text": "我在超市买了一斤控制技术。", "explanation": "这里应该用〈商品〉。超市卖的是商品；控制技术是抽象的技术，不能称重，也不能当商品买。"}, {"text": "这首歌的控制技术很动人。", "explanation": "控制技术指使机器或系统按目标运行的技术，不能用来形容歌曲的感染力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书", "is_correct": false, "explanation": "语义：书不能用来管理电力，句意不通。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不能用来管理电力，句意不通。"}, {"text": "控制技术", "is_correct": true, "explanation": "正确：“用……管理”要求一种手段，控制技术正是管理电力的方法，与句意一致。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“用……管理”后接的应是工具或方法，“感情”不能作为管理电力的手段。"}], "explanations": {"书": "语义：书不能用来管理电力，句意不通。", "礼物": "语义：礼物不能用来管理电力，句意不通。", "控制技术": "正确：“用……管理”要求一种手段，控制技术正是管理电力的方法，与句意一致。", "感情": "搭配：“用……管理”后接的应是工具或方法，“感情”不能作为管理电力的手段。"}, "sentence_index": 6, "correct_answer": "控制技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座大桥是一项大控制技术，建了五年。", "explanation": "这里应该用〈工程〉。建造桥梁这样的整体项目说工程；控制技术是一类技术，不指建造项目。"}, {"text": "我们在控制技术里吃了午饭。", "explanation": "这里应该用〈食堂〉。吃午饭要说在食堂这样的地点；控制技术是一种技术，不是地方，不能说“在……里”。"}, {"text": "工人用控制技术拧紧了螺丝。", "explanation": "这里应该用〈工具〉。拧螺丝要用扳手等工具；控制技术是一种方法，不能用来拧东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂引进了一台先进的控制技术。", "corrected_sentence": "这家工厂引进了一种先进的控制技术。", "error_description": "量词错误：错误形式为“一台”，正确形式为“一种”。“台”用于机器等设备，不能修饰抽象的技术；“控制技术”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位工程师把控制技术管好了整个工厂的电力。", "corrected_sentence": "这位工程师用控制技术管好了整个工厂的电力。", "error_description": "介词错误：错误形式为“把”，正确形式为“用”。控制技术是管理电力的手段，应由“用”引出；“把”后面的宾语应是被处理的对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
