INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "边界层指流体（如空气或水）流经固体表面时，在紧贴表面处形成的流速变化很大的薄层。", "primary_collocate": null, "pronunciation": "biān jiè céng", "ipa": "pjɛn˥ tɕjɛ˥˩ tsʰɤŋ˧˥", "syllable_count": 3, "sentences": [{"text": "研究人员在风洞里观察紧贴机翼的边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞行时，机翼表面会形成一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界层很薄，但是它会影响飞机的阻力。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气流过机翼时，边界层里的速度变化很大。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过大楼的墙面，墙边有一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流过船底，船底附近也有边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边界层越厚，空气流动就越不稳定。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在测量机翼上边界层的厚度。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车跑得很快，车身表面有一层边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验是为了研究管道里的边界层。", "target_word": "边界层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊界層", "label": "繁体"}, {"form": "层流边界层", "label": "复合"}, {"form": "湍流边界层", "label": "复合"}], "register": "书面语", "sense_fingerprint": "流体流过固体表面时紧贴表面、流速变化大的薄层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7250d00-77e8-4de8-a520-b9d293cc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边界层", "is_correct": true, "explanation": "“边界层”指紧贴固体表面的流体薄层，此处指紧贴机翼的那层气流，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是大气现象，不是紧贴机翼的薄层，句子说不通。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“行李”不是流体，不能紧贴机翼表面，句子说不通。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不是流体，不能紧贴机翼表面，句子说不通。"}], "explanations": {"边界层": "“边界层”指紧贴固体表面的流体薄层，此处指紧贴机翼的那层气流，句意通顺。", "天气": "语义：“天气”是大气现象，不是紧贴机翼的薄层，句子说不通。", "行李": "搭配：“行李”不是流体，不能紧贴机翼表面，句子说不通。", "乘客": "语义：乘客是人，不是流体，不能紧贴机翼表面，句子说不通。"}, "sentence_index": 0, "correct_answer": "边界层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个软件的边界层很漂亮。", "explanation": "这里应该用〈界面〉。界面指软件或设备供人操作和观看的部分，边界层指流体紧贴固体表面的薄层，不能用来形容软件外观。"}, {"text": "两国之间的边界层很清楚。", "explanation": "这里应该用〈边界〉。边界指两个地区之间的分界线，边界层指流体紧贴固体表面的薄层，不指国界。"}, {"text": "机翼表面有一条边界层。", "explanation": "这里的量词“条”用于细长的东西，如绳子、河流，不能用于边界层。边界层是紧贴表面的薄层，应该用量词“层”，说“一层边界层”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边界层", "is_correct": true, "explanation": "“边界层”指紧贴物体表面的流体薄层，“越厚，空气流动就越不稳定”说的正是它。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包的厚薄与空气流动的稳定性没有关系，句子说不通。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本的厚薄不会影响空气流动，句子说不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”可以说厚，但“越厚……空气流动越不稳定”里的因果不能由石头的厚度来承担。"}], "explanations": {"边界层": "“边界层”指紧贴物体表面的流体薄层，“越厚，空气流动就越不稳定”说的正是它。", "面包": "语义：面包的厚薄与空气流动的稳定性没有关系，句子说不通。", "书本": "语义：书本的厚薄不会影响空气流动，句子说不通。", "石头": "搭配：“石头”可以说厚，但“越厚……空气流动越不稳定”里的因果不能由石头的厚度来承担。"}, "sentence_index": 6, "correct_answer": "边界层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "土壤的边界层很肥沃。", "explanation": "这里应该用〈表层〉。表层指地表或土壤最外面的一层，边界层指流体紧贴固体表面的薄层，不指土壤。"}, {"text": "这个柜子的边界层可以放书。", "explanation": "这里应该用〈隔板〉。隔板指柜子内部分隔空间的板，可以放东西。边界层是流体紧贴固体表面的薄层，不能用来放书。"}, {"text": "这里的边界层很厚，有很多化石。", "explanation": "这里应该用〈地层〉。地层指地壳中成层的岩石，可以含有化石；边界层是流体的薄层，不是岩层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "薄薄的一条边界层紧贴着机翼表面。", "corrected_sentence": "薄薄的一层边界层紧贴着机翼表面。", "error_description": "量词错误：“边界层”应使用量词“层”，说“一层边界层”，不能说“一条边界层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "管道内壁附近常常有一根很薄的边界层。", "corrected_sentence": "管道内壁附近常常有一层很薄的边界层。", "error_description": "量词错误：“根”用于细长的东西，如绳子、木棍；边界层是紧贴表面的薄层，应使用量词“层”，说“一层很薄的边界层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼出", "is_correct": true, "explanation": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。"}, {"text": "演奏", "is_correct": false, "explanation": "“演奏”指表演乐器或乐曲，与“吸入”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指使损坏的东西恢复正常，与“吸入”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“吸入”没有反义关系。"}], "correct_answer": "呼出", "explanations": {"呼出": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。", "演奏": "“演奏”指表演乐器或乐曲，与“吸入”没有反义关系。", "修理": "“修理”指使损坏的东西恢复正常，与“吸入”没有反义关系。", "散步": "“散步”指随意走动，与“吸入”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼出", "is_correct": true, "explanation": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。"}, {"text": "擦拭", "is_correct": false, "explanation": "“擦拭”指擦掉表面的污物，与“吸入”没有反义关系。"}, {"text": "编织", "is_correct": false, "explanation": "“编织”指把线或条状物交错组合，与“吸入”没有反义关系。"}, {"text": "投掷", "is_correct": false, "explanation": "“投掷”指把东西用力扔出去，与“吸入”没有反义关系。"}], "correct_answer": "呼出", "explanations": {"呼出": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。", "擦拭": "“擦拭”指擦掉表面的污物，与“吸入”没有反义关系。", "编织": "“编织”指把线或条状物交错组合，与“吸入”没有反义关系。", "投掷": "“投掷”指把东西用力扔出去，与“吸入”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过呼吸将气体或细小颗粒物从外部引入体内。", "primary_collocate": null, "pronunciation": "xī rù", "ipa": "ɕi˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他戴着口罩走进车间，尽量少吸入粉尘。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心吸入了很多烟。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人吸入灰尘太多，开始咳嗽。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾时，人们容易吸入有毒的烟雾。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请戴上口罩，不要吸入脏空气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他吸入了一些化学气体。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吸入花粉后，一直打喷嚏。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸入太多灰尘对肺不好。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜水员在水下要吸入压缩空气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吸入了一口冷空气，咳了起来。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸入了", "label": "体标"}, {"form": "吸入过", "label": "体标"}, {"form": "吸入量", "label": "复合"}], "register": "书面语", "sense_fingerprint": "经呼吸把气体、粉尘等从外面吸进体内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7250d00-77e8-4de8-a520-b9d293cc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸入", "is_correct": true, "explanation": "“吸入”指经呼吸把粉尘等颗粒吸进体内，“尽量少吸入粉尘”句意通顺。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水去除污物，“少洗粉尘”与戴口罩防护的句意不符，句子说不通。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”的对象是文字，粉尘不能被“读”，句子说不通。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能与“粉尘”搭配，句子说不通。"}], "explanations": {"吸入": "“吸入”指经呼吸把粉尘等颗粒吸进体内，“尽量少吸入粉尘”句意通顺。", "洗": "语义：“洗”指用水去除污物，“少洗粉尘”与戴口罩防护的句意不符，句子说不通。", "读": "语义：“读”的对象是文字，粉尘不能被“读”，句子说不通。", "拍": "搭配：“拍”不能与“粉尘”搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "吸入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人体通过肠道吸入营养。", "explanation": "这里应该用〈吸收〉。吸收指从外界获取营养或水分，吸入指经呼吸把气体吸进体内，不能用于肠道获取营养。"}, {"text": "他渴了，吸入了一杯水。", "explanation": "这里应该用〈喝〉。喝指把液体送入口中咽下，吸入指经呼吸把气体吸进体内，不能用于水。"}, {"text": "磁铁能吸入铁钉。", "explanation": "这里应该用〈吸附〉。吸附指物体靠引力附着在另一物体上，吸入指经呼吸把气体或颗粒吸进体内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸入", "is_correct": true, "explanation": "“吸入”指经呼吸把花粉等颗粒吸进体内，与“打喷嚏”的句意相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”不能与“花粉”构成吸入的动作，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“花粉”作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "语义：花粉是颗粒，不能被“穿”，句子说不通。"}], "explanations": {"吸入": "“吸入”指经呼吸把花粉等颗粒吸进体内，与“打喷嚏”的句意相符。", "写": "语义：“写”不能与“花粉”构成吸入的动作，句子说不通。", "唱": "搭配：“唱”不能带“花粉”作宾语。", "穿": "语义：花粉是颗粒，不能被“穿”，句子说不通。"}, "sentence_index": 6, "correct_answer": "吸入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个节目吸入了很多观众。", "explanation": "这里应该用〈吸引〉。吸引指使人注意或喜爱，吸入指把气体吸进体内，不能用于观众。"}, {"text": "他慢慢吸入着面包。", "explanation": "这里应该用〈嚼〉。嚼指咀嚼食物，吸入指经呼吸把气体吸进身体，不能用于固体食物。"}, {"text": "他认真吸入比赛。", "explanation": "这里应该用〈观看〉。观看指用眼睛看，吸入指经呼吸把气体吸进体内，不能用于比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "沙尘暴来的时候，人们应该避免吸入了尘土。", "corrected_sentence": "沙尘暴来的时候，人们应该避免吸入尘土。", "error_description": "“了”误用：“避免”针对的是还没有发生的动作，“吸入”后不能加“了”，应说“避免吸入尘土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有吸入了这么冷的空气。", "corrected_sentence": "他从来没有吸入过这么冷的空气。", "error_description": "“了”误用：“从来没有”后表示经历要用“过”，应说“没有吸入过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "流体从窄口或小孔中高速喷出的现象或物质流。", "primary_collocate": null, "pronunciation": "shè liú", "ipa": "ʂɤ⁵¹ ljoʊ³⁵", "syllable_count": 2, "sentences": [{"text": "此外，主动流动控制技术，如边界层吸入或合成射流，正在被探索用于实时调节气流分离，进一步延展飞行包线。", "target_word": "射流", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "水从小孔里喷出来，形成一股射流。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "射流的速度很快，可以切开很硬的东西。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭发动机后面喷出一道长长的射流。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水枪喷出的射流可以打到十米远。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用高压射流清洗墙上的脏东西。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子很细，所以射流的力量特别大。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手指放在水管口，射流立刻变小了。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里的射流是用一台小泵产生的。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机发动机的射流会发出很大的声音。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水射流", "label": "复合"}, {"form": "射流泵", "label": "复合"}], "register": "专业", "sense_fingerprint": "射流：流体从窄口或小孔高速喷出的现象或物质流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "射流", "is_correct": true, "explanation": "“射流”指流体从窄口高速喷出的流，可用于调节气流分离，符合句意。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“合成”一般不与“电流”搭配，电流也不能直接调节气流分离。"}, {"text": "机翼", "is_correct": false, "explanation": "语义：机翼是飞机的承力部件，不是可以“合成”的流动控制手段，与“调节气流分离”不符。"}, {"text": "蛋白质", "is_correct": false, "explanation": "语义：蛋白质与气流无关，不能用来调节气流分离，与句中的技术语境矛盾。"}], "explanations": {"射流": "“射流”指流体从窄口高速喷出的流，可用于调节气流分离，符合句意。", "电流": "搭配：“合成”一般不与“电流”搭配，电流也不能直接调节气流分离。", "机翼": "语义：机翼是飞机的承力部件，不是可以“合成”的流动控制手段，与“调节气流分离”不符。", "蛋白质": "语义：蛋白质与气流无关，不能用来调节气流分离，与句中的技术语境矛盾。"}, "sentence_index": 0, "correct_answer": "射流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河里的射流很慢，一点儿也不急。", "explanation": "这里应该用〈水流〉。射流指从窄口或小孔高速喷出的流，缓慢流动的河水要用〈水流〉。"}, {"text": "春天的风带来了一股暖暖的射流。", "explanation": "这里应该用〈气流〉。射流是高速从窄口喷出的流，温和的春风要用〈气流〉。"}, {"text": "清晨的山谷里飘着一层白白的射流。", "explanation": "这里应该用〈雾气〉。射流是从窄口高速喷出的流，静静飘浮在山谷里的白色水汽要用〈雾气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "射流", "is_correct": true, "explanation": "“射流”是细而快速喷出的流，细管子里喷出的射流力量大，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流宽阔，不可能从很细的管子里产生，与“管子很细”矛盾。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪由风和潮汐形成，与“管子很细”的线索相矛盾。"}, {"text": "电压", "is_correct": false, "explanation": "搭配：形容电压一般说“高”或“低”，不说“力量特别大”。"}], "explanations": {"射流": "“射流”是细而快速喷出的流，细管子里喷出的射流力量大，符合句意。", "河流": "语义：河流宽阔，不可能从很细的管子里产生，与“管子很细”矛盾。", "海浪": "语义：海浪由风和潮汐形成，与“管子很细”的线索相矛盾。", "电压": "搭配：形容电压一般说“高”或“低”，不说“力量特别大”。"}, "sentence_index": 6, "correct_answer": "射流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山谷里的射流又宽又平，静静地铺在石头上。", "explanation": "这里应该用〈湖水〉。射流细而急，从窄口高速喷出，不能形容又宽又平、静静铺开的水面。"}, {"text": "山间的射流慢慢冒出来，清凉可口。", "explanation": "这里应该用〈泉水〉。射流是高速喷出的，不会慢慢冒出；缓缓涌出的清泉要用〈泉水〉。"}, {"text": "喷雾器轻轻喷出一股射流，很柔和。", "explanation": "这里应该用〈细雾〉。射流是高速喷出的强流，“轻轻”“很柔和”的喷出物要用〈细雾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座有力的射流从小孔里喷了出来。", "corrected_sentence": "一股有力的射流从小孔里喷了出来。", "error_description": "错误：“一座”。正确：“一股”。“座”用于山、建筑等大型固定之物，射流是流动的流体，应用“股”或“道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一块射流从管口喷了出来。", "corrected_sentence": "一道射流从管口喷了出来。", "error_description": "“一块射流”错，应为“一道射流”。“块”用于成块的固体，射流是喷出的流体，要用“道”“股”等量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结合", "is_correct": true, "explanation": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。"}, {"text": "保存", "is_correct": false, "explanation": "保存：指留存不失，与“分离”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与“分离”没有反义关系。"}, {"text": "加热", "is_correct": false, "explanation": "加热：指使东西温度升高，与“分离”没有反义关系。"}], "correct_answer": "结合", "explanations": {"结合": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。", "保存": "保存：指留存不失，与“分离”没有反义关系。", "观察": "观察：指仔细看，与“分离”没有反义关系。", "加热": "加热：指使东西温度升高，与“分离”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结合", "is_correct": true, "explanation": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。"}, {"text": "布置", "is_correct": false, "explanation": "布置：指安排、摆设，与“分离”没有反义关系。"}, {"text": "寻找", "is_correct": false, "explanation": "寻找：指设法找到，与“分离”没有反义关系。"}, {"text": "记录", "is_correct": false, "explanation": "记录：指把内容写下来，与“分离”没有反义关系。"}], "correct_answer": "结合", "explanations": {"结合": "结合：与“分离”相反，指把东西合在一起，是“分离”的反义词。", "布置": "布置：指安排、摆设，与“分离”没有反义关系。", "寻找": "寻找：指设法找到，与“分离”没有反义关系。", "记录": "记录：指把内容写下来，与“分离”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分开；使分开。", "primary_collocate": null, "pronunciation": "fēn lí", "ipa": "fən˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "离心机转动后，血液里的血浆和血细胞会分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室用机器把血液里的细胞分离出来。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油和水不能混在一起，很容易分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想把盐从海水中分离出来。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器可以分离牛奶和奶油。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水和沙子放久了就会分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用过滤的方法分离泥沙和水。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试管里的液体已经分离成两层。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把铁和石头分离开。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把蛋黄和蛋白分离，需要一点技巧。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分離", "label": "繁体"}, {"form": "分离了", "label": "体标"}, {"form": "分离出来", "label": "复合"}, {"form": "分离器", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把混合或连在一起的东西分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7250d00-77e8-4de8-a520-b9d293cc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分离", "is_correct": true, "explanation": "与听到的读音一致，fēn lí，意思是分开、使分开。"}, {"text": "奋力", "is_correct": false, "explanation": "fèn lì（第四声）与 fēn lí 的声调不同，意思是尽力、用力。"}, {"text": "分立", "is_correct": false, "explanation": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。"}, {"text": "分力", "is_correct": false, "explanation": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是物理学中的分解力。"}], "explanations": {"分离": "与听到的读音一致，fēn lí，意思是分开、使分开。", "奋力": "fèn lì（第四声）与 fēn lí 的声调不同，意思是尽力、用力。", "分立": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。", "分力": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是物理学中的分解力。"}, "sentence_index": null, "correct_answer": "分离"}, "level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：指血浆与血细胞被离心后分开，与“离心机转动后”的句意相符。"}, {"text": "爆炸", "is_correct": false, "explanation": "语义：“爆炸”指突然炸开，血浆和血细胞不会爆炸，句子说不通。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，血浆和血细胞不会融化，句子说不通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指用火使东西毁坏，与离心后分开的过程无关，句子说不通。"}], "explanations": {"分离": "分离：指血浆与血细胞被离心后分开，与“离心机转动后”的句意相符。", "爆炸": "语义：“爆炸”指突然炸开，血浆和血细胞不会爆炸，句子说不通。", "融化": "语义：“融化”指固体遇热变成液体，血浆和血细胞不会融化，句子说不通。", "烧毁": "语义：“烧毁”指用火使东西毁坏，与离心后分开的过程无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用一道墙把两个房间分离开。", "explanation": "这里应该用〈分隔〉。分离多指把混合或连在一起的东西拆开，用墙划分空间要用分隔。"}, {"text": "我们认真分离了这次事故的原因。", "explanation": "这里应该用〈分析〉。分离指把混合或连在一起的东西拆开，研究事故的原因要用分析。"}, {"text": "我把钱分离给了孩子。", "explanation": "这里应该用〈分给〉。分离是把混合或连着的东西拆开，分钱给孩子要用分给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：把混合物按成分分开，与“用过滤的方法”一致。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指用火使东西毁坏，与过滤的分离方法无关，句意不通。"}, {"text": "粉碎", "is_correct": false, "explanation": "搭配：“粉碎”的对象是固体，水不能被粉碎，不能与“和水”搭配。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指割取庄稼，泥沙和水不能被收割，句意不通。"}], "explanations": {"分离": "分离：把混合物按成分分开，与“用过滤的方法”一致。", "烧毁": "语义：“烧毁”指用火使东西毁坏，与过滤的分离方法无关，句意不通。", "粉碎": "搭配：“粉碎”的对象是固体，水不能被粉碎，不能与“和水”搭配。", "收割": "语义：“收割”指割取庄稼，泥沙和水不能被收割，句意不通。"}, "sentence_index": 6, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起分离了快乐。", "explanation": "这里应该用〈分享〉。分离指拆开或不再在一起，分享快乐要用分享。"}, {"text": "我们要分离真假。", "explanation": "这里应该用〈分辨〉。分离强调拆开，分清真假要用分辨。"}, {"text": "我们一起分离家务。", "explanation": "这里应该用〈分担〉。分离不表示共同承担，分担家务才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂用离心机把油从水里被分离出来。", "corrected_sentence": "工厂用离心机把油从水里分离出来。", "error_description": "“把”字句与“被”字句混用：“把”和“被”不能同时用在同一谓语前，应删去“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用分液漏斗把油和水分离了开。", "corrected_sentence": "用分液漏斗把油和水分离开了。", "error_description": "“了”的位置错误：“了”应放在补语“开”之后，写成“分离了开”是错误的，应为“分离开了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
