INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事物理学研究的人群，即物理学家群体。", "primary_collocate": null, "pronunciation": "wù lǐ xué jiè", "ipa": "u˥˩ li˨˩˦ ɕɥe˧˥ tɕje˥˩", "syllable_count": 4, "sentences": [{"text": "这些前沿技术的背后，是对纳维-斯托克斯方程组的深入求解，其非线性特性使得湍流建模至今仍是物理学界未完全攻克的难题。", "target_word": "物理学界", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个发现在物理学界引起了很大关注。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是物理学界很有名的科学家。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界一直在讨论这个问题。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授在物理学界工作了三十年。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界的专家都来参加这次会议。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究得到了物理学界的认可。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界对新理论有不同的看法。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的论文在物理学界受到了广泛的重视。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个奖项每年都会颁给物理学界的优秀学者。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理學界", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从事物理学研究的专业人群、物理学家群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91d27849-f17d-475a-ae9e-30e433cef473') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理学界", "is_correct": true, "explanation": "正确。“物理学界”指从事物理研究的群体，与句中前沿研究的语境相符。"}, {"text": "厨师界", "is_correct": false, "explanation": "语义：厨师界与纳维-斯托克斯方程组、湍流建模毫无关系，不会有“未完全攻克的难题”。"}, {"text": "文学界", "is_correct": false, "explanation": "语义：文学界的人不研究流体力学，句中的湍流建模与前沿技术语境不支持“文学界未完全攻克的难题”。"}, {"text": "江湖", "is_correct": false, "explanation": "语域：“江湖”带有武侠、口语色彩，与这句书面、学术性的表述不合。"}], "explanations": {"物理学界": "正确。“物理学界”指从事物理研究的群体，与句中前沿研究的语境相符。", "厨师界": "语义：厨师界与纳维-斯托克斯方程组、湍流建模毫无关系，不会有“未完全攻克的难题”。", "文学界": "语义：文学界的人不研究流体力学，句中的湍流建模与前沿技术语境不支持“文学界未完全攻克的难题”。", "江湖": "语域：“江湖”带有武侠、口语色彩，与这句书面、学术性的表述不合。"}, "sentence_index": 0, "correct_answer": "物理学界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位著名的物理学界。", "explanation": "这里应该用〈物理学家〉。“物理学界”指整个群体，不指某一个人，不能用“一位”来指一个人。"}, {"text": "这个物理学界有三十台仪器。", "explanation": "这里应该用〈实验室〉。“物理学界”指人群，不拥有仪器设备，说仪器的归属要用“实验室”。"}, {"text": "物理学界是高中的一门主要课程。", "explanation": "这里应该用〈物理学科〉。“物理学界”指从事研究的人群，不是课程或学科。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理学界", "is_correct": true, "explanation": "正确。“得到……的认可”的主体应是能做学术评价的群体，“物理学界”符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是场所，不能对研究做出“认可”，与这项研究的语境冲突。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：饭馆不是能做学术评价的群体，说它认可这项研究语义不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不能对研究做出“认可”，句子语义不通。"}], "explanations": {"物理学界": "正确。“得到……的认可”的主体应是能做学术评价的群体，“物理学界”符合语境。", "厨房": "语义：“厨房”是场所，不能对研究做出“认可”，与这项研究的语境冲突。", "饭馆": "语义：饭馆不是能做学术评价的群体，说它认可这项研究语义不通。", "蔬菜": "语义：蔬菜不能对研究做出“认可”，句子语义不通。"}, "sentence_index": 6, "correct_answer": "物理学界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物理学界的教学楼很新。", "explanation": "这里应该用〈物理学院〉。“物理学界”指人群，不是有教学楼的机构，不能说它有教学楼或校舍。"}, {"text": "这份物理学界每月出版一期。", "explanation": "这里应该用〈物理学术期刊〉。“物理学界”指人群，不是可以按期出版的刊物，不能说“每月出版一期”。"}, {"text": "他买了一本物理学界。", "explanation": "这里应该用〈物理学专著〉。“物理学界”指人群，不是可以买的书，买书要说“买了一本物理学专著”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在物理学界的很有名。", "corrected_sentence": "他在物理学界很有名。", "error_description": "“物理学界”后不应加“的”。“在物理学界”作状语，后面应直接接“很有名”，正确说法是“他在物理学界很有名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她物理学界很有声望。", "corrected_sentence": "她在物理学界很有声望。", "error_description": "介词漏用：“物理学界”作处所，前面要加介词“在”，应说“在物理学界”，漏掉“在”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
