INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12245, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "操纵、控制交通工具（如汽车、飞机等）使其运行或行驶。", "primary_collocate": null, "pronunciation": "jià shǐ", "ipa": "tɕja˥˩ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "值得注意的是，即便在人工智能高度集成的现代客机中，飞行员依然需要能够亲手驾驶飞机，因为空气动力学的基本物理规律不会因技术进步而改变。", "target_word": "驾驶", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他会驾驶飞机，也会驾驶轮船。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时驾驶过一艘大渔船。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员正在驾驶飞机降落。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有驾驶卡车的经验吗？", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位船长驾驶着货船穿过海峡。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想驾驶火箭去太空。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "驾驶大型客机需要很多年的训练。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次驾驶直升机，心里有点紧张。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他驾驶着小船慢慢靠近海岛。", "target_word": "驾驶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驾驶着", "label": "体标"}, {"form": "驾驶过", "label": "体标"}, {"form": "驾驶员", "label": "复合"}, {"form": "駕駛", "label": "繁体"}], "register": "中性", "sense_fingerprint": "驾驶|操纵飞机船只等交通工具使其运行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91d27849-f17d-475a-ae9e-30e433cef473') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12245, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。驾驶 jià shǐ，指操纵汽车、飞机、船只等交通工具使其运行。"}, {"text": "假使", "is_correct": false, "explanation": "jiǎ shǐ（第三声）与 jià shǐ（第四声）声调不同，意思是“假使”，表示假设。"}, {"text": "家事", "is_correct": false, "explanation": "jiā shì 与 jià shǐ 声调都不同，意思是“家里的事情”。"}, {"text": "加时", "is_correct": false, "explanation": "jiā shí 与 jià shǐ 两个音节声调都不同，意思是“比赛延长时间”。"}], "explanations": {"驾驶": "正确。驾驶 jià shǐ，指操纵汽车、飞机、船只等交通工具使其运行。", "假使": "jiǎ shǐ（第三声）与 jià shǐ（第四声）声调不同，意思是“假使”，表示假设。", "家事": "jiā shì 与 jià shǐ 声调都不同，意思是“家里的事情”。", "加时": "jiā shí 与 jià shǐ 两个音节声调都不同，意思是“比赛延长时间”。"}, "sentence_index": null, "correct_answer": "驾驶"}, "level_3": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。“亲手驾驶飞机”指飞行员直接操纵飞机，与句中“亲手”及现代客机的语境相符。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”是农业活动，与句中的现代客机、人工智能语境完全不合。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“哭泣”是人的情绪行为，不能以飞机为对象，“亲手哭泣飞机”不通。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”的主体是人或动物，不能以飞机为对象，句中不通。"}], "explanations": {"驾驶": "正确。“亲手驾驶飞机”指飞行员直接操纵飞机，与句中“亲手”及现代客机的语境相符。", "种植": "语义：“种植”是农业活动，与句中的现代客机、人工智能语境完全不合。", "哭泣": "搭配：“哭泣”是人的情绪行为，不能以飞机为对象，“亲手哭泣飞机”不通。", "游泳": "搭配：“游泳”的主体是人或动物，不能以飞机为对象，句中不通。"}, "sentence_index": 0, "correct_answer": "驾驶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他驾驶电脑完成了这项任务。", "explanation": "这里应该用〈操作〉。“驾驶”用于汽车、飞机、船只等交通工具，操作电脑要用“操作”。"}, {"text": "他每天驾驶自行车上班。", "explanation": "这里应该用〈骑〉。驾驶用于机动车、飞机、船只，自行车要用“骑”。"}, {"text": "汽车在高速公路上驾驶。", "explanation": "这里应该用〈行驶〉。“行驶”指车辆自己运行，车可以作主语；“驾驶”的动作者必须是人，汽车不能作“驾驶”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12245, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。驾驶 jià shǐ，指操纵交通工具使其运行。"}, {"text": "家史", "is_correct": false, "explanation": "jiā shǐ（第一声）与 jià shǐ（第四声）第一音节声调不同，意思是“家族的历史”。"}, {"text": "加湿", "is_correct": false, "explanation": "jiā shī 与 jià shǐ 两个音节声调都不同，意思是“增加空气湿度”。"}, {"text": "架势", "is_correct": false, "explanation": "jià shì 与 jià shǐ 第二音节声调不同（第四声与第三声），意思是“姿势、样子”。"}], "explanations": {"驾驶": "正确。驾驶 jià shǐ，指操纵交通工具使其运行。", "家史": "jiā shǐ（第一声）与 jià shǐ（第四声）第一音节声调不同，意思是“家族的历史”。", "加湿": "jiā shī 与 jià shǐ 两个音节声调都不同，意思是“增加空气湿度”。", "架势": "jià shì 与 jià shǐ 第二音节声调不同（第四声与第三声），意思是“姿势、样子”。"}, "sentence_index": null, "correct_answer": "驾驶"}, "level_3": {"options": [{"text": "驾驶", "is_correct": true, "explanation": "正确。“驾驶火箭”指操纵火箭，与“去太空”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：火箭不能吃，“吃火箭去太空”完全不合常理。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的受事要求有生命的对象，不能说“喂火箭”。"}, {"text": "嫁", "is_correct": false, "explanation": "配价：“嫁”的对象必须是人，不能说“嫁火箭”。"}], "explanations": {"驾驶": "正确。“驾驶火箭”指操纵火箭，与“去太空”的语境相符。", "吃": "语义：火箭不能吃，“吃火箭去太空”完全不合常理。", "喂": "配价：“喂”的受事要求有生命的对象，不能说“喂火箭”。", "嫁": "配价：“嫁”的对象必须是人，不能说“嫁火箭”。"}, "sentence_index": 6, "correct_answer": "驾驶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他驾驶着烈马慢慢走向河边。", "explanation": "这里应该用〈驾驭〉。驾驶用于交通工具，马要用“驾驭”。"}, {"text": "牧羊人驾驶羊群回家，很辛苦。", "explanation": "这里应该用〈驱赶〉。驾驶用于车船等交通工具，赶羊群要用“驱赶”。"}, {"text": "将军驾驶着部队慢慢靠近海岛。", "explanation": "这里应该用〈指挥〉。驾驶的对象是交通工具，部队要用“指挥”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他驾驶着很多次飞机。", "corrected_sentence": "他驾驶过很多次飞机。", "error_description": "体标误用：“很多次”表示过去的经历次数，要用经历体“过”，说“驾驶过很多次飞机”；持续体“着”不能和次数搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
